>\n  <sql>SELECT&#xd;\n   AVG(sorted_obs.cd4)&#xd;\nFROM&#xd;\n   (SELECT @rowindex:=@rowindex + 1 AS rowindex,&#xd;\n           o.value_numeric AS cd4&#xd;\n    FROM obs o&#xd;\n	where location_id = 16 &#xd;\n		  and o.concept_id = 1187&#xd;\n		  and MONTH(o.obs_datetime) = MONTH(DATE_ADD(now(), INTERVAL -2 MONTH))&#xd;\n    ORDER BY o.value_numeric) AS sorted_obs&#xd;\nWHERE&#xd;\nsorted_obs.rowindex IN (FLOOR(@rowindex / 2) , CEIL(@rowindex / 2));</sql>\n</org.openmrs.module.reporting.indicator.SqlIndicator>','2018-04-20 13:34:00',4,'2018-04-20 13:37:22',4,0,NULL,NULL,NULL,'a5979205-f1fa-4ebe-ad68-8e3f5d4d311a'),(154,'DM_Weight_Updated','patient weight','org.openmrs.module.reporting.indicator.dimension.Dimension','org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension id=\"1\" uuid=\"3cf562e6-0290-45c0-a999-6133791b0652\" retired=\"false\">\n  <name>DM_Weight_Updated</name>\n  <description>patient weight</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2018-06-05 07:42:11 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2018-06-05 07:45:30 UTC</dateChanged>\n  <parameters id=\"5\"/>\n  <id>154</id>\n  <cohortDefinitions class=\"tree-map\" id=\"6\">\n    <entry>\n      <string>03to3.9kg</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"7\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.NumericObsCohortDefinition\" id=\"8\" uuid=\"33a425d0-d6f9-42b8-8afe-08df159de8b7\"/>\n        <parameterMappings id=\"9\">\n          <entry>\n            <string>value2</string>\n            <double>3.9</double>\n          </entry>\n          <entry>\n            <string>value1</string>\n            <double>0.0</double>\n          </entry>\n        </parameterMappings>\n      <