ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4176))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\nAND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n							AND (os.location_id =:location  or parent_location =:location )							&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4247))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location ))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n		WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n		AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2210&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n					)&#xd;\n					 )&#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.Id not in (&#xd;\n				select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n	WHERE (o.location_id =:location  or parent_location =:location ))&#xd;\nand Id not in (&#xd;\n	                       select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n	                       -- CLIENTS NEWLY INITIATED ON ART&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0)&#xd;\nAND Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n					and obs_datetime &lt;= :endDate&#xd;\n                    group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n					and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)															  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate,interval 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\nAND Id not in(&#xd;\n				select distinct Id from&#xd;\n				(select distinct person_id as Id, max(value_datetime), datediff(CAST(:endDate AS DATE), max(value_datetime)) AS Num_Days&#xd;\n				FROM obs&#xd;\n				WHERE concept_id = 3752&#xd;\n				group by person_id&#xd;\n				HAVING Num_Days &gt;= 7) as finalised&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-10 00:00:16',4,'2019-05-09 09:27:52',4,0,NULL,NULL,NULL,'dc0406d3-2c3c-4157-ae83-537ae4e65e59');
INSERT INTO `serialized_object` VALUES (292,'Clients multi month 2d','2d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"4452e974-8c6e-442e-bb45-d6e09d26765a\" retired=\"false\">\n  <name>Clients multi month 2d</name>\n  <description>2d</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-10 00:01:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-09 09:29:04 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>292</id>\n  <query>SELECT DISTINCT Id&#xd;\nFROM&#xd;\n(&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n        from obs o&#xd;\n				-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n				  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND patient.voided = 0 AND o.voided = 0 &#xd;\n				  AND (o.concept_id = 4174 and o.value_coded in (4176,4177,4245,4246,4247))&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n				WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n				AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n			)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 2 MONTHS AND WAS GIVEN (3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177,4245,4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id &#xd;\n					 AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n	   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 3 MONTHS AND WAS GIVEN (4, 5, 6 MONTHS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245, 4246 ,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0		&#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 4 MONTHS AND WAS GIVEN (5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 5 MONTHS AND WAS GIVEN (6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND o.concept_id = 4174 and o.value_coded = 4247&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4175))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4176))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\nAND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n							AND (os.location_id =:location  or parent_location =:location )							&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4247))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location ))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n		WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n		AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 2209&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n					)&#xd;\n					 )&#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.Id not in (&#xd;\n				select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n	WHERE (o.location_id =:location  or parent_location =:location ))&#xd;\nand Id not in (&#xd;\n	                       select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n	                       -- CLIENTS NEWLY INITIATED ON ART&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0)&#xd;\nAND Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n					and obs_datetime &lt;= :endDate&#xd;\n                    group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n					and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)															  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate,interval 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\nAND Id not in(&#xd;\n				select distinct Id from&#xd;\n				(select distinct person_id as Id, max(value_datetime), datediff(CAST(:endDate AS DATE), max(value_datetime)) AS Num_Days&#xd;\n				FROM obs&#xd;\n				WHERE concept_id = 3752&#xd;\n				group by person_id&#xd;\n				HAVING Num_Days &gt;= 7) as finalised&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-10 00:01:21',4,'2019-05-09 09:29:04',4,0,NULL,NULL,NULL,'4452e974-8c6e-442e-bb45-d6e09d26765a'),(293,'Clients multi month 2e','2e','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"b70551ca-7dda-4d71-be21-852530c01b27\" retired=\"false\">\n  <name>Clients multi month 2e</name>\n  <description>2e</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-10 00:02:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-09 09:30:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>293</id>\n  <query>SELECT DISTINCT Id&#xd;\nFROM&#xd;\n(&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n        from obs o&#xd;\n				-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n				  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND patient.voided = 0 AND o.voided = 0 &#xd;\n				  AND (o.concept_id = 4174 and o.value_coded in (4176,4177,4245,4246,4247))&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n				WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n				AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n			)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 2 MONTHS AND WAS GIVEN (3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177,4245,4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id &#xd;\n					 AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n	   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 3 MONTHS AND WAS GIVEN (4, 5, 6 MONTHS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245, 4246 ,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0		&#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 4 MONTHS AND WAS GIVEN (5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 5 MONTHS AND WAS GIVEN (6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND o.concept_id = 4174 and o.value_coded = 4247&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4175))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4176))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\nAND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n							AND (os.location_id =:location  or parent_location =:location )							&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4247))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location ))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n		WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n		AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3674&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n					)&#xd;\n					 )&#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.Id not in (&#xd;\n				select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n	WHERE (o.location_id =:location  or parent_location =:location ))&#xd;\nand Id not in (&#xd;\n	                       select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n	                       -- CLIENTS NEWLY INITIATED ON ART&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0)&#xd;\nAND Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n					and obs_datetime &lt;= :endDate&#xd;\n                    group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n					and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)															  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate,interval 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\nAND Id not in(&#xd;\n				select distinct Id from&#xd;\n				(select distinct person_id as Id, max(value_datetime), datediff(CAST(:endDate AS DATE), max(value_datetime)) AS Num_Days&#xd;\n				FROM obs&#xd;\n				WHERE concept_id = 3752&#xd;\n				group by person_id&#xd;\n				HAVING Num_Days &gt;= 7) as finalised&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-10 00:02:30',4,'2019-05-09 09:30:24',4,0,NULL,NULL,NULL,'b70551ca-7dda-4d71-be21-852530c01b27'),(294,'Clients multi month 2f','2f','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7b572190-3a8e-41fd-9f13-b857c5a2d5a6\" retired=\"false\">\n  <name>Clients multi month 2f</name>\n  <description>2f</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-10 00:04:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-09 09:31:55 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>294</id>\n  <query>SELECT DISTINCT Id&#xd;\nFROM&#xd;\n(&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n        from obs o&#xd;\n				-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n				  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND patient.voided = 0 AND o.voided = 0 &#xd;\n				  AND (o.concept_id = 4174 and o.value_coded in (4176,4177,4245,4246,4247))&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n				WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n				AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n			)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 2 MONTHS AND WAS GIVEN (3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177,4245,4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id &#xd;\n					 AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n	   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 3 MONTHS AND WAS GIVEN (4, 5, 6 MONTHS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245, 4246 ,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0		&#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 4 MONTHS AND WAS GIVEN (5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 5 MONTHS AND WAS GIVEN (6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND o.concept_id = 4174 and o.value_coded = 4247&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4175))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4176))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\nAND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n							AND (os.location_id =:location  or parent_location =:location )							&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4247))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location ))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n		WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n		AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3675&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n					)&#xd;\n					 )&#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.Id not in (&#xd;\n				select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n	WHERE (o.location_id =:location  or parent_location =:location ))&#xd;\nand Id not in (&#xd;\n	                       select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n	                       -- CLIENTS NEWLY INITIATED ON ART&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0)&#xd;\nAND Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n					and obs_datetime &lt;= :endDate&#xd;\n                    group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n					and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)															  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate,interval 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\nAND Id not in(&#xd;\n				select distinct Id from&#xd;\n				(select distinct person_id as Id, max(value_datetime), datediff(CAST(:endDate AS DATE), max(value_datetime)) AS Num_Days&#xd;\n				FROM obs&#xd;\n				WHERE concept_id = 3752&#xd;\n				group by person_id&#xd;\n				HAVING Num_Days &gt;= 7) as finalised&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-10 00:04:54',4,'2019-05-09 09:31:55',4,0,NULL,NULL,NULL,'7b572190-3a8e-41fd-9f13-b857c5a2d5a6'),(295,'Clients multi month 2g','2g','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5aa75e1d-5ae4-47d7-9b0b-e099ecdfbde9\" retired=\"false\">\n  <name>Clients multi month 2g</name>\n  <description>2g</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-10 00:05:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-09 09:32:54 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>295</id>\n  <query>SELECT DISTINCT Id&#xd;\nFROM&#xd;\n(&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n        from obs o&#xd;\n				-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n				  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND patient.voided = 0 AND o.voided = 0 &#xd;\n				  AND (o.concept_id = 4174 and o.value_coded in (4176,4177,4245,4246,4247))&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n				WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n				AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3676&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n			)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 2 MONTHS AND WAS GIVEN (3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177,4245,4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id &#xd;\n					 AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-