 BETWEEN 0 AND 28&#xd;\n						AND (os.location_id = :location  or parent_location =  :location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 			&#xd;\n	WHERE (o.location_id = :location  or parent_location =  :location )&#xd;\n	and o.person_id in(&#xd;\n						select person_id from obs os&#xd;\n						where os.concept_id = 2250 &#xd;\n						and os.value_coded IN (2201,2203,2205,2207,3672,3673,2210,2209,3674,3675,3676,3677,3683,3684,3685,2202,2204,3679,3680,3681,3682,3686,2143)&#xd;\n					)&#xd;\n&#xd;\n	)						&#xd;\n) as regimen&#xd;\n&#xd;\nwhere Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 AND obs_datetime &lt; :endDate)													  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; :endDate &#xd;\n			and dead = 1&#xd;\n			)&#xd;\n) &#xd;\nas final</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-29 21:28:52',4,'2019-03-29 07:53:17',4,0,NULL,NULL,NULL,'4cdbc901-cea1-4995-84b6-0b6d46c49e03'),(333,'Appointment NOT scheduled','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.CodedObsCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.CodedObsCohortDefinition id=\"1\" uuid=\"b3da29d2-311a-4264-bef4-5b1b0629704e\" retired=\"false\">\n  <name>Appointment NOT scheduled</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-29 21:45:38 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>onOrAfter</name>\n      <label>startDate</label>\n