  <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.CodedObsCohortDefinition\" id=\"10\" uuid=\"44383c6e-b552-4703-9f88-faf374ff3b8e\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>locationList</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>onOrBefore</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>onOrAfter</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2019-01-29 22:00:24',4,'2019-01-29 22:01:08',4,0,NULL,NULL,NULL,'dc060565-40ef-4a71-b515-28cd018fb5d6'),(339,'Discordant couples SQL','Discordant couples','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"b3b772a7-7fc2-40d4-bbaa-8fe6e5eb9bd9\" retired=\"false\">\n  <name>Discordant couples SQL</name>\n  <description>Discordant couples</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 04:56:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-01-31 05:06:40 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>339</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.concept_id = 4225 and o.value_coded = 2146</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 04:56:06',4,'2019-01-31 05:06:40',4,0,NULL,NULL,NULL,'b3b772a7-7fc2-40d4-bbaa-8fe6e5eb9bd9'),(340,'ART Start date SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6f37715f-711c-48fa-8f56-e3360233d885\" retired=\"false\">\n  <name>ART Start date SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 08:49:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2022-05-19 08:30:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>340</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(SELECT  Id&#xd;\nFROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 and o.voided = 0&#xd;\n&#xd;\n						AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n						AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 and os.voided = 0 &#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS Newly_Initiated_ART_Clients&#xd;\nORDER BY Newly_Initiated_ART_Clients.Age)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 08:49:55',4,'2022-05-19 08:30:24',4,0,NULL,NULL,NULL,'6f37715f-711c-48fa-8f56-e3360233d885'),(341,'ART restart date SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f1a22112-f4e3-47eb-a3c8-beff0cc47bd4\" retired=\"false\">\n  <name>ART restart date SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 09:40:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-05-16 11:09:32 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>341</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN patient ON o.person_id = patient.patient_id&#xd;\nAND patient.voided = 0 AND o.voided = 0&#xd;\nAND o.person_id in(&#xd;\n		select person_id&#xd;\n		from&#xd;\n		(select o.person_id, max(o.obs_datetime) as seen_date, stopped_date&#xd;\n		from obs o&#xd;\n		inner join&#xd;\n			(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS stopped_date&#xd;\n				from obs oss&#xd;\n				inner join person p on oss.person_id=p.person_id&#xd;\n				and oss.concept_id = 3701 and oss.voided=0 -- ART stop date&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:startDate as date)&#xd;\n				group by p.person_id&#xd;\n				) as stopped_treatment&#xd;\n				on stopped_treatment.person_id = o.person_id&#xd;\n		where o.concept_id = 3753 and o.voided = 0 -- HIV followup form filled&#xd;\n		and cast(o.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n		and cast(o.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n		having datediff(seen_date, stopped_date) &gt; 30&#xd;\n		)stopped_treatment)&#xd;\n&#xd;\nOR o.person_id in&#xd;\n	(select person_id&#xd;\n	from(&#xd;\n		(select o.person_id, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_datetime)), 20) AS restarted_date, stopped_date&#xd;\n		from obs o&#xd;\n		inner join&#xd;\n			(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS stopped_date&#xd;\n				from obs oss&#xd;\n				inner join person p on oss.person_id=p.person_id&#xd;\n				and oss.concept_id = 3701 and oss.voided=0 -- ART stop date&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:startDate as date)&#xd;\n				group by p.person_id&#xd;\n				) as stopped_treatment&#xd;\n				on stopped_treatment.person_id = o.person_id&#xd;\n		where o.concept_id = 3708 and o.voided = 0 -- Date Restarted ART&#xd;\n		and cast(o.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n		and cast(o.value_datetime as date) &lt;= cast(:endDate as date)&#xd;\n		having datediff(restarted_date, stopped_date) &gt; 30&#xd;\n&#xd;\n		)&#xd;\n	)restarted)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 15:10:55',4,'2024-05-16 16:39:32',4,0,NULL,NULL,NULL,'f1a22112-f4e3-47eb-a3c8-beff0cc47bd4'),(342,'ART clients seen SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"092398d1-86b9-4486-97ff-2864ef7871e9\" retired=\"false\">\n  <name>ART clients seen SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 10:45:08 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-02-18 15:47:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>342</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id,&#xd;\n                                   patient_identifier.identifier AS patientIdentifier,&#xd;\n                                   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                                   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                                   person.gender AS Gender,&#xd;\n                                   observed_age_group.name AS age_group,&#xd;\n								   observed_age_group.sort_order AS sort_order&#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n								 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n									  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n									  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n           WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS NEWLY INITIATED ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 and o.voided = 0&#xd;\n					AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n					AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							and os.voided = 0&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752 and os.voided = 0&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266 and os.voided = 0&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)&#xd;\n							&#xd;\n							&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752 and os.voided = 0&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)	&#xd;\n											and voided = 0 	&#xd;\n						)&#xd;\n&#xd;\n						and o.voided = 0&#xd;\n					)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n					-- Visitors&#xd;\n								select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id IN (3753,6515)&#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate  as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and o.value_coded =1 and o.voided=0&#xd;\n									and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n&#xd;\n)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n		select distinct p.person_id as Id&#xd;\n		from person p&#xd;\n		where dead = 1&#xd;\n		and death_date &lt;= CAST(:endDate AS DATE)	&#xd;\n		and voided = 0&#xd;\n&#xd;\n)&#xd;\n&#xd;\nORDER BY Clients_Seen.Age)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 16:15:08',4,'2026-02-18 21:17:36',4,0,NULL,NULL,NULL,'092398d1-86b9-4486-97ff-2864ef7871e9'),(343,'ART Clients transferred in SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"08280ca8-e857-4730-8350-950ab55aee95\" retired=\"false\">\n  <name>ART Clients transferred in SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 10:53:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2022-04-28 13:11:52 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>343</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\nwhere o.concept_id = 2253 and o.voided = 0&#xd;\nand MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\nand YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 10:53:28',4,'2022-04-28 13:11:52',4,0,NULL,NULL,NULL,'08280ca8-e857-4730-8350-950ab55aee95'),(344,'ART Clients transferred out SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ab08b4d3-0971-427c-b3e9-8784299dbee7\" retired=\"false\">\n  <name>ART Clients transferred out SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 11:08:01 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-02-18 15:50:08 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>344</id>\n  <query>SELECT ID&#xd;\n	FROM&#xd;\n	(&#xd;\n		select active_clients.person_id as ID, active_clients.latest_follow_up&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id IN (3753,6515) -- Patient Register/Regimen&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752 -- Follow-up date&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where MONTH (active_clients.latest_follow_up) = MONTH(cast(:endDate as date)) &#xd;\n								and YEAR (active_clients.latest_follow_up) = YEAR(cast(:endDate as date))&#xd;\n								and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &gt;= 1&#xd;\n&#xd;\n	) AS NOT_ACTIVE&#xd;\nINNER JOIN&#xd;\n&#xd;\n(&#xd;\n	select B.person_id, B.obs_group_id&#xd;\n		from obs B&#xd;\n	inner join &#xd;\n			(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n				from obs where concept_id = 2403 -- HIV Treatment and Care Progress Template &#xd;\n				and obs_datetime &lt;= cast(:endDate as date)&#xd;\n				and voided = 0&#xd;\n			group by person_id) as A&#xd;\n			on A.observation_id = B.obs_group_id&#xd;\n			where concept_id = 	2398 -- Transferred out&#xd;\n			and A.observation_id = B.obs_group_id&#xd;\n            and voided = 0	&#xd;\n			group by B.person_id&#xd;\n&#xd;\n										&#xd;\n										&#xd;\n) AS TOUTS&#xd;\non TOUTS.person_id = NOT_ACTIVE.ID&#xd;\n&#xd;\nAND NOT_ACTIVE.ID not in (&#xd;\n						-- Died&#xd;\n												select distinct person_id &#xd;\n												from person &#xd;\n												where death_date &lt;= CAST(&apos;2022-03-31&apos; AS DATE)&#xd;\n												and dead = 1&#xd;\n&#xd;\n						)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-01-31 16:38:01',4,'2026-02-18 21:20:08',4,0,NULL,NULL,NULL,'ab08b4d3-0971-427c-b3e9-8784299dbee7'),(345,'Tx Curr Previous months SQL','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition id=\"1\" uuid=\"9563340e-e1d1-4725-bff2-e89edbf454e2\" retired=\"false\">\n  <name>Tx Curr Previous months SQL</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-01-31 11:21:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-01-31 11:24:10 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>345</id>\n  <compositionString>clients-given-multi-month-ARVs-3mnths OR clients-given-multi-month-ARVs-2-or-3mnths</compositionString>\n  <searches id=\"9\">\n    <entry