ery>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-03 19:37:54',4,'2019-02-03 20:31:26',4,0,NULL,NULL,NULL,'2b679b8c-165e-4dbe-8b9d-e7f685a6dae8'),(359,'Clients newly started on ART and IPT','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a10eb64a-10db-4cc9-a69a-e9659e634918\" retired=\"false\">\n  <name>Clients newly started on ART and IPT</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-03 19:59:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-02-03 20:09:02 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>359</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.concept_id = 2227&#xd;\nand o.value_coded = 2146&#xd;\nand o.person_id in&#xd;\n(&#xd;\nselect person_id&#xd;\nfrom obs&#xd;\nwhere concept_id = 2249&#xd;\nand obs_datetime &gt;=:startDate &#xd;\nand obs_datetime &lt;=:endDate&#xd;\n)&#xd;\nand o.obs_datetime &gt;=:startDate &#xd;\nand o.obs_datetime &lt;=:endDate;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-03 19:59:50',4,'2019-02-03 20:09:02',4,0,NULL,NULL,NULL,'a10eb64a-10db-4cc9-a69a-e9659e634918'),(360,'pre art test new diagnosed','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"44860f5e-0ce8-466d-8c01-c2ff60737256\" retired=\"false\">\n  <name>pre art test new diagnosed</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-04 07:51:40 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-02-04 07:56:11 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>360</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.concept_id = 2222&#xd;\nand o.person_id in&#xd;\n(&#xd;\nselect person_id&#xd;\nfrom obs&#xd;\nwhere concept_id = 2223&#xd;\nand obs_datetime &gt;=:startDate &#xd;\nand obs_datetime &lt;=:endDate&#xd;\n)&#xd;\nand o.person_id not in&#xd;\n(&#xd;\nselect person_id&#xd;\nfrom obs&#xd;\nwhere concept_id = 2249&#xd;\nand obs_datetime &gt;=:startDate &#xd;\nand obs_datetime &lt;=:endDate&#xd;\n)&#xd;\nand o.obs_datetime &gt;=:startDate &#xd;\nand o.obs_datetime &lt;=:endDate;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-04 07:51:40',4,'2019-02-04 07:56:11',4,0,NULL,NULL,NULL,'44860f5e-0ce8-466d-8c01-c2ff60737256'),(361,'pre art test newly enrolled','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"1796e0e3-bf74-436b-8b98-4258885a7d1f\" retired=\"false\">\n  <name>pre art test newly enrolled</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-04 08:07:56 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-02-04 08:14:46 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>361</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.concept_id = 2223&#xd;\nand o.person_id not in&#xd;\n(&#xd;\nselect person_id&#xd;\nfrom obs&#xd;\nwhere concept_id = 2249&#xd;\n)&#xd;\nand o.obs_datetime &gt;=:startDate &#xd;\nand o.obs_datetime &lt;=:endDate;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-04 08:07:56',4,'2019-02-04 08:14:46',4,0,NULL,NULL,NULL,'1796e0e3-bf74-436b-8b98-4258885a7d1f'),(362,'Clients seen in previous 1 through 6 months SQL','All clients seen in previous 1 through 6 months given multi month supply','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6f3593ef-a36c-4d2c-a10b-801b5bc8596b\" retired=\"false\">\n  <name>Clients seen in previous 1 through 6 months SQL</name>\n  <description>All clients seen in previous 1 through 6 months given multi month supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-04 13:45:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-02-18 11:45:52 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>362</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n    (SELECT Id, patientIdentifier , patientName, Age, Gender, age_group, &apos;Seen_Previous&apos; AS &apos;Program_Status&apos;, sort_order&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id IN (3753,6515)&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752 and voided = 0&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n									and B.voided = 0	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							and os.voided = 0&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249 and os.voided =0 &#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and os.voided = 0&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266 and os.voided = 0&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n									-- Visitors&#xd;\n								select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id IN (3753,6515) &#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and o.value_coded =1 and o.voided=0&#xd;\n									and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n&#xd;\n						)&#xd;\n						 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS Seen_Previous_ART_Clients&#xd;\nORDER BY Seen_Previous_ART_Clients.patientName)&#xd;\n)AS Seen_Prev)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-04 19:15:38',4,'2026-02-18 17:15:52',4,0,NULL,NULL,NULL,'6f3593ef-a36c-4d2c-a10b-801b5bc8596b'),(363,'Clients with baseline CD4 counts 12mnths','Clients with baseline CD4 counts 12mnths','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"fa2725bc-529d-43a8-8153-815da5e1cfca\" retired=\"false\">\n  <name>Clients with baseline CD4 counts 12mnths</name>\n  <description>Clients with basel