#xd;\n	AND o.concept_id = 2249 &#xd;\n	 AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n         AND YEAR(o.value_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n	AND o.voided = 0&#xd;\n	&#xd;\nand o.person_id in(&#xd;\n		select os.person_id&#xd;\n		from obs os&#xd;\n        -- All patients given x regimen during a particular period&#xd;\n		where os.concept_id = 2250 and os.value_coded = 3684&#xd;\n		AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    	AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\n					&#xd;\nand o.person_id not in ( -- remove transfer ins&#xd;\n   select os.person_id &#xd;\n   from obs os&#xd;\n   where os.concept_id = 3634 AND os.value_coded = 2095 &#xd;\n    AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\nAND person.voided = 0&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-07 08:21:56',4,'2021-01-27 15:14:28',4,0,NULL,NULL,NULL,'b447da00-0b30-4205-8027-ebe5951ed320'),(400,'Clients seen 4c','4c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"568c8c09-01b5-4a1c-8892-f558350b2abf\" retired=\"false\">\n  <name>Clients seen 4c</name>\n  <description>4c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-07 10:22:40 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-08 09:05:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>400</id>\n  <query>select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	inner join location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n        &#xd;\nWHERE (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\n		select distinct person_id&#xd;\n		from obs&#xd;\n        -- All patients given 1F regimen during a particular period&#xd;\n		where concept_id = 2250 and value_coded = 2202&#xd;\n		AND obs_datetime between :startDate AND :endDate&#xd;\n)&#xd;\nand patient.patient_id not in  -- CLIENTS NEWLY INITIATED ON ART&#xd;\n	                       (select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0&#xd;\n							and patient.patient_id not in(&#xd;\n														select distinct os.person_id from obs os															 &#xd;\n														where os.concept_id = 2396 														 &#xd;\n														AND DATE(os.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							&#xd;\n							)&#xd;\nAND o.person_id not in (																 &#xd;\n						select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n                    and obs_datetime &lt;= :endDate&#xd;\n					group by person_id) one,&#xd;\n					&#xd;\n					(select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n                    and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)													 &#xd;\n                        )&#xd;\n&#xd;\nAND patient.patient_id not in &#xd;\n			(&#xd;\n			select distinct person_id &#xd;\n			from person&#xd;\n			where death_date &lt;=	 :endDate&#xd;\n			and dead = 1&#xd;\n			)						&#xd;\n				&#xd;\n														</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-07 10:22:40',4,'2019-05-08 09:05:39',4,0,NULL,NULL,NULL,'568c8c09-01b5-4a1c-8892-f558350b2abf'),(401,'Clients seen 4d','4d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"df3b2c47-8c25-4a90-a9cf-4a98a52d87de\" retired=\"false\">\n  <name>Clients seen 4d</name>\n  <description>4d</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-07 10:24:59 UTC</dateCreated>\n  <changedBy