cept_id = 2250 and value_coded = 3685&#xd;\n		AND obs_datetime between :startDate AND :endDate&#xd;\n)&#xd;\nand patient.patient_id not in  -- CLIENTS NEWLY INITIATED ON ART&#xd;\n	                       (select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0&#xd;\n							and patient.patient_id not in(&#xd;\n														select distinct os.person_id from obs os															 &#xd;\n														where os.concept_id = 2396 														 &#xd;\n														AND DATE(os.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							&#xd;\n							)&#xd;\nAND o.person_id not in (																 &#xd;\n						select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n                    and obs_datetime &lt;= :endDate&#xd;\n					group by person_id) one,&#xd;\n					&#xd;\n					(select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n                    and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)													 &#xd;\n                        )&#xd;\n&#xd;\nAND patient.patient_id not in &#xd;\n			(&#xd;\n			select distinct person_id &#xd;\n			from person&#xd;\n			where death_date &lt;=	 :endDate&#xd;\n			and dead = 1&#xd;\n			)						&#xd;\n				&#xd;\n														</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-07 13:35:11',4,'2019-05-08 10:38:50',4,0,NULL,NULL,NULL,'604a75e1-4aac-413b-be90-3c3f5f0e1506'),(408,'Clients multi month 3c','3c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"30fa519d-6d87-453f-a68f-fbfe97d650b9\" retired=\"false\">\n  <name>Clients multi month 3c</name>\n  <description>3c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-07 13:57:32 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-05-09 09:40:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>408</id>\n  <query>SELECT DISTINCT Id&#xd;\nFROM&#xd;\n(&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n        from obs o&#xd;\n				-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n				  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n				  AND patient.voided = 0 AND o.voided = 0 &#xd;\n				  AND (o.concept_id = 4174 and o.value_coded in (4176,4177,4245,4246,4247))&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n				WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n				AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n			)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 2 MONTHS AND WAS GIVEN (3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177,4245,4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id &#xd;\n					 AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n	   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 3 MONTHS AND WAS GIVEN (4, 5, 6 MONTHS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245, 4246 ,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0		&#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 4 MONTHS AND WAS GIVEN (5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n				 INNER JOIN location l on o.location_id = l.location_id					 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246,4247))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n				-- CAME IN PREVIOUS 5 MONTHS AND WAS GIVEN (6 MONHTS SUPPLY OF DRUGS)&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND o.concept_id = 4174 and o.value_coded = 4247&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4175))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -1 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -1 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4176))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -2 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -2 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\n		   &#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4177))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location ) &#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -3 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -3 MONTH))&#xd;\n					)&#xd;\n				)&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4245))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location )								&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\nAND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -4 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -4 MONTH))&#xd;\n					)					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id				 &#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4246))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN location l on os.location_id = l.location_id	&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n							AND (os.location_id =:location  or parent_location =:location )							&#xd;\n					 )&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n					WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n					AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -5 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -5 MONTH))&#xd;\n					)&#xd;\n					&#xd;\n				)&#xd;\n&#xd;\n&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n                from obs o&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 INNER JOIN location l on o.location_id = l.location_id&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n					 AND patient.voided = 0 AND o.voided = 0 &#xd;\n					 AND (o.concept_id = 4174 and o.value_coded in (4247))&#xd;\n					 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where &#xd;\n							MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n							AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						    AND (os.location_id =:location  or parent_location =:location ))&#xd;\n					 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 &#xd;\n		WHERE (o.location_id =:location  or parent_location =:location )&#xd;\n		AND o.person_id in (&#xd;\n						select distinct person_id&#xd;\n						from obs&#xd;\n						-- All patients given 1F regimen during a particular period&#xd;\n						where concept_id = 2250 and value_coded = 3685&#xd;\n						AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -6 MONTH)) &#xd;\n						AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -6 MONTH))&#xd;\n					)&#xd;\n					 )&#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.Id not in (&#xd;\n				select distinct patient.patient_id&#xd;\nfrom obs o&#xd;\n-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN location l on o.location_id = l.location_id&#xd;\n	INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n	AND (DATE(o.obs_datetime) BETWEEN :startDate AND :endDate)&#xd;\n	AND patient.voided = 0 AND o.voided = 0&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n	WHERE (o.location_id =:location  or parent_location =:location ))&#xd;\nand Id not in (&#xd;\n	                       select distinct patient.patient_id AS Id&#xd;\n	                       from obs o&#xd;\n	                       -- CLIENTS NEWLY INITIATED ON ART&#xd;\n							INNER JOIN patient ON o.person_id = patient.patient_id													&#xd;\n							AND (o.concept_id = 2249 AND DATE(o.value_datetime) BETWEEN :startDate AND :endDate)&#xd;\n							AND patient.voided = 0 AND o.voided = 0)&#xd;\nAND Id not in (																		 &#xd;\n                &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n					and obs_datetime &lt;= :endDate&#xd;\n                    group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 &#xd;\n					and obs_datetime &lt;= :endDate) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)															  														 							 &#xd;\n              )&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate,interval 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\nAND Id not in(&#xd;\n				select distinct Id from&#xd;\n				(select distinct person_id as Id, max(value_datetime), datediff(CAST(:endDate AS DATE), max(value_datetime)) AS Num_Days&#xd;\n				FROM obs&#xd;\n				WHERE concept_id = 3752&#xd;\n				group by person_id&#xd;\n				HAVING Num_Days &gt;= 7) as finalised&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-07 13:57:32',4,'2019-05-09 09:40:39',4,0,NULL,NULL,NULL,'30fa519d-6d87-453f-a68f-fbfe97d650b9'),(409,'Clients seen given 1 month supply 4c','4c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"537bfeb1-7f85-4387-81c1-79f35d6b8193\" retired=\"false\">\n  <name>Clients seen given 1 month supply 4c</name>\n  <description>4c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-07 14:01:00 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-02-04 07:31:35 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>409</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT person_id&#xd;\nFROM( (&#xd;\n		SELECT person_id &#xd;\n					FROM( &#xd;\n						SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) as ARV_regimen&#xd;\n						FROM&#xd;\n						(&#xd;\n							select distinct o.person_id,o.value_coded as current_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2250&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2250 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n						)currentreg&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as substitute_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 4284&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 4284 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)substitutereg ON currentreg.person_id = substitutereg.person_id&#xd;\n&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as switch_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2268&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2268 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)switchreg ON currentreg.person_id = switchreg.person_id&#xd;\n								)regimen &#xd;\n								WHERE ARV_regimen = 2202) &#xd;\nUNION&#xd;\n&#xd;\n(SELECT distinct person_id&#xd;\nFROM(SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n                FROM(SELECT o.person_id,o.value_coded as current_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2250&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as substitute_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 4284&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n		LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as switch_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2268&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id			&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 2202&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n															and CAST(oss.obs_datetime AS DATE) &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(CAST(os.value_datetime AS DATE)), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(CAST(os.value_datetime AS DATE)) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-02-07 14:01:00',4,'2021-02-04 07:31:35',4,0,NULL,NULL,NULL,'537bfeb1-7f85-4387-81c1-79f35d6b8193'),(410,'Clients seen given 1 month supply 4d','4d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.modul