efinition id=\"1\" uuid=\"8f521b14-95ad-4e4c-b03d-10c0b7b3a0aa\" retired=\"false\">\n  <name>clients seen 2 to 6mnths ago</name>\n  <description>composition</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-02-27 10:59:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-02-27 14:18:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>441</id>\n  <compositionString>clients-seen-3months-ago OR clients-seen-2months-ago</compositionString>\n  <searches id=\"9\">\n    <entry>\n      <string>clients-seen-3months-ago</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"10\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"11\" uuid=\"21c776ca-7cbc-4388-a623-06e351469a20\"/>\n        <parameterMappings id=\"12\">\n          <entry>\n            <string>endDate</string>\n            <string>${endDate}</string>\n          </entry>\n          <entry>\n            <string>location</string>\n            <string>${location}</string>\n          </entry>\n          <entry>\n            <string>startDate</string>\n            <string>${startDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </searches>\n</org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition>','2019-02-27 10:59:28',4,'2019-02-27 14:18:26',4,0,NULL,NULL,NULL,'8f521b14-95ad-4e4c-b03d-10c0b7b3a0aa'),(442,'Clients on ARV who died','Clients on ARV who died','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"914d4f42-66e2-4fce-b1da-d3fce7f95f15\" retired=\"false\">\n  <name>Clients on ARV who died</name>\n  <description>Clients on ARV who died</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-03-29 06:48:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2022-04-28 08:21:40 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>442</id>\n  <query>select person_id &#xd;\n	from person &#xd;\n	where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n	AND MONTH(death_date) = MONTH(CAST(:endDate AS DATE))&#xd;\n	AND YEAR(death_date) =  YEAR(CAST(:endDate AS DATE))&#xd;\n	and dead = 1</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-03-29 06:48:55',4,'2022-04-28 08:21:40',4,0,NULL,NULL,NULL,'914d4f42-66e2-4fce-b1da-d3fce7f95f15'),(443,'Clients given 2weeks ARV','Clients given 2weeks ARV','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d8bb0175-47c0-461b-b457-498c8ef3cf27\" retired=\"false\">\n  <name>Clients given 2weeks ARV</name>\n  <description>Clients given 2weeks ARV</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-03-29 07:53:59 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-03-29 07:57:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>443</id>\n  <query>select distinct Id from(&#xd;\nselect distinct Id from&#xd;\n(&#xd;\n	(select distinct o.person_id AS Id&#xd;\n	from obs o &#xd;\n	inner join location l on o.location_id = l.location_id&#xd;\n	where (o.location_id = :location or parent_location = :location)&#xd;\n	and o.concept_id = 2250 &#xd;\n	and o.value_coded in (2201,2203,2205,2207,3672,3673,2210,2209,3674,3675,3676,3677,3683,3684,3685,2202,2204,3679,3680,3681,3682,3686,2143)&#xd;\n	and o.person_id in (&#xd;\n				select distinct o.person_id&#xd;\n				from obs o &#xd;\n				where (o.concept_id = 4174 and o.value_coded = 4243)&#xd;\n				and obs_datetime BETWEEN :startDate and DATE_ADD(:endDate, INTERVAL 1 DAY)&#xd;\n				)&#xd;\n	&#xd;\n	and o.voided = 0&#xd;\n	and obs_datetime BETWEEN :startDate and DATE_ADD(:endDate, INTERVAL 1 DAY)&#xd;\n	)&#xd;\n	UNION&#xd;\n(select distinct patient.patient_id AS Id&#xd;\n     from obs o&#xd;\n     INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n	 INNER JOIN location l on o.location_id = l.location_id	&#xd;\n	 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -28 DAY))&#xd;\n	 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -28 DAY)) &#xd;\n	 AND patient.voided = 0 AND o.voided = 0 &#xd;\n	 AND (o.concept_id = 4174 and o.value_coded = 4243)&#xd;\n	 AND o.person_id in (&#xd;\n						select distinct os.person_id from obs os&#xd;\n						INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n						INNER JOIN location l on os.location_id = l.location_id						&#xd;\n						where MONTH(os.obs_datetime) = MONTH(DATE_ADD(:endDate, INTERVAL -28 DAY)) &#xd;\n						AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(:endDate, INTERVAL -28 DAY))&#xd;\n						AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, :endDate) BETWEEN 0 AND 28&#xd;\n						AND (os.location_id = :location  or parent_location = :location )&#xd;\n					 )&#xd;\n	INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0				 			&#xd;\n	WHERE (o.location_id = :location  or parent_location = :location )&#xd;\n	and o.person_id in(&#xd;\n						select distinct person_id from obs os&#xd;\n						where os.concept_id = 2250 &#xd;\n						and os.value_coded in (2201,2203,2205,2207,3672,3673,2210,2209,3674,3675,3676,3677,3683,3684,3685,2202,2204,3679,3680,3681,3682,3686,2143)&#xd;\n					)&#xd;\n	)&#xd;\n) as regimen&#xd;\nwhere Id not in (																		 &#xd;\n				select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; DATE_ADD(:endDate, INTERVAL 1 DAY))													  														 							 &#xd;\n				)&#xd;\nAND Id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt; DATE_ADD(:endDate, INTERVAL 1 DAY) &#xd;\n			and dead = 1&#xd;\n			)&#xd;\n	)as final</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-03-29 07:53:59',4,'2019-03-29 07:57:45',4,0,NULL,NULL,NULL,'d8bb0175-47c0-461b-b457-498c8ef3cf27'),(445,'Total 1F Data Set',NULL,'org.openmrs.module.reporting.dataset.definition.DataSetDefinition','org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition id=\"1\" uuid=\"9169293f-f54e-4905-a477-15f43395d28a\" retired=\"false\">\n  <name>Total 1F Data Set</name>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-04-24 08:11:13 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-04-24 08:14:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>445</id>\n  <dimensions id=\"9\">\n    <entry>\n      <string>DM_Sex</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"10\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension\" id=\"11\" uuid=\"dec74189-72cc-4981-b956-557f37b82a87\"/>\n        <parameterMappings id=\"12\"/>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </dimensions>\n  <columns id=\"13\">\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"14\">\n      <name>1Line1fF</name>\n      <label>CI07: Adults 1st Line ARV Regimen 1(f)TDF-3TC-EFV-Females</label>\n      <indicator id=\"15\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.CohortIndicator\" id=\"16\" uuid=\"1f6b7448-9557-4335-8d9c-3d1310626aa0\"/>\n        <parameterMappings id=\"17\">\n          <entry>\n            <string>endDate</string>\n            <string>${endDate}</string>\n          </entry>\n          <entry>\n            <string>location</string>\n            <string>${location}</string>\n          </entry>\n          <entry>\n            <string>startDate</string>\n            <string>${startDate}</string>\n          </entry>\n        </parameterMappings>\n      </indicator>\n      <dimensionOptions id=\"18\">\n        <entry>\n          <string>DM_Sex</string>\n          <string>Females</string>\n        </entry>\n      </dimensionOptions>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"19\">\n      <name>1stLine1FM</name>\n      <label>CI07: Adults 1st Line ARV Regimen 1(f)TDF-3TC-EFV-Males</label>\n      <indicator reference=\"15\"/>\n      <dimensionOptions id=\"20\">\n        <entry>\n          <string>DM_Sex</string>\n          <string>Males</string>\n        </entry>\n      </dimensionOptions>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n  </columns>\n</org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition>','2019-04-24 08:11:13',4,'2019-04-24 08:14:21',4,0,NULL,NULL,NULL,'9169293f-f54e-4905-a477-15f43395d28a'),(446,'SQL Version Total Clients Registered for ART','SQL Version Total Clients Registered for ART','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"dabb33fe-f6f9-479c-82a0-d93c5a681b36\" retired=\"false\">\n  <name>SQL Version Total Clients Registered for ART</name>\n  <description>SQL Version Total Clients Registered for ART</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-07-10 12:51:51 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-10-17 14:02:12 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>446</id>\n  <query>	SELECT distinct p.person_id AS Id&#xd;\n		FROM person p&#xd;\n			INNER JOIN obs o ON o.person_id = p.person_id &#xd;\n				AND o.voided = 0 &#xd;\n				AND o.person_id in &#xd;\n				         (select person_id from obs where concept_id = 2403 and voided = 0) &#xd;\n				AND o.person_id not in &#xd;\n						 (select person_id from obs where concept_id = 5416 and value_coded = 1 and voided = 0)&#xd;\n			INNER JOIN person_name pn ON p.person_id = pn.person_id&#xd;\n			INNER JOIN patient_identifier pi1 ON pi1.patient_id = p.person_id AND pi1.voided = 0 and pi1.preferred = 1 &#xd;\n				AND pi1.identifier_type = 3&#xd;\n			LEFT JOIN patient_identifier pi2 ON pi2.patient_id = p.person_id AND pi2.identifier_type in (5,12)&#xd;\n			JOIN location l on o.location_id = l.location_id and l.retired=0&#xd;\n		WHERE p.voided = 0&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n		SELECT distinct o.person_id AS Id		&#xd;\n		FROM obs o&#xd;\n			INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n			INNER JOIN patient_identifier p ON o.person_id = p.patient_id&#xd;\n			INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n			INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n			INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3&#xd;\n			JOIN location l on o.location_id = l.location_id and l.retired=0&#xd;\n			WHERE p.identifier_type in (5,12) &#xd;\n			AND o.voided = 0&#xd;\n			AND o.person_id not in (select person_id from obs where concept_id = 2403 and voided = 0)&#xd;\n			group by patient_identifier.identifier</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-07-10 18:21:51',4,'2023-10-17 19:32:12',4,0,NULL,NULL,NULL,'dabb33fe-f6f9-479c-82a0-d93c5a681b36'),(447,'SQL Version Total Registered ART Client with Intakes captured','SQL Version Total Registered ART Client with Intakes captured','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f7926250-cdd1-4446-9106-bfe81ce908f5\" retired=\"false\">\n  <name>SQL Version Total Registered ART Client with Intakes captured</name>\n  <description>SQL Version Total Registered ART Client with Intakes captured</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-07-11 01:08:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-10-17 14:21:57 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>447</id>\n  <query>	SELECT distinct p.person_id AS Id&#xd;\n		FROM person p&#xd;\n			INNER JOIN obs o ON o.person_id = p.person_id &#xd;\n				AND o.voided = 0 &#xd;\n				AND o.person_id in &#xd;\n				         (select person_id from obs where concept_id = 2249 and voided = 0) &#xd;\n				AND o.person_id not in &#xd;\n						 (select person_id from obs where concept_id = 5416 and value_coded = 1 and voided = 0)&#xd;\n			INNER JOIN person_name pn ON p.person_id = pn.person_id&#xd;\n			INNER JOIN patient_identifier pi1 ON pi1.patient_id = p.person_id AND pi1.voided = 0 and pi1.preferred = 1 &#xd;\n				AND pi1.identifier_type = 3&#xd;\n			LEFT JOIN patient_identifier pi2 ON pi2.patient_id = p.person_id AND pi2.identifier_type in (5,12)&#xd;\n			JOIN location l on o.location_id = l.location_id and l.retired=0&#xd;\n		WHERE p.voided = 0&#xd;\n		AND concept_id = 2403&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n		SELECT distinct o.person_id AS Id		&#xd;\n		FROM obs o&#xd;\n			INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n			INNER JOIN patient_identifier p ON o.person_id = p.patient_id&#xd;\n			INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n			INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n			INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3&#xd;\n			JOIN location l on o.location_id = l.location_id and l.retired=0&#xd;\n			WHERE p.identifier_type in (5,12) &#xd;\n			AND o.voided = 0&#xd;\n			AND o.person_id not in (select person_id from obs where concept_id = 2403 and voided = 0)&#xd;\n			AND concept_id = 2249&#xd;\n			group by patient_identifier.identifier</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2019-07-11 06:38:18',4,'2023-10-17 19:51:57',4,0,NULL,NULL,NULL,'f7926250-cdd1-4446-9106-bfe81ce908f5'),(448,'CI36: Total Registered ART Clients','','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"860c7123-a8a4-46d1-8c5e-2c33ac1a2632\" retired=\"false\">\n  <name>CI36: Total Registered ART Clients</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2019-07-11 01:17:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2019-07-11 01:21:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>448</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"dabb33fe-f6f9-479c-82a0-d93c5a681b36\"/>\n    <parameterMa