\n  <description>repeating clients who tested positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-04-24 12:50:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2020-04-24 12:50:52 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>467</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"9bba9c3a-f886-477f-997f-a7325a668ee7\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-04-24 12:50:04',4,'2020-04-24 12:50:52',4,0,NULL,NULL,NULL,'e359947f-9dd8-490f-a1c2-056afb801816'),(468,'CITC_Repeat_Positive','repeat clients tested positve','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"3b0f9835-29a4-418d-aaa6-3f8f1d141ece\" retired=\"false\">\n  <name>CITC_Repeat_Positive</name>\n  <description>repeat clients tested positve</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-04-27 05:28:31 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:26:07 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>468</id>\n  <query>SELECT DISTINCT p.patient_id AS Id&#xd;\nFROM patient p&#xd;\nJOIN person per ON per.person_id = p.patient_id AND per.voided = 0&#xd;\nJOIN obs res&#xd;\n  ON res.person_id = p.patient_id&#xd;\n AND res.concept_id = 2165            -- HTC, Final HIV status&#xd;\n AND res.value_coded = 1738           -- Positive&#xd;\n AND res.voided = 0&#xd;\n AND res.obs_datetime BETWEEN :startDate AND :endDate&#xd;\n-- (optional) ensure result is within an HTS form&#xd;\nJOIN obs htsgrp&#xd;\n  ON htsgrp.obs_id = res.obs_group_id&#xd;\n AND htsgrp.concept_id = 2385        -- HTC, Post-test Counseling Set&#xd;\n AND htsgrp.voided = 0&#xd;\nJOIN obs pitc&#xd;\n  ON pitc.person_id = p.patient_id&#xd;\n AND pitc.concept_id = 4228           -- Initiated Testing and Counseling?&#xd;\n AND pitc.value_coded = 4226          -- CITC&#xd;\n AND pitc.voided = 0&#xd;\n AND pitc.obs_datetime BETWEEN :startDate AND :endDate&#xd;\nJOIN obs newf&#xd;\n  ON newf.person_id = p.patient_id&#xd;\n AND newf.concept_id = 4798           -- HTC, History of Previous Testing?&#xd;\n AND newf.value_coded = 2146          -- Yes&#xd;\n AND newf.voided = 0&#xd;\n AND newf.obs_datetime BETWEEN :startDate AND :endDate&#xd;\nWHERE p.voided = 0&#xd;\n  AND (&#xd;\n    res.location_id = :location&#xd;\n    OR EXISTS (SELECT 1 FROM location l WHERE l.location_id = res.location_id AND l.parent_location = :location)&#xd;\n  )&#xd;\n  -- exclude anyone with a NEW flag in the same period&#xd;\n  AND NOT EXISTS (&#xd;\n    SELECT 1 FROM obs rep&#xd;\n    WHERE rep.person_id = p.patient_id&#xd;\n      AND rep.concept_id = 4798       -- HTC, History of Previous Testing?&#xd;\n      AND rep.value_coded = 2146     -- No&#xd;\n      AND rep.voided = 0&#xd;\n      AND rep.obs_datetime BETWEEN :startDate AND :endDate&#xd;\n  );&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-04-27 07:28:31',4,'2025-11-05 03:26:07',4,0,NULL,NULL,NULL,'3b0f9835-29a4-418d-aaa6-3f8f1d141ece'),(469,'CITC_Repeat_Negative','clients tested negative on repeat visit','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a4daa5d2-8e61-44d1-bc37-1b6aba7a6d55\" retired=\"false\">\n  <name>CITC_Repeat_Negative</name>\n