-- PITC&#xd;\n AND pitc.voided = 0&#xd;\n AND pitc.obs_datetime BETWEEN :startDate AND :endDate&#xd;\nJOIN obs newf&#xd;\n  ON newf.person_id = p.patient_id&#xd;\n AND newf.concept_id = 4798           -- HTC, History of Previous Testing?&#xd;\n AND newf.value_coded = 2146          -- Yes&#xd;\n AND newf.voided = 0&#xd;\n AND newf.obs_datetime BETWEEN :startDate AND :endDate&#xd;\nWHERE p.voided = 0&#xd;\n  AND (&#xd;\n    res.location_id = :location&#xd;\n    OR EXISTS (SELECT 1 FROM location l WHERE l.location_id = res.location_id AND l.parent_location = :location)&#xd;\n  )&#xd;\n  -- exclude anyone with a NEW flag in the same period&#xd;\n  AND NOT EXISTS (&#xd;\n    SELECT 1 FROM obs rep&#xd;\n    WHERE rep.person_id = p.patient_id&#xd;\n      AND rep.concept_id = 4798       -- HTC, History of Previous Testing?&#xd;\n      AND rep.value_coded = 2146     -- No&#xd;\n      AND rep.voided = 0&#xd;\n      AND rep.obs_datetime BETWEEN :startDate AND :endDate&#xd;\n  );&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-04-27 07:30:31',4,'2025-11-05 03:35:06',4,0,NULL,NULL,NULL,'a4daa5d2-8e61-44d1-bc37-1b6aba7a6d55'),(470,'CITC_New_Positive','new clients tested positive','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9cd47068-2982-4ca1-a040-bc19ca313349\" retired=\"false\">\n  <name>CITC_New_Positive</name>\n  <description>new clients tested positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-04-27 05:33:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:17:28 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <na