  AND (&#xd;\n    res.location_id = :location&#xd;\n    OR EXISTS (SELECT 1 FROM location l WHERE l.location_id = res.location_id AND l.parent_location = :location)&#xd;\n  )&#xd;\n  -- exclude anyone with a REPEAT flag in the same period&#xd;\n  AND NOT EXISTS (&#xd;\n    SELECT 1 FROM obs rep&#xd;\n    WHERE rep.person_id = p.patient_id&#xd;\n      AND rep.concept_id = 4798       -- HTC, History of Previous Testing?&#xd;\n      AND rep.value_coded = 2146      -- Yes&#xd;\n      AND rep.voided = 0&#xd;\n      AND rep.obs_datetime BETWEEN :startDate AND :endDate&#xd;\n  );&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-04-27 07:33:15',4,'2025-11-05 03:17:28',4,0,NULL,NULL,NULL,'9cd47068-2982-4ca1-a040-bc19ca313349'),(471,'CITC_New_Negative','clients tested negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ebf8843c-2e45-4156-8bbf-867273775513\" retired=\"false\">\n  <name>CITC_New_Negative</name>\n  <description>clients tested negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-04-27 05:37:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:42:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.