.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4706)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 08:54:01',4,'2021-07-13 15:11:33',4,0,NULL,NULL,NULL,'19fff766-eb8f-41f2-8d76-8f6505bbb9b9'),(576,'Clients seen given 1 month supply 3e','1month supply of 3e','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"b2e90223-56f5-4e04-89e1-d9cc1fc34b17\" retired=\"false\">\n  <name>Clients seen given 1 month supply 3e</name>\n  <description>1month supply of 3e</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 08:54:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 15:11:57 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>576</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4707)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 08:54:50',4,'2021-07-13 15:11:57',4,0,NULL,NULL,NULL,'b2e90223-56f5-4e04-89e1-d9cc1fc34b17'),(577,'Clients seen given 1 month supply 3f','1month supply of 3f','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"fdc65c1d-6a93-4a2d-bfc8-19f93d762531\" retired=\"false\">\n  <name>Clients seen given 1 month supply 3f</name>\n  <description>1month supply of 3f</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 08:58:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 15:12:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>577</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4708)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 08:58:16',4,'2021-07-13 15:12:26',4,0,NULL,NULL,NULL,'fdc65c1d-6a93-4a2d-bfc8-19f93d762531'),(578,'Clients seen given 1 month supply 3g','1month supply of 3g','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"72a63ae5-4204-4f3a-803a-6ede62fee967\" retired=\"false\">\n  <name>Clients seen given 1 month supply 3g</name>\n  <description>1month supply of 3g</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 08:59:44 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 15:12:55 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>578</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4709)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 08:59:44',4,'2021-07-13 15:12:55',4,0,NULL,NULL,NULL,'72a63ae5-4204-4f3a-803a-6ede62fee967'),(579,'Clients seen given 1 month supply 3h','1month supply of 3h','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a1042d17-e93e-407e-a91e-e6cdf2930ab6\" retired=\"false\">\n  <name>Clients seen given 1 month supply 3h</name>\n  <description>1month supply of 3h</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 09:00:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 15:13:35 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>endDate</name>\n      <label>endDate</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>579</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4710)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 09:00:47',4,'2021-07-13 15:13:35',4,0,NULL,NULL,NULL,'a1042d17-e93e-407e-a91e-e6cdf2930ab6'),(580,'adult_arv_2c_3mnth','3months supply of 2c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d0c31b7a-ea56-4f12-a574-924391d2dcb0\" retired=\"false\">\n  <name>adult_arv_2c_3mnth</name>\n  <description>3months supply of 2c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 09:02:19 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2020-06-05 09:02:33 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>580</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o 	&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN person ON person.person_id = o.person_id	&#xd;\nwhere (o.location_id =:location or parent_location  =:location)&#xd;\nAND o.voided = 0&#xd;\nand o.person_id in (select o.person_id&#xd;\n			from obs o&#xd;\n				where obs_datetime BETWEEN :startDate AND :endDate&#xd;\n				and concept_id = 2250 and value_coded = 2210&#xd;\n				)&#xd;\nand o.person_id in	&#xd;\n	(select o.person_id&#xd;\n	from obs o&#xd;\n		where obs_datetime BETWEEN :startDate AND :endDate&#xd;\n		and concept_id = 4174 and value_coded = 4177&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 11:02:19',4,'2020-06-05 11:02:33',4,0,NULL,NULL,NULL,'d0c31b7a-ea56-4f12-a574-924391d2dcb0'),(581,'adult_arv_2d_3mnth','3months supply of 2d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"0f6c5bd6-8635-463f-80c8-d5322e97fe54\" retired=\"false\">\n  <name>adult_arv_2d_3mnth</name>\n  <description>3months supply of 2d</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 09:03:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2020-06-05 09:03:19 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>581</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o 	&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN person ON person.person_id = o.person_id	&#xd;\nwhere (o.location_id =:location or parent_location  =:location)&#xd;\nAND o.voided = 0&#xd;\nand o.person_id in (select o.person_id&#xd;\n			from obs o&#xd;\n				where obs_datetime BETWEEN :startDate AND :endDate&#xd;\n				and concept_id = 2250 and value_coded = 2209&#xd;\n				)&#xd;\nand o.person_id in	&#xd;\n	(select o.person_id&#xd;\n	from obs o&#xd;\n		where obs_datetime BETWEEN :startDate AND :endDate&#xd;\n		and concept_id = 4174 and value_coded = 4177&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 11:03:04',4,'2020-06-05 11:03:19',4,0,NULL,NULL,NULL,'0f6c5bd6-8635-463f-80c8-d5322e97fe54'),(582,'adult_arv_2e_3mnth','3months aupply of 2e','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"62d0a57e-51b0-4f3e-967a-12ce18b24778\" retired=\"false\">\n  <name>adult_arv_2e_3mnth</name>\n  <description>3months aupply of 2e</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 09:03:56 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2020-06-05 09:04:38 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>582</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o 	&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN person ON person.person_id = o.person_id	&#xd;\nwhere (o.location_id =:location or pare