dule.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"e6de45f1-6b8a-4436-ba97-b13059648def\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:15:41',4,'2021-01-27 17:08:52',4,0,NULL,NULL,NULL,'6e5cbb5d-f451-47ea-a2fd-9bff1f28f555'),(672,'Missed or defaulted under 28days','missed or defaulted < 28','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a7064d93-cb9d-44f7-b7cb-f0d38313fdb3\" retired=\"false\">\n  <name>Missed or defaulted under 28days</name>\n  <description>missed or defaulted &lt; 28</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:16:25 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-02-18 15:44:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>672</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\ninner join location l on o.location_id = l.location_id&#xd;\n	 and l.location_id = :location or l.parent_location = :location&#xd;\n	 -- PATIENTS WHO HAVE NOT SHOWED UP FOR THEIR APPOINTMENT FOR UP TO 28 DAYS&#xd;\n	 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id IN (3753,6515)&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &lt; cast(:endDate as date)&#xd;\n								and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &gt; 0&#xd;\n                and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &lt;= 28&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							and os.voided = 0&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249 and os.voided = 0&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							&#xd;\n									-- TOUTS&#xd;\n									select tout_clients.person_id&#xd;\n                     from&#xd;\n                     (select B.person_id, B.obs_group_id, B.obs_datetime AS latest_consultation&#xd;\n                      from obs B&#xd;\n                       inner join&#xd;\n                         (select person_id, max(obs_datetime), SUBSTRING(max(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                          from obs where concept_id = 2403&#xd;\n                          and obs_datetime &lt;= cast(:endDate as date)&#xd;\n                          and voided = 0&#xd;\n                          group by person_id) as A&#xd;\n                          on A.observation_id = B.obs_group_id&#xd;\n                          where concept_id = 2398&#xd;\n                          and A.observation_id = B.obs_group_id&#xd;\n                          and voided = 0&#xd;\n                          group by B.person_id&#xd;\n                            ) as tout_clients&#xd;\n                            where tout_clients.latest_consultation &lt; cast(:endDate as date)&#xd;\n										&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n&#xd;\n		and active_clients.person_id not in(&#xd;\n									-- Visitors&#xd;\n								select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id IN (3753,6515) &#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and o.value_coded =1 and o.voided=0&#xd;\n									and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n							)					 &#xd;\n&#xd;\n		&#xd;\n						 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;	&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 17:46:25',4,'2026-02-18 21:14:39',4,0,NULL,NULL,NULL,'a7064d93-cb9d-44f7-b7cb-f0d38313fdb3'),(673,'adult_arv_1m_other_mnths','1m other supply','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"9ebb3d1c-52e8-40e7-abc2-871abfdd6ffa\" retired=\"false\">\n  <name>adult_arv_1m_other_mnths</name>\n  <description>1m other supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:16:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 17:18:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>673</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"4ecbaa81-3f7c-46e5-834f-ddb6439039fc\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:16:47',4,'2021-01-27 17:18:26',4,0,NULL,NULL,NULL,'9ebb3d1c-52e8-40e7-abc2-871abfdd6ffa'),(674,'adult_arv_1n_other_mnths','1n other supply','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"b829a556-e0e5-4856-8800-ea2560894f62\" retired=\"false\">\n  <name>adult_arv_1n_other_mnths</name>\n  <description>1n other supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:17:46 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 17:41:01 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>674</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"db874a28-7767-4d91-8cd5-9e1dd5911ad6\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:17:46',4,'2021-01-27 17:41:01',4,0,NULL,NULL,NULL,'b829a556-e0e5-4856-8800-ea2560894f62'),(675,'adult_arv_1p_other_mnths','1p other supply','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"6843123f-248a-4232-9008-a51ffdc43c5b\" retired=\"false\">\n  <name>adult_arv_1p_other_mnths</name>\n  <description>1p other supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:20:31 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 17:49:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>675</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"0f780026-4b19-47c2-b88a-f103b85b8493\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:20:31',4,'2021-01-27 17:49:53',4,0,NULL,NULL,NULL,'6843123f-248a-4232-9008-a51ffdc43c5b'),(676,'adult_arv_1q_other_mnths','1q other supply','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"762d08de-74a3-40fe-9240-1fc904fcb69e\" retired=\"false\">\n  <name>adult_arv_1q_other_mnths</name>\n  <description>1q other supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:21:42 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 18:07:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>676</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"ae410b11-acaa-425d-a309-7eb491cfa3eb\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:21:42',4,'2021-01-27 18:07:21',4,0,NULL,NULL,NULL,'762d08de-74a3-40fe-9240-1fc904fcb69e'),(677,'Missed or defaulted between 29 and 89 days','missed >29\r\nmissed < 90','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5be87aeb-a57c-4a02-83e7-93d560d49fbb\" retired=\"false\">\n  <name>Missed or defaulted between 29 and 89 days</name>\n  <description>missed &gt;29&#xd;\nmissed &lt; 90</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:22:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-02-18 11:41:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"9\">\n      <name>endDateAS</name>\n      <label>endDateAS</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>677</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o  inner join location l on o.location_id = l.location_id&#xd;\n	 and l.location_id = :location or l.parent_location = :location&#xd;\n	 -- PATIENTS WHO HAVE NOT SHOWED UP FOR THEIR APPOINTMENT FOR 4 WEEKS to 3 MONTHS (i.e. 29 to 89 days)&#xd;\n	 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id IN (3753,6515)&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &lt; cast(:endDate as date)&#xd;\n								and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &gt; 28&#xd;\n                and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &lt;= 89&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							&#xd;\n									-- TOUTS&#xd;\n									select tout_clients.person_id&#xd;\n                     from&#xd;\n                     (select B.person_id, B.obs_group_id, B.obs_datetime AS latest_consultation&#xd;\n                      from obs B&#xd;\n                       inner join&#xd;\n                         (select person_id, max(obs_datetime), SUBSTRING(max(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                          from obs where concept_id = 2403&#xd;\n                          and obs_datetime &lt;= cast(:endDate as date)&#xd;\n                          and voided = 0&#xd;\n                          group by person_id) as A&#xd;\n                          on A.observation_id = B.obs_group_id&#xd;\n                          where concept_id = 2398&#xd;\n                          and A.observation_id = B.obs_group_id&#xd;\n                          and voided = 0&#xd;\n                          group by B.person_id&#xd;\n                            ) as tout_clients&#xd;\n                            where tout_clients.latest_consultation &lt; cast(:endDate as date)&#xd;\n										&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n					select person_id &#xd;\n					from person &#xd;\n					where death_date &lt;= cast(:endDate as date)&#xd;\n					and dead = 1 and voided = 0&#xd;\n			)&#xd;\n		and active_clients.person_id not in (&#xd;\n					-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id IN (3753,6515) &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n						 )&#xd;\n						 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n									</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 17:52:30',4,'2026-02-18 17:11:26',4,0,NULL,NULL,NULL,'5be87aeb-a57c-4a02-83e7-93d560d49fbb'),(678,'adult_arv_other_other_mnths','other other supply','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"c53c49b3-0557-4f1a-9006-1a88e542519d\" retired=\"false\">\n  <name>adult_arv_other_other_mnths</name>\n  <description>other other supply</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:23:07 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-02-04 09:06:31 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>678</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"c51f0308-5026-404c-afbf-35df5fb4e729\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:23:07',4,'2021-02-04 09:06:31',4,0,NULL,NULL,NULL,'c53c49b3-0557-4f1a-9006-1a88e542519d'),(679,'adult_arv_2c_1mnth','2c 1mnth','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"69830812-bc46-428a-b10e-43a31a982e02\" retired=\"false\">\n  <name>adult_arv_2c_1mnth</name>\n  <description>2c 1mnth</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:36:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 14:26:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>679</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"c1f9e099-143c-4dd2-bfe0-8946fc5d148e\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:36:06',4,'2021-07-13 14:26:45',4,0,NULL,NULL,NULL,'69830812-bc46-428a-b10e-43a31a982e02'),(680,'LTFU this month','lost to follow up','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f5c2691c-0977-4a4d-957e-2cf973e37bb7\" retired=\"false\">\n  <name>LTFU this month</name>\n  <description>lost to follow up</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:37:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2020-06-05 12:38:18 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>680</id>\n  <query>select distinct o.person_id &#xd;\nFROM obs o&#xd;\nINNER JOIN patient ON o.person_id = patient.patient_id &#xd;\nand o.concept_id = 3752 &#xd;\nand o.value_datetime in&#xd;\n	(				&#xd;\n		select latestFU from&#xd;\n		(&#xd;\n		select distinct os.person_id, max(os.value_datetime) AS latestFU, datediff(CAST(:endDate AS DATE), max(value_datetime)) AS &#xd;\n                Num_Days&#xd;\n                from obs os&#xd;\n                inner join person_name pn on os.person_id = pn.person_id&#xd;\n                inner join patient p  on pn.person_id = p.patient_id and pn.voided = 0&#xd;\n                inner join person ps on ps.person_id = p.patient_id and ps.voided = 0&#xd;\n		where os.concept_id = 3752 &#xd;\n                and obs_datetime &lt;= :endDate&#xd;\n		group by os.person_id&#xd;\n		having Num_Days &gt; 7&#xd;\n                and Num_Days &lt; 30&#xd;\n		) as lost&#xd;\n	)									&#xd;\nand o.person_id in&#xd;\n	(				&#xd;\n		select person_id from&#xd;\n		(&#xd;\n		    select distinct os.person_id, max(os.value_datetime) AS latestFU, datediff(CAST(:endDate AS DATE), &#xd;\n                    max(value_datetime)) AS Num_Days&#xd;\n		    from obs os&#xd;\n		    inner join person_name pn on os.person_id = pn.person_id&#xd;\n		    inner join patient p  on pn.person_id = p.patient_id and pn.voided = 0&#xd;\n		    inner join person ps on ps.person_id = p.patient_id and ps.voided = 0&#xd;\n		    where os.concept_id = 3752 &#xd;\n                    and obs_datetime &lt;= :endDate&#xd;\n		    group by os.person_id&#xd;\n		    having Num_Days &gt; 90&#xd;\n		) as lost&#xd;\n	)&#xd;\n		&#xd;\nAND o.person_id not in (																		 &#xd;\n			select distinct os.person_id &#xd;\n				from obs os&#xd;\n				where (os.concept_id = 4155 and os.value_coded = 2146 and obs_datetime &lt; :endDate and person_id not in &#xd;\n				(select person_id from&#xd;\n					(select person_id who, max(value_datetime) latest&#xd;\n					from obs &#xd;\n					where concept_ID = 2266&#xd;\n                                        group by person_id) one,&#xd;\n					&#xd;\n					 (&#xd;\n					select person_id,obs_datetime &#xd;\n					from obs &#xd;\n					where concept_id = 3843 ) two&#xd;\n					&#xd;\n					where who = person_id&#xd;\n					and DATE(obs_datetime) &gt; DATE(latest))&#xd;\n					)													  														 							 &#xd;\n			)&#xd;\nAND o.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= :endDate &#xd;\n			and dead = 1&#xd;\n			)&#xd;\n&#xd;\n;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 14:37:18',4,'2020-06-05 14:38:18',4,0,NULL,NULL,NULL,'f5c2691c-0977-4a4d-957e-2cf973e37bb7'),(681,'adult_arv_2d_1mnth','2d 1mnth','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"456f6967-04cc-4c2a-8e50-7c99e799eb29\" retired=\"false\">\n  <name>adult_arv_2d_1mnth</name>\n  <description>2d 1mnth</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 12:37:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 14:30:11 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>681</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"50d1da47-5c78-46f0-81dc-11c7eb0a2e60\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2020-06-05 12:37:55',4,'2021-07-13 14:30:11',4,0,NULL,NULL,NULL,'456f6967-04cc-4c2a-8e50-7c99e799eb29'),(682,'adult_arv_2e_1mnth','2e 1mnth','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"e5b6e482-9ccb-