.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>721</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\n	inner join location l on o.location_id = l.location_id&#xd;\n	INNER JOIN person ON person.person_id = o.person_id&#xd;\n	&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\n	AND o.concept_id = 2249 &#xd;\n	 AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n         AND YEAR(o.value_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n	AND o.voided = 0&#xd;\n	&#xd;\nand o.person_id in(&#xd;\n		select os.person_id&#xd;\n		from obs os&#xd;\n        -- All patients given x regimen during a particular period&#xd;\n		where os.concept_id = 2250 and os.value_coded = 4686&#xd;\n		AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    	AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\n					&#xd;\nand o.person_id not in ( -- remove transfer ins&#xd;\n   select os.person_id &#xd;\n   from obs os&#xd;\n   where os.concept_id = 3634 AND os.value_coded = 2095 &#xd;\n    AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\nAND person.voided = 0&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2020-06-05 13:30:13',4,'2021-01-27 22:27:00',4,0,NULL,NULL,NULL,'98e00266-550e-4ac2-ad86-d1bfd1edad02'),(722,'CI42a: Adult 3rd Line 1month supply 3f','3f 1mnth','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"0ec32115-a8ab-4989-8693-4a3b02a2f57f\" retired=\"false\">\n  <name>CI42a: Adult 3rd Line 1month supply 3f</name>\n  <description>3f 1mnth</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2020-06-05 13:30:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-13 15:24:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>722</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"fdc65c1d-6a93-4a2d-bfc8-19f93d762531\"/>\n    <parameterMappings id=\"11\">\n   