xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 3683&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and oss.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															and oss.obs_datetime &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(os.value_datetime), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(os.value_datetime) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-26 17:32:43',4,'2021-01-26 17:33:19',4,0,NULL,NULL,NULL,'bb3bfcea-7bf4-40ff-8e51-c02125d9ed36'),(1054,'Clients given 3 months supply 3b','3mnths 3b','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c961ad65-091a-4ef3-b3df-93795215d394\" retired=\"false\">\n  <name>Clients given 3 months supply 3b</name>\n  <description>3mnths 3b</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-26 17:35:11 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-26 17:35:48 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1054</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT person_id&#xd;\nFROM( (&#xd;\n		SELECT person_id &#xd;\n					FROM( &#xd;\n						SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) as ARV_regimen&#xd;\n						FROM&#xd;\n						(&#xd;\n							select distinct o.person_id,o.value_coded as current_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2250&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2250 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n						)currentreg&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as substitute_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 4284&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 4284 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)substitutereg ON currentreg.person_id = substitutereg.person_id&#xd;\n&#xd;\n                            LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as switch_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2268&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2268 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)switchreg ON currentreg.person_id = switchreg.person_id&#xd;\n								)regimen &#xd;\n								WHERE ARV_regimen = 3684) &#xd;\n		UNION&#xd;\n		&#xd;\n		(SELECT person_id &#xd;\n		FROM(&#xd;\n			SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n			FROM(&#xd;\n					(select distinct o.person_id,o.value_coded current_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 2250&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n									)&#xd;\n					)&#xd;\n				)currentreg&#xd;\n					&#xd;\n                 LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as substitute_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 4284&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as switch_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 2268&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    )regimen&#xd;\n					WHERE ARV_regimen = 3684)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT person_id &#xd;\n		FROM(&#xd;\n			SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n			FROM(&#xd;\n					(select distinct o.person_id,o.value_coded current_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 2250&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n									)&#xd;\n					)&#xd;\n				)currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as substitute_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 4284&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as switch_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 2268&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n                    )regimen&#xd;\n					WHERE ARV_regimen = 3684)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT distinct person_id&#xd;\nFROM(SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n                FROM(SELECT o.person_id,o.value_coded as current_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2250&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as substitute_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 4284&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as switch_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2268&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 3684&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and oss.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															and oss.obs_datetime &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(os.value_datetime), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(os.value_datetime) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-26 17:35:11',4,'2021-01-26 17:35:48',4,0,NULL,NULL,NULL,'c961ad65-091a-4ef3-b3df-93795215d394'),(1055,'Clients given 3 months supply 3c','3mnths 3c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"980ee077-7ac1-4380-b636-b5d83e80e128\" retired=\"false\">\n  <name>Clients given 3 months supply 3c</name>\n  <description>3mnths 3c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-26 17:36:24 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-26 17:36:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1055</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT person_id&#xd;\nFROM( (&#xd;\n		SELECT person_id &#xd;\n					FROM( &#xd;\n						SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) as ARV_regimen&#xd;\n						FROM&#xd;\n						(&#xd;\n							select distinct o.person_id,o.value_coded as current_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2250&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2250 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n						)currentreg&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as substitute_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 4284&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 4284 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)substitutereg ON currentreg.person_id = substitutereg.person_id&#xd;\n&#xd;\n                            LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as switch_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2268&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2268 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)switchreg ON currentreg.person_id = switchreg.person_id&#xd;\n								)regimen &#xd;\n								WHERE ARV_regimen = 3685) &#xd;\n		UNION&#xd;\n		&#xd;\n		(SELECT person_id &#xd;\n		FROM(&#xd;\n			SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n			FROM(&#xd;\n					(select distinct o.person_id,o.value_coded current_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 2250&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n									)&#xd;\n					)&#xd;\n				)currentreg&#xd;\n					&#xd;\n                 LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as substitute_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 4284&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as switch_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n						  AND o.concept_id = 2268&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    )regimen&#xd;\n					WHERE ARV_regimen = 3685)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT person_id &#xd;\n		FROM(&#xd;\n			SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n			FROM(&#xd;\n					(select distinct o.person_id,o.value_coded current_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 2250&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n									)&#xd;\n					)&#xd;\n				)currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as substitute_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 4284&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					(select distinct o.person_id,o.value_coded as switch_regimen&#xd;\n						FROM obs o&#xd;\n						-- CAME IN PREVIOUS 1 MONTH AND WAS GIVEN (2, 3, 4, 5, 6 MONHTS SUPPLY OF DRUGS)&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n						  AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n						  AND o.concept_id = 2268&#xd;\n						  AND o.voided = 0 &#xd;\n						  AND o.person_id in (&#xd;\n												SELECT oss.person_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -2 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4177))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n                    )regimen&#xd;\n					WHERE ARV_regimen = 3685)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT distinct person_id&#xd;\nFROM(SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n                FROM(SELECT o.person_id,o.value_coded as current_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2250&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as substitute_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 4284&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n                    LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as switch_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2268&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4177&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 3685&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and oss.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															and oss.obs_datetime &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(os.value_datetime), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(os.value_datetime) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-26 17:36:24',4,'2021-01-26 17:36:53',4,0,NULL,NULL,NULL,'980ee077-7ac1-4380-b636-b5d83e80e128'),(1056,'Clients given 3 months supply 3d','3mnths 3d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a5671007-d60d-44f4-8e1c-230aeb2239ec\" retired=\"false\">\n  <name>Clients given 3 months supply 3d</name>\n  <description>3mnths 3d</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-26 17:38:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-26 17:38:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1056</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT person_id&#xd;\nFROM( (&#xd;\n		SELECT person_id &#xd;\n					FROM( &#xd;\n						SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) as ARV_regimen&#xd;\n						FROM&#xd;\n						(&#xd;\n							select distinct o.person_id,o.value_coded as current_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2250&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2250 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n						)currentreg&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as substitute_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 4284&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 4284 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4177))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                   