on_id&#xd;\n												FROM obs oss&#xd;\n												WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -5 MONTH)) &#xd;\n												AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -5 MONTH))&#xd;\n												AND oss.concept_id = 4174 and (oss.value_coded in (4247))&#xd;\n												)&#xd;\n						 &#xd;\n                 &#xd;\n           WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n					&#xd;\n					)regimen&#xd;\n					WHERE ARV_regimen = 3678)&#xd;\nUNION&#xd;\n&#xd;\n(SELECT distinct person_id&#xd;\nFROM(SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n                FROM(SELECT o.person_id,o.value_coded as current_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2250&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4247&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as substitute_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 4284&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4247&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					 LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as switch_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2268&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded = 4247&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -6 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(os.value_datetime, CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n&#xd;\n&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 3678&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and oss.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															and oss.obs_datetime &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(os.value_datetime), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and os.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(os.value_datetime) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-26 19:06:43',4,'2021-01-26 19:07:18',4,0,NULL,NULL,NULL,'826fa67b-2ba1-42de-bbc9-fff95007b9fb'),(1059,'Clients seen given 1 month supply other','1 month other','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"aba0cb73-c297-4fba-b97d-89ac9a7c8003\" retired=\"false\">\n  <name>Clients seen given 1 month supply other</name>\n  <description>1 month other</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 06:50:37 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-08 14:19:54 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1059</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 2143)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 10 AND datediff(latest_follow_up, max_observation)&lt; 28&#xd;\n			or datediff(latest_follow_up, max_observation) &gt;=  28 AND datediff(latest_follow_up, max_observation)&lt; 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-27 06:50:37',4,'2021-07-08 14:19:54',4,0,NULL,NULL,NULL,'aba0cb73-c297-4fba-b97d-89ac9a7c8003'),(1060,'Clients given 6 months supply other','6 months other','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2cbd2310-1aec-4bdf-b0e2-6a5387529764\" retired=\"false\">\n  <name>Clients given 6 months supply other</name>\n  <description>6 months other</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 07:08:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-06-30 11:24:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1060</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n	(Select Id&#xd;\n	FROM&#xd;\n	(select distinct patient.patient_id AS Id&#xd;\n									   &#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 &#xd;\n&#xd;\n						AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n						AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n						 &#xd;\n						INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n				  ) AS Newly_Initiated_ART_Clients)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS SEEN ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 &#xd;\n											AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n											AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 2143)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;=  168 AND datediff(latest_follow_up, max_observation)&lt; 196)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-27 07:08:38',4,'2021-06-30 11:24:37',4,0,NULL,NULL,NULL,'2cbd2310-1aec-4bdf-b0e2-6a5387529764'),(1061,'Clients given Other months MMD supply other','other months other regimen','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c51f0308-5026-404c-afbf-35df5fb4e729\" retired=\"false\">\n  <name>Clients given Other months MMD supply other</name>\n  <description>other months other regimen</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 07:28:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-06-30 11:49:08 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1061</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n	(Select Id&#xd;\n	FROM&#xd;\n	(select distinct patient.patient_id AS Id&#xd;\n									   &#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 &#xd;\n&#xd;\n						AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n						AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n						 &#xd;\n						INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n				  ) AS Newly_Initiated_ART_Clients)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS SEEN ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 &#xd;\n											AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n											AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 2143)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;=  56 AND datediff(latest_follow_up, max_observation)&lt; 84&#xd;\n			OR datediff(latest_follow_up, max_observation) &gt;=  112 AND datediff(latest_follow_up, max_observation)&lt; 140&#xd;\n			OR datediff(latest_follow_up, max_observation) &gt;=  140 AND datediff(latest_follow_up, max_observation)&lt; 168&#xd;\n			OR datediff(latest_follow_up, max_observation) &gt;=  196&#xd;\n			)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-27 07:28:16',4,'2021-06-30 11:49:08',4,0,NULL,NULL,NULL,'c51f0308-5026-404c-afbf-35df5fb4e729'),(1062,'Clients newly initiated other regimen','initiated other','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"83133cb9-2778-43d9-b579-1ad824027608\" retired=\"false\">\n  <name>Clients newly initiated other regimen</name>\n  <description>initiated other</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 14:51:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 14:51:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1062</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\n	inner join location l on o.location_id = l.location_id&#xd;\n	INNER JOIN person ON person.person_id = o.person_id&#xd;\n	&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\n	AND o.concept_id = 2249 &#xd;\n	 AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n         AND YEAR(o.value_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n	AND o.voided = 0&#xd;\n	&#xd;\nand o.person_id in(&#xd;\n		select os.person_id&#xd;\n		from obs os&#xd;\n        -- All patients given x regimen during a particular period&#xd;\n		where os.concept_id = 2250 and os.value_coded = 2143&#xd;\n		AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    	AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\n					&#xd;\nand o.person_id not in ( -- remove transfer ins&#xd;\n   select os.person_id &#xd;\n   from obs os&#xd;\n   where os.concept_id = 3634 AND os.value_coded = 2095 &#xd;\n    AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE))&#xd;\n    AND YEAR(os.obs_datetime) =  YEAR(CAST(:endDate AS DATE))&#xd;\n)&#xd;\nAND person.voided = 0&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-27 14:51:15',4,'2021-01-27 14:51:51',4,0,NULL,NULL,NULL,'83133cb9-2778-43d9-b579-1ad824027608'),(1063,'CMP_ART Regimen 1month supply other','compostion newly initiated and seen','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition id=\"1\" uuid=\"60b6b073-1a42-4d55-b194-fadbb863aadc\" retired=\"false\">\n  <name>CMP_ART Regimen 1month supply other</name>\n  <description>compostion newly initiated and seen</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 15:28:45 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-01-27 15:32:00 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1063</id>\n  <compositionString>Clients-seen-given-1-month-supply-other OR Clients-newly-initiated-other-regimen</compositionString>\n  <searches id=\"9\">\n    <entry>\n      <string>Clients-seen-given-1-month-supply-other</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"10\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"11\" uuid=\"aba0cb73-c297-4fba-b97d-89ac9a7c8003\"/>\n        <parameterMappings id=\"12\">\n          <entry>\n            <string>endDate</string>\n            <string>${endDate}</string>\n          </entry>\n          <entry>\n            <string>location</string>\n            <string>${location}</string>\n          </entry>\n          <entry>\n            <string>startDate</string>\n            <string>${startDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n    <entry>\n      <string>Clients-newly-initiated-other-regimen</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"13\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"14\" uuid=\"83133cb9-2778-43d9-b579-1ad824027608\"/>\n        <parameterMappings reference=\"12\"/>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </searches>\n</org.openmrs.module.reporting.cohort.definition.CompositionCohortDefinition>','2021-01-27 15:28:45',4,'2021-01-27 15:32:00',4,0,NULL,NULL,NULL,'60b6b073-1a42-4d55-b194-fadbb863aadc'),(1064,'Clients seen given 1 month supply 4g','4g','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"cfa78680-b638-40d6-bf8a-d6b3e7092725\" retired=\"false\">\n  <name>Clients seen given 1 month supply 4g</name>\n  <description>4g</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-01-27 21:09:12 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-02-04 07:37:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1064</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT person_id&#xd;\nFROM( (&#xd;\n		SELECT person_id &#xd;\n					FROM( &#xd;\n						SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) as ARV_regimen&#xd;\n						FROM&#xd;\n						(&#xd;\n							select distinct o.person_id,o.value_coded as current_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2250&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2250 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n						)currentreg&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as substitute_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 4284&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 4284 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)substitutereg ON currentreg.person_id = substitutereg.person_id&#xd;\n&#xd;\n							LEFT OUTER JOIN&#xd;\n							(&#xd;\n							select distinct o.person_id,o.value_coded as switch_regimen &#xd;\n							from obs o&#xd;\n&#xd;\n                            inner join &#xd;\n                                        (select ob.person_id,cast(max(ob.obs_datetime) as date) maxdate &#xd;\n                                        from obs ob&#xd;\n                                        where ob.concept_id = 2268&#xd;\n                                        AND cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                        AND MONTH(ob.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                        AND YEAR(ob.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                        and ob.voided = 0&#xd;\n                                        group by ob.person_id &#xd;\n                                        )latest &#xd;\n                                    on latest.person_id = o.person_id&#xd;\n                                    &#xd;\n											-- CLIENTS SEEN FOR ART&#xd;\n							 INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n                             INNER JOIN obs os on latest.person_id = os.person_id	&#xd;\n							 AND o.concept_id = 2268 &#xd;\n							 AND o.voided = 0    &#xd;\n                             AND (os.concept_id = 4174 AND os.value_coded in (4175,4243))&#xd;\n                             AND os.voided = 0&#xd;\n                             and CAST(o.obs_datetime as date) = maxdate&#xd;\n				             and CAST(o.obs_datetime AS DATE) = CAST(os.obs_datetime AS DATE)                              &#xd;\n                             and o.person_id in(&#xd;\n                                                SELECT oss.person_id&#xd;\n                                                FROM obs oss&#xd;\n                                                WHERE oss.concept_id = 3843 AND oss.value_coded = 3841 OR oss.value_coded = 3842&#xd;\n                                                AND MONTH(oss.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                AND oss.voided = 0 &#xd;\n                                                )&#xd;\n												&#xd;\n                            AND o.person_id not in (&#xd;\n                                            select oss.person_id&#xd;\n                                            from obs oss&#xd;\n                                                        -- CLIENTS NEWLY INITIATED ON ART													&#xd;\n                                            WHERE (oss.concept_id = 2249 &#xd;\n                                                AND MONTH(oss.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n                                                AND YEAR(oss.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                                )&#xd;\n                                                AND oss.voided = 0)&#xd;\n							)switchreg ON currentreg.person_id = switchreg.person_id&#xd;\n								)regimen &#xd;\n								WHERE ARV_regimen = 4684) &#xd;\nUNION&#xd;\n&#xd;\n(SELECT distinct person_id&#xd;\nFROM(SELECT currentreg.person_id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n                FROM(SELECT o.person_id,o.value_coded as current_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2250&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n					))currentreg&#xd;\n					LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as substitute_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 4284&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n		LEFT OUTER JOIN&#xd;\n					(&#xd;\n					SELECT o.person_id,o.value_coded as switch_regimen&#xd;\n					FROM obs o&#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					 AND MONTH(o.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND YEAR(o.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n					 AND o.voided = 0 &#xd;\n					 AND o.concept_id  = 2268&#xd;\n					 AND o.person_id in(&#xd;\n										SELECT oss.person_id&#xd;\n										FROM obs oss&#xd;\n										WHERE MONTH(oss.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND YEAR(oss.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n										AND oss.concept_id = 4174 and oss.value_coded in (4175,4243)&#xd;\n										AND oss.person_id in (&#xd;\n															select distinct os.person_id from obs os&#xd;\n															where &#xd;\n															MONTH(os.obs_datetime) = MONTH(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH)) &#xd;\n															AND YEAR(os.obs_datetime) = YEAR(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -1 MONTH))&#xd;\n															AND os.concept_id = 3752 AND DATEDIFF(CAST(os.value_datetime AS DATE), CAST(:endDate AS DATE)) BETWEEN 0 AND 28	&#xd;\n															)&#xd;\n										)&#xd;\n					 				 &#xd;\n				WHERE o.person_id not in (&#xd;\n						select distinct(person_id)&#xd;\n						from&#xd;\n								(&#xd;\n								select os.person_id, cast(max(os.obs_datetime) as date) as latest_visit&#xd;\n												from obs os&#xd;\n												where os.concept_id=3843&#xd;\n												and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n												group by os.person_id&#xd;\n												&#xd;\n								) as visit&#xd;\n						where CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and latest_visit &gt; CAST(o.obs_datetime AS DATE) &#xd;\n						and latest_visit &lt;= CAST(:endDate AS DATE)&#xd;\n										)	&#xd;\n					)switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id			&#xd;\n	)regimen&#xd;\n	WHERE ARV_regimen = 4684&#xd;\n)&#xd;\n		   &#xd;\n) AS ARTCurrent_PrevMonths&#xd;\n &#xd;\nWHERE ARTCurrent_PrevMonths.person_id not in (&#xd;\n									select distinct(o.person_id)&#xd;\n									from obs o&#xd;\n									where o.person_id in (&#xd;\n											-- FOLLOW UPS&#xd;\n												select firstquery.person_id&#xd;\n												from&#xd;\n												(&#xd;\n												select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, max(oss.value_datetime) as latest_followup_obs&#xd;\n												from obs oss&#xd;\n															where oss.voided=0 &#xd;\n															and oss.concept_id=3752 &#xd;\n															and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n															and CAST(oss.obs_datetime AS DATE) &gt; DATE_ADD(CAST(:endDate AS DATE), INTERVAL -7 MONTH)&#xd;\n															group by oss.person_id) firstquery&#xd;\n												inner join (&#xd;\n															select os.person_id,datediff(max(CAST(os.value_datetime AS DATE)), CAST(:endDate AS DATE)) as last_ap&#xd;\n															from obs os&#xd;\n															where concept_id = 3752&#xd;\n															and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n															group by os.person_id&#xd;\n															having last_ap &lt; 0&#xd;\n												) secondquery&#xd;\n												on firstquery.person_id = secondquery.person_id&#xd;\n									) and o.person_id in (&#xd;\n											-- TOUTS&#xd;\n											select distinct(person_id)&#xd;\n											from&#xd;\n											(&#xd;\n												select os.person_id, max(CAST(os.value_datetime AS DATE)) as latest_transferout&#xd;\n												from obs os&#xd;\n												where os.concept_id=2266&#xd;\n												group by os.person_id&#xd;\n												having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n											) as TOUTS&#xd;\n									)&#xd;\n		)&#xd;\nAND ARTCurrent_PrevMonths.person_id not in (&#xd;\n						-- Death&#xd;\n									select distinct p.person_id&#xd;\n									from person p&#xd;\n									where dead = 1&#xd;\n									and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n										)&#xd;\n			&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-01-27 21:09:12',4,'2021-02-04 07:37:42',4,0,NULL,NULL,NULL,'cfa78680-b638-40d6-bf8a-d6b3e7092725'),(1065,'Clients seen given 1 month supply 4h','4h','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortD