</indicator>\n      <dimensionOptions reference=\"18\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"164\">\n      <name>2s3months</name>\n      <label>adult_arv_2s_3mnths-15+yrs</label>\n      <indicator id=\"165\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.CohortIndicator\" id=\"166\" uuid=\"9508f75e-01d6-4fac-a9ef-701b6306f4e5\"/>\n        <parameterMappings reference=\"17\"/>\n      </indicator>\n      <dimensionOptions reference=\"18\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"167\">\n      <name>2sOther</name>\n      <label>adult_arv_2s_other-15+yrs</label>\n      <indicator id=\"168\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.CohortIndicator\" id=\"169\" uuid=\"eb4df91c-f55d-40ab-bd9c-de172dc40fb3\"/>\n        <parameterMappings reference=\"17\"/>\n      </indicator>\n      <dimensionOptions reference=\"18\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n  </columns>\n</org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition>','2021-07-24 21:08:14',4,'2021-07-25 00:06:41',4,0,NULL,NULL,NULL,'63481a60-98f4-448d-b87f-81c26b3428a2'),(1106,'Clients given Other months MMD supply 2i','Clients given Other months MMD supply 2i','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9a098a70-340d-4abf-8812-e8a7af58e41f\" retired=\"false\">\n  <name>Clients given Other months MMD supply 2i</name>\n  <description>Clients given Other months MMD supply 2i</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:12:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-24 22:13:34 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1106</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n	(Select Id&#xd;\n	FROM&#xd;\n	(select distinct patient.patient_id AS Id&#xd;\n									   &#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 &#xd;\n&#xd;\n						AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n						AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n						 &#xd;\n						INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n				  ) AS Newly_Initiated_ART_Clients)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS SEEN ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 &#xd;\n											AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n											AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3678)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;=  56 AND datediff(latest_follow_up, max_observation)&lt; 84&#xd;\n			OR datediff(latest_follow_up, max_observation) &gt;=  112 &#xd;\n			)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:12:47',4,'2021-07-24 22:13:34',4,0,NULL,NULL,NULL,'9a098a70-340d-4abf-8812-e8a7af58e41f'),(1107,'Clients given Other months MMD supply 3a','Clients given Other months MMD supply 3a','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"1beb1f89-253e-4989-86d6-79519e6d1991\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3a</name>\n  <description>Clients given Other months MMD supply 3a</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:14:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 15:39:52 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1107</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3683)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:14:16',4,'2021-07-25 15:39:52',4,0,NULL,NULL,NULL,'1beb1f89-253e-4989-86d6-79519e6d1991'),(1108,'Clients given Other months MMD supply 3b','Clients given Other months MMD supply 3b','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"0c074440-2184-41fd-a989-cd5eab20e861\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3b</name>\n  <description>Clients given Other months MMD supply 3b</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:15:29 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:23:48 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1108</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3684)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:15:29',4,'2021-07-25 17:23:48',4,0,NULL,NULL,NULL,'0c074440-2184-41fd-a989-cd5eab20e861'),(1109,'Clients given Other months MMD supply 3c','Clients given Other months MMD supply 3c','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8197eb7b-2d9c-4dae-b527-342d7a2fc049\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3c</name>\n  <description>Clients given Other months MMD supply 3c</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:24:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1109</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3685)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:06',4,'2021-07-25 17:24:42',4,0,NULL,NULL,NULL,'8197eb7b-2d9c-4dae-b527-342d7a2fc049'),(1110,'Clients given Other months MMD supply 3d','Clients given Other months MMD supply 3d','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6e1a7efa-9a36-440e-8fce-17afb7d33a70\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3d</name>\n  <description>Clients given Other months MMD supply 3d</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:25:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1110</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4706)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:16',4,'2021-07-25 17:25:45',4,0,NULL,NULL,NULL,'6e1a7efa-9a36-440e-8fce-17afb7d33a70'),(1111,'Clients given Other months MMD supply 3e','Clients given Other months MMD supply 3e','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7f6ea741-a3bf-4488-a354-9a258d65d49d\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3e</name>\n  <description>Clients given Other months MMD supply 3e</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:25 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:26:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1111</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4707)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:25',4,'2021-07-25 17:26:26',4,0,NULL,NULL,NULL,'7f6ea741-a3bf-4488-a354-9a258d65d49d'),(1112,'Clients given Other months MMD supply 3f','Clients given Other months MMD supply 3f','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2e6f05f5-2959-48b1-95e6-82ce7fbe83c2\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3f</name>\n  <description>Clients given Other months MMD supply 3f</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 15:41:48 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1112</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4708)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:38',4,'2021-07-25 15:41:48',4,0,NULL,NULL,NULL,'2e6f05f5-2959-48b1-95e6-82ce7fbe83c2'),(1113,'Clients given Other months MMD supply 3g','Clients given Other months MMD supply 3g','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6374a1da-a30b-4a63-8199-c4c44b3b8221\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3g</name>\n  <description>Clients given Other months MMD supply 3g</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:27:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1113</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4709)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:47',4,'2021-07-25 17:27:36',4,0,NULL,NULL,NULL,'6374a1da-a30b-4a63-8199-c4c44b3b8221'),(1114,'Clients given Other months MMD supply 3h','Clients given Other months MMD supply 3h','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e46ed914-5afc-4fe5-ac10-9380c044140d\" retired=\"false\">\n  <name>Clients given Other months MMD supply 3h</name>\n  <description>Clients given Other months MMD supply 3h</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:17:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-25 17:28:30 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1114</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id&#xd;\n                                  &#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4710)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN &#xd;\n&#xd;\n		(select Id, latest_follow_up,max_observation&#xd;\n		FROM(&#xd;\n            select a.person_id AS Id, SUBSTRING(MAX(CONCAT(a.obs_datetime, b.value_datetime)), 20) AS latest_follow_up, Max(CAST(a.obs_datetime AS DATE)) as max_observation,&#xd;\n			SUBSTRING(MAX(CONCAT(a.obs_datetime, b.obs_group_id)), 20) as max_obs_group_id&#xd;\n			from obs a, obs b&#xd;\n			where a.person_id = b.person_id&#xd;\n			and a.concept_id = 3753&#xd;\n			and b.concept_id = 3752&#xd;\n			and a.obs_id = b.obs_group_id&#xd;\n			and a.obs_datetime &lt;= cast(:endDate as date)&#xd;\n			group by a.person_id)as latest_follow_up_obs&#xd;\n			where datediff(latest_follow_up, max_observation) &gt;= 56)as supply_duration&#xd;\n		ON 	Active_Patients.Id = supply_duration.Id&#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-07-24 22:17:57',4,'2021-07-25 17:28:30',4,0,NULL,NULL,NULL,'e46ed914-5afc-4fe5-ac10-9380c044140d'),(1115,'adult_arv_2c_other','2c other months','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"bb9efe71-8a37-4920-8337-8b62d6bd950f\" retired=\"false\">\n  <name>adult_arv_2c_other</name>\n  <description>2c other months</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-07-24 22:39:05 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-07-24 22:42:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1115</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"986a2393-6ee9-4072-ae1d-04fd7b