                                                         where o.concept_id = 2254&#xd;\n                                                                                and o.value_numeric &gt; 1000&#xd;\n                                                                        )&#xd;\n                                                    group by oss.person_id&#xd;\n&#xd;\n									) As MoreThan1000copies&#xd;\n&#xd;\n									UNION&#xd;\n&#xd;\n									select Id, max_observation,latest_vl_result&#xd;\n									from(select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.concept_id)), 20) AS latest_vl_result&#xd;\n													from obs oss&#xd;\n													where oss.concept_id = 5485 and oss.voided=0&#xd;\n													and oss.obs_datetime BETWEEN DATE(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)) AND date_add(cast(:endDate as datetime), interval 1 day)&#xd;\n													and oss.value_numeric &gt; 1000&#xd;\n                                                    group by oss.person_id&#xd;\n&#xd;\n									) As Lab_Copies&#xd;\n&#xd;\n                                    order by Id&#xd;\n&#xd;\n			) as obs_vl_latest &#xd;\n            on obs_vl_latest.Id = o.person_id&#xd;\n			INNER JOIN&#xd;\n			(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS latest_indication_vl&#xd;\n				from obs oss&#xd;\n				where oss.concept_id = 4280 and oss.value_coded = 4281 and oss.voided=0&#xd;\n				and oss.obs_datetime BETWEEN DATE(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)) AND date_add(cast(:endDate as datetime), interval 1 day)&#xd;\n				group by oss.person_id&#xd;\n			) as obs_routine_latest_vl on o.person_id = obs_routine_latest_vl.person_id&#xd;\n			INNER JOIN person ON person.person_id = o.person_id AND person.voided = 0&#xd;\n			INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n			INNER JOIN pa