;\n		select distinct o.person_id,&#xd;\n							  IF(latest_indication_vl = 4281, &apos;Routine&apos;, &apos;Targeted&apos;) as Indication&#xd;\n&#xd;\n		from obs o INNER JOIN location l on o.location_id = l.location_id&#xd;\n	&#xd;\n	&#xd;\n			INNER JOIN&#xd;\n			(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS latest_indication_vl&#xd;\n				from obs oss&#xd;\n				where oss.concept_id = 4280 and oss.voided=0&#xd;\n				and oss.obs_datetime BETWEEN DATE(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -31 DAY)) AND date_add(cast(:endDate as datetime), interval 1 day)&#xd;\n				group by oss.person_id&#xd;\n			) as obs_routine_latest_vl on o.person_id = obs_routine_latest_vl.person_id&#xd;\n		&#xd;\n&#xd;\n			INNER JOIN person ON person.person_id = o.person_id AND person.voided = 0&#xd;\n			INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n			INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		&#xd;\n) as all_vl_tests_performed&#xd;\nwhere Indication = &apos;Targeted&apos;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-08-05 17:54:38',4,'2026-02-15 18:51:23',4,0,NULL,NULL,NULL,'7a0d9c5b-e86d-4c06-8e83-487fc8f9238c'),(1146,'VL-05 Targeted suppressed VL test results','','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ca8302ef-0acb-4fa6-9767-2e228b2423c3\" retired=\"false\">\n  <name>VL-05 Targeted suppressed VL test results</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-08-05 12:25:43 UTC</dateCr