g.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1195</id>\n  <query>select obs_ml_clients.person_id&#xd;\nfrom obs os&#xd;\ninner join location l on os.location_id = l.location_id&#xd;\ninner join &#xd;\n(&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id in (&#xd;\n						select person_id&#xd;\n						from &#xd;\n							(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n							 from obs oss&#xd;\n							 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n							 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n							 group by p.person_id&#xd;\n							 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 29) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n     AND obs_ml_clients.person_id in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n									 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 07:32:13',4,'2024-02-15 14:06:30',4,0,NULL,NULL,NULL,'8d2c7d4f-adbf-4aa0-bd9e-e19ce887a64f'),(1196,'TX_ML-02 Clients who are current on ART at reporting period and experienced IIT<3months','TX_ML-02 Clients who are current on ART at reporting period and experienced IIT<3months','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ed95842b-5f50-4afe-89c1-b1761191123e\" retired=\"false\">\n  <name>TX_ML-02 Clients who are current on ART at reporting period and experienced IIT&lt;3months</name>\n  <description>TX_ML-02 Clients who are current on ART at reporting period and experienced IIT&lt;3months</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:02:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-15 08:37:28 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>startDate</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>endDate</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1196</id>\n  <query>select obs_ml_clients.person_id&#xd;\nfrom obs os&#xd;\ninner join location l on os.location_id = l.location_id&#xd;\ninner join &#xd;\n(&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id in (&#xd;\n						select person_id&#xd;\n						from &#xd;\n							(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n							 from obs oss&#xd;\n							 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n							 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n							 group by p.person_id&#xd;\n							 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 29) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n	 -- INITIATED ON ART LESS THAN 3 MONTHS AGO&#xd;\n	 AND obs_ml_clients.person_id in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 2249&#xd;\n			AND datediff(CAST(:endDate AS DATE), os.value_datetime) BETWEEN 0 AND 90						&#xd;\n	 )&#xd;\n	 -- NOT Transfered Out to Another Site&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 4155 and os.value_coded = 2146&#xd;\n			AND os.obs_datetime &lt;= CAST(:endDate AS DATE)						&#xd;\n	 )&#xd;\n	 -- NOT DEAD&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n									 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 07:32:54',4,'2024-02-15 14:07:28',4,0,NULL,NULL,NULL,'ed95842b-5f50-4afe-89c1-b1761191123e'),(1197,'TX_ML-03 Clients who are current on ART at reporting period and experienced IIT_6+months','TX_ML-03 Clients who are current on ART at reporting period and experienced IIT_6+months','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"11fdf33c-0d64-4c86-8ece-f8eb55ed6119\" retired=\"false\">\n  <name>TX_ML-03 Clients who are current on ART at reporting period and experienced IIT_6+months</name>\n  <description>TX_ML-03 Clients who are current on ART at reporting peri