AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 29) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n	 -- INITIATED ON ART MORE THAN 3 MONTHS AGO&#xd;\n	 AND obs_ml_clients.person_id in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 2249&#xd;\n			AND datediff(CAST(:endDate AS DATE), os.value_datetime) &gt;= 180						&#xd;\n	 )&#xd;\n	 -- NOT Transfered Out to Another Site&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 4155 and os.value_coded = 2146&#xd;\n			AND os.obs_datetime &lt;= CAST(:endDate AS DATE)						&#xd;\n	 )&#xd;\n	 -- NOT DEAD&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n									 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 07:34:20',4,'2024-02-15 14:14:36',4,0,NULL,NULL,NULL,'11fdf33c-0d64-4c86-8ece-f8eb55ed6119'),(1198,'TX_ML-04 Clients who are current on ART at reporting period and experienced IIT_TOut','TX_ML-04 Clients who are current on ART at reporting period and experienced IIT_TOut','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d19bded0-5e8e-4aeb-a41f-f5c6921d90a9\" retired=\"false\">\n  <name>TX_ML-04 Clients who are current on ART at reporting period and experienced IIT_TOut</name>\n  <description>TX_ML-04 Clients who are current on ART at reporting period and experienced IIT_TOut</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:05:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-15 09:01:14 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"9\">\n      <name>endDateas</name>\n      <label>endDateas</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1198</id>\n  <query>select obs_ml_clients.person_id&#xd;\nfrom obs os&#xd;\ninner join location l on os.location_id = l.location_id&#xd;\ninner join &#xd;\n(&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id in (&#xd;\n						select person_id&#xd;\n						from &#xd;\n							(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n							 from obs oss&#xd;\n							 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n							 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n							 group by p.person_id&#xd;\n							 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 1) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 0) as Missed_Greater_Than_0Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 0) as Missed_Greater_Than_0Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n	 -- Transfered Out to Another Site&#xd;\n	 AND obs_ml_clients.person_id in (&#xd;\n			&#xd;\n			select tout_clients.person_id&#xd;\n				from&#xd;\n				(select B.person_id, B.obs_group_id, B.obs_datetime AS latest_consultation&#xd;\n					from obs B&#xd;\n					inner join&#xd;\n					(select person_id, max(obs_datetime), SUBSTRING(max(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n					from obs where concept_id = 2403&#xd;\n					and obs_datetime &lt;= cast(:endDate AS date)&#xd;\n					and voided = 0&#xd;\n					group by person_id) as A&#xd;\n					on A.observation_id = B.obs_group_id&#xd;\n					where concept_id = 2398&#xd;\n					and A.observation_id = B.obs_group_id&#xd;\n					and voided = 0&#xd;\n					group by B.person_id&#xd;\n				) as tout_clients&#xd;\n				where tout_clients.latest_consultation &lt;= cast(:endDate AS date)						&#xd;\n	 )&#xd;\n	 -- NOT DEAD&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n	 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 07:35:17',4,'2024-02-15 14:31:14',4,0,NULL,NULL,NULL,'d19bded0-5e8e-4aeb-a41f-f5c6921d90a9'),(1199,'TX_ML-05 Clients who are current on ART at reporting period and experienced IIT_Stopped','TX_ML-05 Clients who are current on ART at reporting period and experienced IIT_Stopped','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"436959a2-8534-4a1e-9e76-3baf516b8620\" retired=\"false\">\n  <name>TX_ML-05 Clients who are current on ART at reporting period and experienced IIT_Stopped</name>\n  <description>TX_ML-05 Clients who are current on ART at reporting period and experienced IIT_Stopped</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:06:20 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-15 09:02:17 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1199</id>\n  <query>select obs_ml_clients.person_id&#xd;\nfrom obs os&#xd;\ninner join location l on os.location_id = l.location_id&#xd;\ninner join &#xd;\n(&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id in (&#xd;\n						select person_id&#xd;\n						from &#xd;\n							(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n							 from obs oss&#xd;\n							 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n							 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n							 group by p.person_id&#xd;\n							 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 29) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n	 -- ART TREATMENT INTERRUPTION/REFUSED OR STOPPED&#xd;\n	 AND obs_ml_clients.person_id in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 3701 &#xd;\n			AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)						&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 07:36:20',4,'2024-02-15 14:32:17',4,0,NULL,NULL,NULL,'436959a2-8534-4a1e-9e76-3baf516b8620'),(1200,'TX_RTT-01 Clients with IIT in previous period who restarted ARV\'s during current period','TX_RTT-01 Clients with IIT in previous period who restarted ARV\'s during current period','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2ada18e8-c557-4e96-ac65-84648ec56b7f\" retired=\"false\">\n  <name>TX_RTT-01 Clients with IIT in previous period who restarted ARV&apos;s during current period</name>\n  <description>TX_RTT-01 Clients with IIT in previous period who restarted ARV&apos;s during current period</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:07:07 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-09-17 02:07:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1200</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o&#xd;\n-- PATIENTS WITH NO CLINICAL CONTACT OR ARV PICK-UP FOR GREATER THAN 28 DAYS&#xd;\n-- SINCE THEIR LAST EXPECTED CONTACT WHO RESTARTED ARVs WITHIN THE REPORTING PERIOD&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN patient ON o.person_id = patient.patient_id&#xd;\nAND patient.voided = 0 AND o.voided = 0&#xd;\nAND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n )&#xd;\n&#xd;\n -- Client Seen: As either patient OR Treatment Buddy&#xd;\n AND (						 &#xd;\n		 o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n				AND os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n		 &#xd;\n		 -- Client Seen and Date Restarted picked &#xd;\n		 OR o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where os.concept_id = 3708 AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n )&#xd;\n -- Still on treatment at the end of the reporting period&#xd;\n AND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &gt;= cast(:startDate as DATE) and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(:endDate AS DATE), latest_follow_up) &lt;= 28) as Still_On_Treatment_End_Period&#xd;\n )&#xd;\n &#xd;\n -- Transfered Out to Another Site during thier latest encounter before the start date&#xd;\n AND o.person_id not in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS last_obs_tout&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 4155 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having last_obs_tout = 2146) as Transfered_Out_In_Last_Encounter&#xd;\n )&#xd;\n &#xd;\n-- NOT Transfered In from another Site&#xd;\n AND o.person_id not in (&#xd;\n		select os.person_id &#xd;\n		from obs os&#xd;\n		where (os.concept_id = 2253 AND DATE(os.value_datetime) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE))&#xd;\n		AND os.voided = 0					&#xd;\n )						 &#xd;\n &#xd;\n AND o.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n )&#xd;\n &#xd;\n INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE (o.location_id =:location or parent_location  =:location)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 04:07:07',4,'2021-09-17 04:07:22',4,0,NULL,NULL,NULL,'2ada18e8-c557-4e96-ac65-84648ec56b7f'),(1201,'Continuation ART Clients Seen ','Continuation ART Clients Seen  excl Transfers In, TxRTT','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6d452652-2e45-4009-a6fc-a00231e470ce\" retired=\"false\">\n  <name>Continuation ART Clients Seen </name>\n  <description>Continuation ART Clients Seen  excl Transfers In, TxRTT</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:08:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-09-17 02:09:23 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1201</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id,&#xd;\n                                   patient_identifier.identifier AS patientIdentifier,&#xd;\n                                   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                                   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                                   person.gender AS Gender,&#xd;\n                                   observed_age_group.name AS age_group,&#xd;\n								   observed_age_group.sort_order AS sort_order&#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n								 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n								 AND CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n								 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n									  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n									  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n           WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS NEWLY INITIATED ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 &#xd;\n					AND MONTH(o.value_datetime) &gt;= MONTH(CAST(:startDate AS DATE)) &#xd;\n					AND MONTH(o.value_datetime) &lt;= MONTH(CAST(:endDate AS DATE))&#xd;\n					AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													AND CAST(oss.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n													AND CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													AND CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)&#xd;\n							&#xd;\n							&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														AND CAST(oss.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n														AND CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														AND CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)		&#xd;\n						)&#xd;\n					)&#xd;\n&#xd;\n-- Exclude Transfers In&#xd;\nAND Clients_Seen.Id not in (&#xd;\n						select o.person_id&#xd;\n						from obs o &#xd;\n						INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						INNER JOIN person ON patient.patient_id = person.person_id&#xd;\n  					    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						where concept_id = 3634 and o.value_coded = 2095&#xd;\n						and CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n						and CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						and CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n						and o.voided = 0)&#xd;\n&#xd;\n&#xd;\nAND Clients_Seen.Id not in (&#xd;\n&#xd;\nselect distinct (o.person_id)&#xd;\nfrom obs o&#xd;\n-- PATIENTS WITH NO CLINICAL CONTACT OR ARV PICK-UP FOR GREATER THAN 28 DAYS&#xd;\n-- SINCE THEIR LAST EXPECTED CONTACT WHO RESTARTED ARVs WITHIN THE REPORTING PERIOD&#xd;\n-- inner join location l on o.location_id = l.location_id&#xd;\n   INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n   INNER JOIN person ON patient.patient_id = person.person_id&#xd;\n   INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n   AND patient.voided = 0 AND o.voided = 0&#xd;\nwhere o.person_id in (&#xd;\n		select person_id&#xd;\n		from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n )&#xd;\n&#xd;\n  AND (						 &#xd;\n		 o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n				AND os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n		 &#xd;\n		 -- Client Seen and Date Restarted picked &#xd;\n		 OR o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where os.concept_id = 3708 AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n )&#xd;\n&#xd;\n -- Still on treatment at the end of the reporting period&#xd;\n AND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &gt;= cast(:startDate as DATE) and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(:endDate AS DATE), latest_follow_up) &lt;= 28) as Still_On_Treatment_End_Period&#xd;\n )&#xd;\n &#xd;\n -- Transfered Out to Another Site during thier latest encounter before the start date&#xd;\n AND o.person_id not in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS last_obs_tout&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 4155 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having last_obs_tout = 2146) as Transfered_Out_In_Last_Encounter&#xd;\n )&#xd;\n&#xd;\n-- NOT Transfered In from another Site&#xd;\n AND o.person_id not in (&#xd;\n		select os.person_id &#xd;\n		from obs os&#xd;\n		where (os.concept_id = 2253 AND DATE(os.value_datetime) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE))&#xd;\n		AND os.voided = 0					&#xd;\n )&#xd;\n&#xd;\n AND o.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n ) 	 &#xd;\n&#xd;\n))</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 04:08:18',4,'2021-09-17 04:09:23',4,0,NULL,NULL,NULL,'6d452652-2e45-4009-a6fc-a00231e470ce'),(1202,'Continuation ART Clients On MMD','Continuation ART Clients On MMD excl Seen, Transfers In, TxRTT','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6c3b70a0-3830-4598-aba2-92ac32c4d52d\" retired=\"false\">\n  <name>Continuation ART Clients On MMD</name>\n  <description>Continuation ART Clients On MMD excl Seen, Transfers In, TxRTT</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:10:59 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-09-17 02:11:17 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1202</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n    (SELECT Id, patientIdentifier , patientName, Age, Gender, age_group, &apos;Seen_Previous&apos; AS &apos;Program_Status&apos;, sort_order&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND CAST(os.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) &gt;= MONTH(CAST(:startDate AS DATE)) &#xd;\n							AND MONTH(os.value_datetime) &lt;= MONTH(CAST(:endDate AS DATE))&#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													AND CAST(oss.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n													AND CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													AND CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n			-- Transfers In	&#xd;\n									select o.person_id&#xd;\n									from obs o &#xd;\n									INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n									INNER JOIN person ON patient.patient_id = person.person_id&#xd;\n									INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n									where concept_id = 3634 and o.value_coded = 2095&#xd;\n									and CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n									and CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n									and CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n									and o.voided = 0&#xd;\n&#xd;\n&#xd;\n						)&#xd;\n&#xd;\n		and active_clients.person_id  not in (&#xd;\n&#xd;\n								select distinct (o.person_id)&#xd;\n								from obs o&#xd;\n								-- PATIENTS WITH NO CLINICAL CONTACT OR ARV PICK-UP FOR GREATER THAN 28 DAYS&#xd;\n								-- SINCE THEIR LAST EXPECTED CONTACT WHO RESTARTED ARVs WITHIN THE REPORTING PERIOD&#xd;\n								-- inner join location l on o.location_id = l.location_id&#xd;\n								INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n								INNER JOIN person ON patient.patient_id = person.person_id&#xd;\n								INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n								AND patient.voided = 0 AND o.voided = 0&#xd;\n								where o.person_id in (&#xd;\n										select person_id&#xd;\n										from &#xd;\n										(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n										from obs oss&#xd;\n										inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n										and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n										group by p.person_id&#xd;\n										having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n								)&#xd;\n&#xd;\n								AND (						 &#xd;\n										o.person_id in (&#xd;\n												select distinct os.person_id&#xd;\n												from obs os&#xd;\n												where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n												AND os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n										)&#xd;\n										&#xd;\n										-- Client Seen and Date Restarted picked &#xd;\n										OR o.person_id in (&#xd;\n												select distinct os.person_id&#xd;\n												from obs os&#xd;\n												where os.concept_id = 3708 AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n										)&#xd;\n								)&#xd;\n&#xd;\n								-- Still on treatment at the end of the reporting period&#xd;\n								AND o.person_id in (&#xd;\n									select person_id&#xd;\n									from &#xd;\n										(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n										from obs oss&#xd;\n										inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n										and oss.obs_datetime &gt;= cast(:startDate as DATE) and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n										group by p.person_id&#xd;\n										having datediff(CAST(:endDate AS DATE), latest_follow_up) &lt;= 28) as Still_On_Treatment_End_Period&#xd;\n								)&#xd;\n								&#xd;\n								-- Transfered Out to Another Site during thier latest encounter before the start date&#xd;\n								AND o.person_id not in (&#xd;\n									select person_id&#xd;\n									from &#xd;\n										(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS last_obs_tout&#xd;\n										from obs oss&#xd;\n										inner join person p on oss.person_id=p.person_id and oss.concept_id = 4155 and oss.voided=0&#xd;\n										and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n										group by p.person_id&#xd;\n										having last_obs_tout = 2146) as Transfered_Out_In_Last_Encounter&#xd;\n								)&#xd;\n&#xd;\n								-- NOT Transfered In from another Site&#xd;\n								AND o.person_id not in (&#xd;\n										select os.person_id &#xd;\n										from obs os&#xd;\n										where (os.concept_id = 2253 AND DATE(os.value_datetime) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE))&#xd;\n										AND os.voided = 0					&#xd;\n								)&#xd;\n&#xd;\n								AND o.person_id not in (&#xd;\n											select person_id &#xd;\n											from person &#xd;\n											where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n											and dead = 1&#xd;\n								) 	 &#xd;\n														&#xd;\n														)								 &#xd;\n&#xd;\n					 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS Seen_Previous_ART_Clients&#xd;\nORDER BY Seen_Previous_ART_Clients.patientName)&#xd;\n)AS Seen_Prev)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 04:10:59',4,'2021-09-17 04:11:17',4,0,NULL,NULL,NULL,'6c3b70a0-3830-4598-aba2-92ac32c4d52d'),(1203,'Continuation ART Clients Transferred In','Continuation ART Clients Transferred In','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"47d0abca-f9d5-48b3-9151-647a732e9a76\" retired=\"false\">\n  <name>Continuation ART Clients Transferred In</name>\n  <description>Continuation ART Clients Transferred In</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:12:22 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-09-17 02:12:38 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1203</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in&#xd;\n(select o.person_id&#xd;\n									from obs o &#xd;\n									INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n									INNER JOIN person ON patient.patient_id = person.person_id&#xd;\n									INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n									where concept_id = 3634 and o.value_coded = 2095&#xd;\n									and CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n									and CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n									and CAST(o.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n									and o.voided = 0)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-17 04:12:22',4,'2021-09-17 04:12:38',4,0,NULL,NULL,NULL,'47d0abca-f9d5-48b3-9151-647a732e9a76'),(1204,'CI46: TxML Died','TxML Died','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"8952b48b-2d4e-4f46-8996-b6fc498327f5\" retired=\"false\">\n  <name>CI46: TxML Died</name>\n  <description>TxML Died</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-17 02:14:41 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-09-17 06:22:13 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1204</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"8d2c7d4f-adbf-4aa0-bd9e-e19ce887a64f\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n     