ndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"190\">\n      <name>TOutM25-29</name>\n      <label>CI49:TxML Transferred Out-Males-25-29yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"53\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"191\">\n      <name>TOutM30-34</name>\n      <label>CI49:TxML Transferred Out-Males-30-34yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"55\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"192\">\n      <name>TOutM35-39</name>\n      <label>CI49:TxML Transferred Out-Males-35-39yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"57\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"193\">\n      <name>TOutM40-44</name>\n      <label>CI49:TxML Transferred Out-Males-40-44yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"59\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"194\">\n      <name>TOutM45-49</name>\n      <label>CI49:TxML Transferred Out-Males-45-49yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"61\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"195\">\n      <name>TOutM5-9</name>\n      <label>CI49:TxML Transferred Out-Males-05-09yrs</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"63\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"196\">\n      <name>TOutM50PLu</name>\n      <label>CI49:TxML Transferred Out-Males-50Plus</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"65\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"197\">\n      <name>TOutM&lt;1yr</name>\n      <label>CI49:TxML Transferred Out-Males-Under1yr</label>\n      <indicator reference=\"173\"/>\n      <dimensionOptions reference=\"67\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n  </columns>\n</org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition>','2021-09-21 10:52:57',4,'2022-09-23 08:18:33',4,0,NULL,NULL,NULL,'81bde35e-8217-4ef4-988a-f578a52fd5d9'),(1217,'PITC_New_Positive_OPD','HTS Report - OPD location - PITC New Pos ','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c9db805d-4bea-4f9a-a3ac-0325d0a27fa9\" retired=\"false\">\n  <name>PITC_New_Positive_OPD</name>\n  <description>HTS Report - OPD location - PITC New Pos </description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 11:38:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:13:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1217</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;New&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1738&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2147&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded in (2191,2190,2192,2139,4791,2143)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 13:38:55',4,'2025-11-05 03:13:51',4,0,NULL,NULL,NULL,'c9db805d-4bea-4f9a-a3ac-0325d0a27fa9'),(1218,'PITC_New_Negative_OPD','HTS Report - OPD location - PITC New Negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e6471d7a-2acd-4bb6-9124-d757bc31a72b\" retired=\"false\">\n  <name>PITC_New_Negative_OPD</name>\n  <description>HTS Report - OPD location - PITC New Negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 13:11:08 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 00:26:14 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1218</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;New&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1016&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2147&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded in (2191,2190,2192,2139,4791,2143)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 15:11:08',4,'2025-11-05 02:26:14',4,0,NULL,NULL,NULL,'e6471d7a-2acd-4bb6-9124-d757bc31a72b'),(1219,'PITC_Repeat_Positive_OPD','HTS Report - OPD location - PITC Repeat Pos','org.openmrs.module.reporting.cohort.definition.CohortDefinition','o