ame,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1738&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2146&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded = 4236&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 15:35:10',4,'2025-11-05 02:54:42',4,0,NULL,NULL,NULL,'117426a7-ca44-4b9b-b4c4-72f565c9b534'),(1224,'PITC_Repeat_Negative_Adolescent',' HTS Report - Adolescent location - PITC Repeat Negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"eb4559df-958e-40ff-a863-abdcfcf257e8\" retired=\"false\">\n  <name>PITC_Repeat_Negative_Adolescent</name>\n  <description> HTS Report - Adolescent location - PITC Repeat Negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 13:39:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 00:38:03 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1224</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;Repeat&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1016&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2146&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded = 4236&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 15:39:06',4,'2025-11-05 02:38:03',4,0,NULL,NULL,NULL,'eb4559df-958e-40ff-a863-abdcfcf257e8'),(1225,'PITC_New_Positive_ART','HTS Report - ART location - PITC New Positive','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"1590fd93-0b9e-4e42-93b7-98ce50da42a9\" retired=\"false\">\n  <name>PITC_New_Positive_ART</name>\n  <description>HTS Report - ART location - PITC New Positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 13:46:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:11:17 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1225</id>\n  <query>/* PITC New Negative (ART) — MySQL 5.7 compatible, encounter-scoped, mutually exclusive */&#xd;\n&#xd;\nSELECT DISTINCT p.patient_id AS Id&#xd;\nFROM patient p&#xd;\nJOIN person per ON per.person_id = p.patient_id AND per.voided = 0&#xd;\n&#xd;\n/* Base: obs filtered to period */&#xd;\nJOIN (&#xd;\n  SELECT&#xd;\n    o.person_id, o.encounter_id, o.location_id, o.obs_group_id, o.obs_datetime,&#xd;\n    o.concept_id, o.value_coded&#xd;\n  FROM obs o&#xd;\n  WHERE o.voided = 0&#xd;\n    AND CAST(o.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n) AS obsip ON obsip.person_id = p.patient_id&#xd;\n&#xd;\n/* HIV Result = Negative — tie to this encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id, location_id, obs_group_id, obs_datetime&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id, location_id, obs_group_id, obs_datetime&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 2165      /* HTC, Final HIV status */&#xd;\n      AND value_coded = 1738     /* Negative */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS neg_res&#xd;\n  ON neg_res.person_id = p.patient_id&#xd;\n AND neg_res.encounter_id = obsip.encounter_id&#xd;\n&#xd;\n/* PITC = Yes in same encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4228      /* HTC, Initiated Testing and Counseling */&#xd;\n      AND value_coded = 4227     /* Yes */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS pitc&#xd;\n  ON pitc.person_id = p.patient_id&#xd;\n AND pitc.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* NEW tester in same encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4798      /* HTC, History of Previous Testing */&#xd;\n      AND value_coded = 2147     /* NO */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS newf&#xd;\n  ON newf.person_id = p.patient_id&#xd;\n AND newf.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* HTS testing form item present in same encounter (2386 per your ART view) */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 2386      /* HIV Testing and Counseling Intake Template */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS hts_form&#xd;\n  ON hts_form.person_id = p.patient_id&#xd;\n AND hts_form.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* ART service point in same encounter: concept 4238 in (4234,3632,4816) */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4238        /* --HTC, Mode of Entry Point */&#xd;\n      AND value_coded IN (4234, 3632, 4816)  /* ART,PEP,PrEP */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS sp&#xd;\n  ON sp.person_id = p.patient_id&#xd;\n AND sp.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* Location filter (site or child of selected parent) */&#xd;\nJOIN location l ON l.location_id = neg_res.location_id&#xd;\nWHERE p.voided = 0&#xd;\n  AND (neg_res.location_id = :location OR l.parent_location = :location)&#xd;\n&#xd;\n/* Mutual exclusion: no REPEAT flag on this encounter */&#xd;\nAND NOT EXISTS (&#xd;\n  SELECT 1&#xd;\n  FROM obs rf&#xd;\n  WHERE rf.voided = 0&#xd;\n    AND rf.person_id   = p.patient_id&#xd;\n    AND rf.encounter_id = neg_res.encounter_id&#xd;\n    AND rf.concept_id  = 4798&#xd;\n          /* HTC, History of Previous Testing */&#xd;\n    AND rf.value_coded = 2146          /* YES */&#xd;\n    AND CAST(rf.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n)&#xd;\n&#xd;\n/* (Optional) belt-and-braces: exclude any REPEAT flag anywhere in the period */&#xd;\nAND NOT EXISTS (&#xd;\n  SELECT 1&#xd;\n  FROM obs rf2&#xd;\n  WHERE rf2.voided = 0&#xd;\n    AND rf2.person_id = p.patient_id&#xd;\n    AND rf2.concept_id = 4798         /* HTC, History of Previous Testing */&#xd;\n    AND rf2.value_coded = 2146         /* YES */&#xd;\n    AND CAST(rf2.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n);&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 15:46:15',4,'2025-11-05 03:11:17',4,0,NULL,NULL,NULL,'1590fd93-0b9e-4e42-93b7-98ce50da42a9'),(1226,'PITC_New_Negative_ART','HTS Report - ART location - PITC New Negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d7b22cfb-e38a-4764-8e7c-c1950dee7bb1\" retired=\"false\">\n  <name>PITC_New_Negative_ART</name>\n  <description>HTS Report - ART location - PITC New Negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 13:47:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 00:21:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1226</id>\n  <query>/* PITC New Negative (ART) — MySQL 5.7 compatible, encounter-scoped, mutually exclusive */&#xd;\n&#xd;\nSELECT DISTINCT p.patient_id AS Id&#xd;\nFROM patient p&#xd;\nJOIN person per ON per.person_id = p.patient_id AND per.voided = 0&#xd;\n&#xd;\n/* Base: obs filtered to period */&#xd;\nJOIN (&#xd;\n  SELECT&#xd;\n    o.person_id, o.encounter_id, o.location_id, o.obs_group_id, o.obs_datetime,&#xd;\n    o.concept_id, o.value_coded&#xd;\n  FROM obs o&#xd;\n  WHERE o.voided = 0&#xd;\n    AND CAST(o.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n) AS obsip ON obsip.person_id = p.patient_id&#xd;\n&#xd;\n/* HIV Result = Negative — tie to this encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id, location_id, obs_group_id, obs_datetime&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id, location_id, obs_group_id, obs_datetime&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 2165      /* HTC, Final HIV status */&#xd;\n      AND value_coded = 1016     /* Negative */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS neg_res&#xd;\n  ON neg_res.person_id = p.patient_id&#xd;\n AND neg_res.encounter_id = obsip.encounter_id&#xd;\n&#xd;\n/* PITC = Yes in same encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4228      /* HTC, Initiated Testing and Counseling */&#xd;\n      AND value_coded = 4227     /* Yes */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS pitc&#xd;\n  ON pitc.person_id = p.patient_id&#xd;\n AND pitc.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* NEW tester in same encounter */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4798      /* HTC, History of Previous Testing */&#xd;\n      AND value_coded = 2147     /* NO */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS newf&#xd;\n  ON newf.person_id = p.patient_id&#xd;\n AND newf.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* HTS testing form item present in same encounter (2386 per your ART view) */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 2386      /* HIV Testing and Counseling Intake Template */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS hts_form&#xd;\n  ON hts_form.person_id = p.patient_id&#xd;\n AND hts_form.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* ART service point in same encounter: concept 4238 in (4234,3632,4816) */&#xd;\nJOIN (&#xd;\n  SELECT person_id, encounter_id&#xd;\n  FROM (&#xd;\n    SELECT person_id, encounter_id&#xd;\n    FROM obs&#xd;\n    WHERE voided = 0&#xd;\n      AND concept_id = 4238        /* --HTC, Mode of Entry Point */&#xd;\n      AND value_coded IN (4234, 3632, 4816)  /* ART,PEP,PrEP */&#xd;\n      AND CAST(obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n  ) x&#xd;\n  GROUP BY person_id, encounter_id&#xd;\n) AS sp&#xd;\n  ON sp.person_id = p.patient_id&#xd;\n AND sp.encounter_id = neg_res.encounter_id&#xd;\n&#xd;\n/* Location filter (site or child of selected parent) */&#xd;\nJOIN location l ON l.location_id = neg_res.location_id&#xd;\nWHERE p.voided = 0&#xd;\n  AND (neg_res.location_id = :location OR l.parent_location = :location)&#xd;\n&#xd;\n/* Mutual exclusion: no REPEAT flag on this encounter */&#xd;\nAND NOT EXISTS (&#xd;\n  SELECT 1&#xd;\n  FROM obs rf&#xd;\n  WHERE rf.voided = 0&#xd;\n    AND rf.person_id   = p.patient_id&#xd;\n    AND rf.encounter_id = neg_res.encounter_id&#xd;\n    AND rf.concept_id  = 4798          /* HTC, History of Previous Testing */&#xd;\n    AND rf.value_coded = 2146          /* YES */&#xd;\n    AND CAST(rf.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n)&#xd;\n&#xd;\n/* (Optional) belt-and-braces: exclude any REPEAT flag anywhere in the period */&#xd;\nAND NOT EXISTS (&#xd;\n  SELECT 1&#xd;\n  FROM obs rf2&#xd;\n  WHERE rf2.voided = 0&#xd;\n    AND rf2.person_id = p.patient_id&#xd;\n    AND rf2.concept_id = 4798         /* HTC, History of Previous Testing */&#xd;\n    AND rf2.value_coded = 2146         /* YES */&#xd;\n    AND CAST(rf2.obs_datetime AS DATE) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n);&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 15:47:57',4,'2025-11-05 02:21:24',4,0,NULL,NULL,NULL,'d7b22cfb-e38a-4764-8e7c-c1950dee7bb1'),(1227,'PITC_Repeat_Positive_ART','HTS Report - ART location - PITC Repeat Positive','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"037fb6a1-3ad9-421d-851b-29b857c36013\" retired=\"false\">\n  <name>PITC_Repeat_Positive_ART</name>\n  <description>HTS Report - ART location - PITC Repeat Positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 13:49:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2026-03-20 14:35:13 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</ty