hortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"79da84b1-174a-4c1a-b472-3c4ef965962f\" retired=\"false\">\n  <name>PITC_Repeat_Positive_Outreach</name>\n  <description> HTS Report - Outreach location - PITC Repeat Positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 14:35:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:00:27 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1239</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;Repeat&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1738&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2146&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded = 4796&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 16:35:30',4,'2025-11-05 03:00:27',4,0,NULL,NULL,NULL,'79da84b1-174a-4c1a-b472-3c4ef965962f'),(1240,'PITC_Repeat_Negative_Outreach','HTS Report - Outreach location - PITC Repeat Negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5dceb80b-1b6a-45e6-9670-b209e3960b3b\" retired=\"false\">\n  <name>PITC_Repeat_Negative_Outreach</name>\n  <description>HTS Report - Outreach location - PITC Repeat Negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 14:37:27 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 00:48:15 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1240</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;Repeat&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1016&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2146&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded = 4796&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 16:37:27',4,'2025-11-05 02:48:15',4,0,NULL,NULL,NULL,'5dceb80b-1b6a-45e6-9670-b209e3960b3b'),(1241,'PITC_New_Positive_SelfTest','HTS Report - Self Test - PITC New Positive','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a649af2e-c356-4c21-aae4-8ecf5325699e\" retired=\"false\">\n  <name>PITC_New_Positive_SelfTest</name>\n  <description>HTS Report - Self Test - PITC New Positive</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 14:42:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 01:15:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1241</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;New&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1738 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1738 -- HIV Positive&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 -- AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2147&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n&#xd;\n                 Inner Join (&#xd;\n                  select encounter_id,CAST(date_created as Date) as current_conc&#xd;\n                  from obs &#xd;\n                  where concept_id = 4845 and value_coded = 4847&#xd;\n                 ) as rapids&#xd;\n                 on o.encounter_id = rapids.encounter_id&#xd;\n                  -- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 &#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 AND testingform.current_conc=rapids.current_conc&#xd;\n                 inner join&#xd;\n                (&#xd;\n                  select os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n                  where os.concept_id = 4238 and os.value_coded = 4237&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                &#xd;\n                  )as mode&#xd;\n                  ON o.person_id = mode.person_id&#xd;\n                  AND pitc.encounter = mode.encounter&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n )&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 16:42:18',4,'2025-11-05 03:15:51',4,0,NULL,NULL,NULL,'a649af2e-c356-4c21-aae4-8ecf5325699e'),(1242,'PITC_New_Negative_SelfTest','HTS Report - Self Test - PITC New Negative','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"bfc795aa-cf34-4129-8765-08d8c5a6c265\" retired=\"false\">\n  <name>PITC_New_Negative_SelfTest</name>\n  <description>HTS Report - Self Test - PITC New Negative</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-09-23 14:45:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2025-11-05 00:30:25 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1242</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n&#xd;\n  (SELECT Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age, Gender, age_group, &apos;PITC&apos; AS &apos;HIV_Testing_Initiation&apos;&#xd;\n        , &apos;New&apos; AS &apos;Testing_History&apos; , HIV_Status, current_conc, encounter, sort_order&#xd;\n    FROM&#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                         patient_identifier.identifier AS patientIdentifier,&#xd;\n                         concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                         floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                         (select name from concept_name cn where cn.concept_id = 1016 and concept_name_type=&apos;FULLY_SPECIFIED&apos;) AS HIV_Status,&#xd;\n                         person.gender AS Gender,&#xd;\n                         observed_age_group.name AS age_group,&#xd;\n                         pitc.current_conc,&#xd;\n                         o.encounter_id as encounter,&#xd;\n                         observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n                -- HTS CLIENTS WITH HIV STATUS BY SEX AND AGE&#xd;\n                 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                 AND o.concept_id = 2165 and o.value_coded = 1016&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 &#xd;\n                 -- PROVIDER INITIATED TESTING AND COUNSELING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4228 and os.value_coded = 4227&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as pitc&#xd;\n                 on o.person_id = pitc.person_id&#xd;\n                 AND pitc.encounter = o.encounter_id             &#xd;\n                  -- NEW TESTER, DOES NOT HAVE HISTORY OF PREVIOUS TESTING&#xd;\n                 Inner Join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 4798 and os.value_coded = 2147&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 ) as repeater&#xd;\n                 on o.person_id = repeater.person_id&#xd;\n                 and pitc.current_conc = repeater.current_conc&#xd;\n                 &#xd;\n                 	-- Observation be in HIV Testing form&#xd;\n                 inner join (&#xd;\n                  select distinct os.person_id, CAST(os.date_created as Date) as current_conc&#xd;\n                  from obs os&#xd;\n                  INNER JOIN patient ON os.person_id = patient.patient_id&#xd;\n                  where os.concept_id = 2386&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND os.voided = 0&#xd;\n                 )as testingform&#xd;\n                 on o.person_id = testingform.person_id&#xd;\n                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n               WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                ) AS HTSClients_HIV_Status&#xd;\n    ORDER BY HTSClients_HIV_Status.HIV_Status, HTSClients_HIV_Status.Age)&#xd;\n  &#xd;\n&#xd;\n) AS HTS_Status_Detailed&#xd;\n&#xd;\n inner join&#xd;\n(&#xd;\n  select distinct os.person_id, CAST(os.date_created as Date) as current_conc, os.encounter_id as encounter&#xd;\n  from obs os&#xd;\n  INNER JOIN patient ON os.person_id = patient.patient_id &#xd;\n  where os.concept_id = 4238 and os.value_coded = 4237&#xd;\n  AND CAST(os.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n  AND CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n  AND patient.voided = 0 AND os.voided = 0&#xd;\n  group by os.person_id&#xd;\n  )B&#xd;\n  ON B.person_id = HTS_Status_Detailed.Id&#xd;\n  AND HTS_Status_Detailed.encounter = B.encounter)&#xd;\n&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-09-23 16:45:04',4,'2025-11-05 02:30:25',4,0,NULL,NULL,NULL,'bfc795aa-cf34-4129-8765-08d8c5a6c265'),(1243,'PITC_