enmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"04eb3953-22d9-4733-aa50-4a8ed4742edf\" retired=\"false\">\n  <name>VL-04  VL tests performed_recent_3months</name>\n  <description>VL-04 VL tests performed in the recent 3 months</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-12-15 13:35:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-12-16 09:05:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1388</id>\n  <query>Select person_id&#xd;\nFROM&#xd;\n(select oss.person_id, MAX(oss.obs_datetime) as max_observation,CAST(Max(oss.value_datetime) as DATE) as Blood_Drawn_Date&#xd;\n				from obs oss&#xd;\n				where oss.concept_id = 4267 and oss.voided=0&#xd;\n				and oss.value_datetime BETWEEN DATE(DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)) AND date_add(cast(:endDate as datetime), interval 1 day)&#xd;\n				group by oss.person_id) as vl_tests_preformed</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2021-12-15 15:35:47',4,'2021-12-16 11:05:21',4,0,NULL,NULL,NULL,'04eb3953-22d9-4733-aa50-4a8ed4742edf'),(1389,'TPT Continued eRegister Process Report Weekly','Clients Currently on TPT - eRegister Process Report Weekly','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2a45ccbb-5d49-46a5-9c14-86a68c658c0f\" retired=\"false\">\n  <name>TPT Continued eRegister Process Report Weekly</name>\n  <description>Clients Currently on TPT - eRegister Process Report Weekly</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2021-12-16 10:37:22 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2021-12-16 10:51:15 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1389</id>\n  <query>Select Id &#xd;\nfrom&#xd;\n(select distinct patient.patient_id AS Id,&#xd;\n                                   patient_identifier.identifier AS patientIdentifier&#xd;\n        						   from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n	INNER JOIN 