_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4685)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=14 and _weight &lt;=19.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 12:48:50',4,'2023-07-27 12:55:55',4,0,NULL,NULL,NULL,'4477b341-8fb3-4d94-bc1a-cec68c45d5e8'),(1487,'Clients given 4F weighing 14-19.9kg','Clients given 4F weighing 14-19.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"bc68c0e3-f9af-458a-9c48-e498e27e55cf\" retired=\"false\">\n  <name>Clients given 4F weighing 14-19.9kg</name>\n  <description>Clients given 4F weighing 14-19.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 10:49:43 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-07-27 10:42:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1487</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 4F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3680)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=14 and _weight &lt;=19.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 12:49:43',4,'2023-07-27 12:42:09',4,0,NULL,NULL,NULL,'bc68c0e3-f9af-458a-9c48-e498e27e55cf'),(1488,'Clients given 4H weighing 20-24.9kg','Clients given 4H weighing 20-24.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"db7df0b0-048e-4292-8047-aede481f516a\" retired=\"false\">\n  <name>Clients given 4H weighing 20-24.9kg</name>\n  <description>Clients given 4H weighing 20-24.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 10:49:44 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-07-27 10:56:17 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1488</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 4H&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4685)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=20 and _weight &lt;=24.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 12:49:44',4,'2023-07-27 12:56:17',4,0,NULL,NULL,NULL,'db7df0b0-048e-4292-8047-aede481f516a'),(1489,'Clients given 4H weighing 25-34.9kg','Clients given 4H weighing 25-34.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8a0ffc3a-6f13-41d4-9012-80f7df387328\" retired=\"false\">\n  <name>Clients given 4H weighing 25-34.9kg</name>\n  <description>Clients given 4H weighing 25-34.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 10:50:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-07-27 10:56:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1489</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 4H&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4685)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=25 and _weight &lt;=34.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 12:50:30',4,'2023-07-27 12:56:36',4,0,NULL,NULL,NULL,'8a0ffc3a-6f13-41d4-9012-80f7df387328'),(1490,'Clients given 4F weighing 20-24.9kg','Clients given 4F weighing 20-24.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"acf07216-1652-4e83-9d65-6823c59981a8\" retired=\"false\">\n  <name>Clients given 4F weighing 20-24.9kg</name>\n  <description>Clients given 4F weighing 20-24.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 10:50:41 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-07-27 10:42:33 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <l