					on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=6 and _weight &lt;=9.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 13:42:56',4,'2023-08-15 14:07:06',4,0,NULL,NULL,NULL,'d6cf3e57-fba8-4961-83e9-e0c69b152e91'),(1571,'Clients given 6F weighing 6-9.9kg','Clients given 6F weighing 6-9.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"07ebdb1b-42fd-4338-9880-b53a0e857d14\" retired=\"false\">\n  <name>Clients given 6F weighing 6-9.9kg</name>\n  <description>Clients given 6F weighing 6-9.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 11:43:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-15 12:11:18 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1571</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4705)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=6 and _weight &lt;=9.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 13:43:28',4,'2023-08-15 14:11:18',4,0,NULL,NULL,NULL,'07ebdb1b-42fd-4338-9880-b53a0e857d14'),(1572,'Clients given 6A weighing 10-13.9kg','Clients given 6A weighing 10-13.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"de6af126-f558-4acf-b061-982dbfac0025\" retired=\"false\">\n  <name>Clients given 6A weighing 10-13.9kg</name>\n  <description>Clients given 6A weighing 10-13.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 11:43:45 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-15 12:19:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1572</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight&gt;=10 and _weight &lt;=13.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-06-30 13:43:45',4,'2023-08-15 14:19:36',4,0,NULL,NULL,NULL,'de6af126-f558-4acf-b061-982dbfac0025'),(1573,'Clients given 6F weighing 10-13.9kg','Clients given 6F weighing 10-13.9kg','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e77aeb5b-70e2-46a1-9451-be37911a5dc0\" retired=\"false\">\n  <name>Clients given 6F weighing 10-13.9kg</name>\n  <description>Clients given 6F weighing 10-13.9kg</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-06-30 11:44:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-15 12:14:29 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n  