equired>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1814</id>\n  <query>select obs_ml_clients.person_id&#xd;\nfrom obs os&#xd;\ninner join location l on os.location_id = l.location_id&#xd;\ninner join &#xd;\n(&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.person_id in (&#xd;\n						select person_id&#xd;\n						from &#xd;\n							(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n							 from obs oss&#xd;\n							 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n							 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n							 group by p.person_id&#xd;\n							 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) &lt; 29) as On_ART_Beginning_Quarter&#xd;\n				 )&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n		UNION&#xd;\n		select o.person_id&#xd;\n		from obs o&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND patient.voided = 0 AND o.voided = 0&#xd;\n				 AND o.concept_id = 2249 and cast(o.value_datetime as date) &gt;= cast(:startDate as DATE) and cast(o.value_datetime as date) &lt;= cast(:endDate as DATE)&#xd;\n				 AND o.person_id in (&#xd;\n					select person_id&#xd;\n					from &#xd;\n						(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n						 from obs oss&#xd;\n						 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n						 and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n						 group by p.person_id&#xd;\n						 having datediff(CAST(:endDate AS DATE), latest_follow_up) &gt; 28) as Missed_Greater_Than_28Days&#xd;\n				 )&#xd;\n				 INNER JOIN patient_identifier ON patient_identifier.patient_id = patient.patient_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n		group by patient.patient_id&#xd;\n) as obs_ml_clients on os.person_id = obs_ml_clients.person_id&#xd;\nINNER JOIN person ON person.person_id = obs_ml_clients.person_id AND person.voided = 0&#xd;\nINNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE os.location_id =:location or parent_location  =:location&#xd;\n	 -- INITIATED ON ART BETWEEN 3 AND 5 MONTHS AGO&#xd;\n	 AND obs_ml_clients.person_id in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 2249&#xd;\n			AND datediff(CAST(:endDate AS DATE), os.value_datetime) BETWEEN 89 AND 180						&#xd;\n	 )&#xd;\n	 -- NOT Transfered Out to Another Site&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select distinct os.person_id &#xd;\n			from obs os&#xd;\n			where os.concept_id = 4155 and os.value_coded = 2146&#xd;\n			AND os.obs_datetime &lt;= CAST(:endDate AS DATE)						&#xd;\n	 )&#xd;\n	 -- NOT DEAD&#xd;\n	 AND obs_ml_clients.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n	 )&#xd;\nAND obs_ml_clients.person_id not in (&#xd;\n				-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n	 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-08-10 16:33:51',4,'2024-02-15 14:33:32',4,0,NULL,NULL,NULL,'e2a2e29e-040a-45b1-902d-fa25074d52a1'),(1815,'CI63:TxML IIT3-5','TxML IIT3-5','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"781f34cd-9cce-41ef-acbe-b89b0e1257e4\" retired=\"false\">\n  <name>CI63:TxML IIT3-5</name>\n  <description>TxML IIT3-5</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-08-10 11:07:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2022-08-10 11:08:59 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1815</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"e2a2e29e-040a-45b1-902d-fa25074d52a1\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2022-08-10 11:07:17',4,'2022-08-10 11:08:59',4,0,NULL,NULL,NULL,'781f34cd-9cce-41ef-acbe-b89b0e1257e4'),(1816,'TX_RTT-02 Clients with IIT  for < 3 months in previous period who restarted ARV\'s during current period','TX_RTT-02 Clients with IIT  for < 3 months in previous period who restarted ARV\'s during current period','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"505841df-fa38-436c-8463-8a437f536b69\" retired=\"false\">\n  <name>TX_RTT-02 Clients with IIT  for &lt; 3 months in previous period who restarted ARV&apos;s during current period</name>\n  <description>TX_RTT-02 Clients with IIT  for &lt; 3 months in previous period who restarted ARV&apos;s during current period</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-08-23 16:34:31 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-15 08:22:47 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1816</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o&#xd;\n-- PATIENTS WITH NO CLINICAL CONTACT OR ARV PICK-UP FOR GREATER THAN 28 DAYS&#xd;\n-- SINCE THEIR LAST EXPECTED CONTACT WHO RESTARTED ARVs WITHIN THE REPORTING PERIOD&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN patient ON o.person_id = patient.patient_id&#xd;\nAND patient.voided = 0 AND o.voided = 0&#xd;\nAND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) BETWEEN 29 and 90) as Missed_Greater_Than_28Days&#xd;\n )&#xd;\n&#xd;\n -- Client Seen: As either patient OR Treatment Buddy&#xd;\n AND (						 &#xd;\n		 o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n				AND os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n		 &#xd;\n		 -- Client Seen and Date Restarted picked &#xd;\n		 OR o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where os.concept_id = 3708 AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n )&#xd;\n -- Still on treatment at the end of the reporting period&#xd;\n AND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &gt;= cast(:startDate as DATE) and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(:endDate AS DATE), latest_follow_up) &lt;= 28) as Still_On_Treatment_End_Period&#xd;\n )&#xd;\n &#xd;\n -- Transfered Out to Another Site during their latest encounter before the start date&#xd;\n AND o.person_id not in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS last_obs_tout&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 4155 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having last_obs_tout = 2146) as Transfered_Out_In_Last_Encounter&#xd;\n )&#xd;\n &#xd;\n-- NOT Transfered In from another Site&#xd;\n AND o.person_id not in (&#xd;\n		select os.person_id &#xd;\n		from obs os&#xd;\n		where (os.concept_id = 2253 AND DATE(os.value_datetime) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE))&#xd;\n		AND os.voided = 0					&#xd;\n )						 &#xd;\n &#xd;\n AND o.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n )&#xd;\n AND o.person_id not in (&#xd;\n			-- Visitors&#xd;\n			select o.person_id&#xd;\n			from obs o&#xd;\n			inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n)&#xd;\n &#xd;\n INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE (o.location_id =:location or parent_location  =:location)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-08-23 22:04:31',4,'2024-02-15 13:52:47',4,0,NULL,NULL,NULL,'505841df-fa38-436c-8463-8a437f536b69'),(1817,'TX_RTT-03 Clients with IIT for 3-5 months in previous period who restarted ARV\'s during current period','TX_RTT-03 Clients with IIT for 3-5 months in previous period who restarted ARV\'s during current period','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"129f5049-8d6d-4cd9-8922-7cf72b623ab3\" retired=\"false\">\n  <name>TX_RTT-03 Clients with IIT for 3-5 months in previous period who restarted ARV&apos;s during current period</name>\n  <description>TX_RTT-03 Clients with IIT for 3-5 months in previous period who restarted ARV&apos;s during current period</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-08-23 16:42:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-15 08:26:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1817</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o&#xd;\n-- PATIENTS WITH NO CLINICAL CONTACT OR ARV PICK-UP FOR GREATER THAN 28 DAYS&#xd;\n-- SINCE THEIR LAST EXPECTED CONTACT WHO RESTARTED ARVs WITHIN THE REPORTING PERIOD&#xd;\ninner join location l on o.location_id = l.location_id&#xd;\nINNER JOIN patient ON o.person_id = patient.patient_id&#xd;\nAND patient.voided = 0 AND o.voided = 0&#xd;\nAND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(DATE_ADD(CAST(:startDate AS DATE), INTERVAL -1 DAY) AS DATE), latest_follow_up) BETWEEN 89 and 180) as Missed_Between_89_and_180Days&#xd;\n )&#xd;\n&#xd;\n -- Client Seen: As either patient OR Treatment Buddy&#xd;\n AND (						 &#xd;\n		 o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n				AND os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n		 &#xd;\n		 -- Client Seen and Date Restarted picked &#xd;\n		 OR o.person_id in (&#xd;\n				select distinct os.person_id&#xd;\n				from obs os&#xd;\n				where os.concept_id = 3708 AND os.value_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE)&#xd;\n		 )&#xd;\n )&#xd;\n -- Still on treatment at the end of the reporting period&#xd;\n AND o.person_id in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_datetime)), 20) AS latest_follow_up&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 3752 and oss.voided=0&#xd;\n		 and oss.obs_datetime &gt;= cast(:startDate as DATE) and oss.obs_datetime &lt;= cast(:endDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having datediff(CAST(:endDate AS DATE), latest_follow_up) &lt;= 28) as Still_On_Treatment_End_Period&#xd;\n )&#xd;\n &#xd;\n -- Transfered Out to Another Site during their latest encounter before the start date&#xd;\n AND o.person_id not in (&#xd;\n	select person_id&#xd;\n	from &#xd;\n		(select oss.person_id, MAX(oss.obs_datetime) as max_observation, SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) AS last_obs_tout&#xd;\n		 from obs oss&#xd;\n		 inner join person p on oss.person_id=p.person_id and oss.concept_id = 4155 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt; cast(:startDate as DATE)&#xd;\n		 group by p.person_id&#xd;\n		 having last_obs_tout = 2146) as Transfered_Out_In_Last_Encounter&#xd;\n )&#xd;\n &#xd;\n-- NOT Transfered In from another Site&#xd;\n AND o.person_id not in (&#xd;\n		select os.person_id &#xd;\n		from obs os&#xd;\n		where (os.concept_id = 2253 AND DATE(os.value_datetime) BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate AS DATE))&#xd;\n		AND os.voided = 0					&#xd;\n )						 &#xd;\n &#xd;\n AND o.person_id not in (&#xd;\n			select person_id &#xd;\n			from person &#xd;\n			where death_date &lt;= CAST(:endDate AS DATE)&#xd;\n			and dead = 1&#xd;\n )&#xd;\n AND o.person_id not in (&#xd;\n			-- Visitors&#xd;\n				select o.person_id&#xd;\n				from obs o&#xd;\n				inner join&#xd;\n					(&#xd;\n					select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n					SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n					from obs oss&#xd;\n					where oss.concept_id = 3753 &#xd;\n					and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n					group by oss.person_id&#xd;\n					)latest&#xd;\n				on latest.person_id = o.person_id&#xd;\n				where concept_id = 5416&#xd;\n				and o.value_coded =1 and o.voided=0&#xd;\n				and  cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n )&#xd;\n &#xd;\n INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\nWHERE (o.location_id =:location or parent_location  =:location)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2022-08-23 22:12:57',4,'2024-02-15 13:56:51',4,0,NULL,NULL,NULL,'129f5049-8d6d-4cd9-8922-7cf72b623ab3'),(1818,' TX_RTT-04 Clients with IIT for >6 months in previous period who restarted ARV\'s during current period',' TX_RTT-04 Clients with IIT for >6 months in previous period who restarted ARV\'s during current period','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"afc2a5d5-53e4-427a-9491-b3b1609bbe69\" retired=\"false\">\n  <name> TX_RTT-04 Clients with IIT for &gt;6 months in previous period who restarted ARV&apos;s during current period</name>\n  <description> TX_RTT-04 Clients with IIT for &gt;6 months in previous period who restarted ARV&apos;s during current period</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-08002