n.SqlCohortDefinition\" id=\"10\" uuid=\"129f5049-8d6d-4cd9-8922-7cf72b623ab3\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2022-08-24 07:47:56',4,'2022-08-24 07:48:48',4,0,NULL,NULL,NULL,'714af509-9ade-48b5-b6f0-10d7499a6f15'),(1821,'CI66:TxRTT IIT_6+months','CI66:TxRTT IIT_6+months','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"271261f4-75c6-4c64-a6f0-7be2d40c33c3\" retired=\"false\">\n  <name>CI66:TxRTT IIT_6+months</name>\n  <description>CI66:TxRTT IIT_6+months</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2022-08-24 07:49:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2022-08-24 07:49:56 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1821</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"afc2a5d5-53e4-427a-9491-b3b1609bbe69\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2022-08-24 07:49:18',4,'2022-08-24 07:49:56',4,0,NULL,NULL,NULL,'271261f4-75c6-4c64-a6f0-7be2d40c33c3'),(1822,'Pulmonary Bacteriologically Confirmed New','New Pulmonary Bacteriologically Confirmed clients','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5ab3fc4d-0d1e-4a30-b0c7-d35c68f7f19a\" retired=\"false\">\n  <name>Pulmonary Bacteriologically Confirmed New</name>\n  <description>New Pulmonary Bacteriologically Confirmed clients</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 10:50:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 11:13:34 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1822</id>\n  <query>-- Bacteriologically confirmed Genotypic test results and Phenotypic test results&#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id in (3814, 3815, 4153) &#xd;\n            and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB not Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (3814,3815)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840) &#xd;\n                                        and o.value_coded in (3816,3817,3718, 1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n        and o.person_id in        (&#xd;\n                                    -- New patient&#xd;\n                                    select distinct person_id as pId&#xd;\n                                        from obs ob&#xd;\n                                        where concept_id = 3785 and value_coded = 1034&#xd;\n                                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                )&#xd;\n        and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                    from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                    where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n&#xd;\n        and o.person_id in  (&#xd;\n                                 select distinct ob.person_id as pId&#xd;\n                                    FROM obs ob&#xd;\n                                    -- Pulmonary TB&#xd;\n                                    where ob.concept_id = 3788 and ob.value_coded = 1018&#xd;\n                                    AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                    and ob.voided = 0&#xd;\n                                    group by pId&#xd;\n&#xd;\n        )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-27 16:20:04',4,'2024-07-22 16:43:34',4,0,NULL,NULL,NULL,'5ab3fc4d-0d1e-4a30-b0c7-d35c68f7f19a'),(1823,'NewRelapse_Tb_Treatment_History','Tb Treatment History - New and Relapse Patients','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7f8a23bd-eec0-40a6-8181-cda3d0aab0bd\" retired=\"false\">\n  <name>NewRelapse_Tb_Treatment_History</name>\n  <description>Tb Treatment History - New and Relapse Patients</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 11:51:48 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 13:07:40 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1823</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM&#xd;\n((SELECT distinct Id, patientIdentifier AS &quot;Patient_Identifier&quot;, patientName AS &quot;Patient_Name&quot;, Age , Gender, age_group&#xd;\n        FROM&#xd;\n                        &#xd;\n            (select distinct patient.patient_id AS Id,&#xd;\n                patient_identifier.identifier AS patientIdentifier,&#xd;\n                concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                floor(datediff(CAST(:endDate  AS DATE), person.birthdate)/365) AS Age,&#xd;\n                person.gender AS Gender,&#xd;\n                observed_age_group.name AS age_group,&#xd;\n                observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n            from obs o&#xd;\n            -- New TB Patient&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.person_id in &#xd;\n                        (&#xd;\n                            select distinct ob.person_id &#xd;\n                            from obs ob&#xd;\n                            -- TB Start Date&#xd;\n                            where ob.concept_id = 2237&#xd;\n                            and cast(ob.value_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                            and cast(ob.value_datetime as date) &lt;= CAST(:endDate AS DATE)&#xd;\n                            and ob.voided = 0&#xd;\n                        )&#xd;\n                    AND o.person_id in &#xd;\n                        (&#xd;\n                            select distinct ob.person_id &#xd;\n                            from obs ob&#xd;\n                            where ob.person_id in (&#xd;\n                                        -- New and Relapse Clients&#xd;\n                                            select distinct person_id&#xd;\n                                                from obs&#xd;\n                                                where concept_id = 3785 and value_coded in (1034, 1084) -- New and Relapse clients&#xd;\n                                                and obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                                            )&#xd;\n                        )&#xd;\n&#xd;\n                    &#xd;\n                    AND o.person_id not in (&#xd;\n                        select distinct os.person_id &#xd;\n                            from obs os&#xd;\n                                -- Patient must not be a tranfer in &#xd;\n                            where os.concept_id =   3772 and os.value_coded =2095&#xd;\n                        AND (os.obs_datetime BETWEEN CAST(:startDate AS DATE) AND CAST(:endDate  AS DATE))&#xd;\n                        AND patient.voided = 0 AND os.voided = 0&#xd;\n                        )&#xd;\n                    &#xd;\n                    INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                    INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n                    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                    INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n                    CAST(:endDate  AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n                    AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS NEW_TB_CLIENTS&#xd;\n        ORDER BY NEW_TB_CLIENTS.Age) &#xd;\n&#xd;\n) AS NewRelapsed) </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-27 17:21:48',4,'2024-07-23 18:37:40',4,0,NULL,NULL,NULL,'7f8a23bd-eec0-40a6-8181-cda3d0aab0bd'),(1824,'Pulmonary Bacteriologically Confirmed Relapse','Pulmonary Bacteriologically Confirmed Relapse','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e495a330-c538-4fa2-9279-e0c03ec69b51\" retired=\"false\">\n  <name>Pulmonary Bacteriologically Confirmed Relapse</name>\n  <description>Pulmonary Bacteriologically Confirmed Relapse</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 12:10:01 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 11:11:29 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1824</id>\n  <query>-- Bacteriologically confirmed Genotypic test results and Phenotypic test results&#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id in (3814, 3815, 4153) &#xd;\n            and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB not Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (3814,3815)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840) &#xd;\n                                        and o.value_coded in (3816,3817,3718, 1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n        and o.person_id in        (&#xd;\n                                    -- Relapse patient&#xd;\n                                    select distinct person_id as pId&#xd;\n                                        from obs ob&#xd;\n                                        where concept_id = 3785 and value_coded = 1084&#xd;\n                                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                )&#xd;\n        and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                    from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                    where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n&#xd;\n        and o.person_id in  (&#xd;\n                                 select distinct ob.person_id as pId&#xd;\n                                    FROM obs ob&#xd;\n                                    -- Pulmonary TB&#xd;\n                                    where ob.concept_id = 3788 and ob.value_coded = 1018&#xd;\n                                    AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                    and ob.voided = 0&#xd;\n                                    group by pId&#xd;\n&#xd;\n        )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-27 17:40:01',4,'2024-07-22 16:41:29',4,0,NULL,NULL,NULL,'e495a330-c538-4fa2-9279-e0c03ec69b51'),(1825,'Pulmonary Bacteriologically Confirmed	Excluding Relapse','Pulmonary Bacteriologically Confirmed	Excluding Relapse','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"23ba6606-91b7-4f7c-9142-73d6a43769a3\" retired=\"false\">\n  <name>Pulmonary Bacteriologically Confirmed	Excluding Relapse</name>\n  <description>Pulmonary Bacteriologically Confirmed	Excluding Relapse</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 17:01:52 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 11:15:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1825</id>\n  <query>-- Bacteriologically confirmed Genotypic test results and Phenotypic test results&#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id in (3814, 3815, 4153) &#xd;\n            and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB not Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (3814,3815)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840) &#xd;\n                                        and o.value_coded in (3816,3817,3718, 1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n        and o.person_id in        (&#xd;\n                                    -- Retreatment patient&#xd;\n                                    select distinct person_id as pId&#xd;\n                                        from obs ob&#xd;\n                                        where concept_id = 3785 and value_coded in (3786,1037)&#xd;\n                                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                )&#xd;\n        and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                    from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                    where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n&#xd;\n        and o.person_id in  (&#xd;\n                                 select distinct ob.person_id as pId&#xd;\n                                    FROM obs ob&#xd;\n                                    -- Pulmonary TB&#xd;\n                                    where ob.concept_id = 3788 and ob.value_coded = 1018&#xd;\n                                    AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                    and ob.voided = 0&#xd;\n                                    group by pId&#xd;\n&#xd;\n        )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-27 22:31:52',4,'2024-07-22 16:45:22',4,0,NULL,NULL,NULL,'23ba6606-91b7-4f7c-9142-73d6a43769a3'),(1826,'New and Relapse with document HIV Status','New and Relapse patients with document HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ee4e2170-5dd7-423e-bc84-f0c13c3a9b4f\" retired=\"false\">\n  <name>New and Relapse with document HIV Status</name>\n  <description>New and Relapse patients with document HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 19:38:11 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 11:10:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1826</id>\n  <query>SELECT DISTINCT  o.person_id&#xd;\n                from obs o&#xd;\n                    -- New and Relapse with Documented HIV, Status&#xd;\n                INNER JOIN location l on o.location_id = l.location_id&#xd;\n                INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                AND o.concept_id = 4666&#xd;\n                AND o.voided = 0&#xd;\n                AND o.person_id in &#xd;\n                                (&#xd;\n                                     Select ob.person_id&#xd;\n                                        from obs ob&#xd;\n                                            where ob.concept_id = 3785 and ob.value_coded in (1034, 1084) -- New and Relapse&#xd;\n                                            and ob.voided = 0&#xd;\n                                        )    &#xd;\n				and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                AND o.obs_datetime &lt;= CAST(:endDate AS DATE)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 01:08:11',4,'2024-07-23 16:40:42',4,0,NULL,NULL,NULL,'ee4e2170-5dd7-423e-bc84-f0c13c3a9b4f'),(1827,'Retreatment with documented HIV status','Retreatment Excl. Relapse client with documented HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"17edcc8f-3d38-49dd-a6f4-a5384cdb7245\" retired=\"false\">\n  <name>Retreatment with documented HIV status</name>\n  <description>Retreatment Excl. Relapse client with documented HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 19:50:19 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:58:46 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1827</id>\n  <query>SELECT DISTINCT  o.person_id&#xd;\n                from obs o&#xd;\n                    -- New and Relapse with Documented HIV, Status&#xd;\n                INNER JOIN location l on o.location_id = l.location_id&#xd;\n                INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                AND o.concept_id = 4666&#xd;\n                AND o.voided = 0&#xd;\n                AND o.person_id in &#xd;\n                                (&#xd;\n                                     Select ob.person_id&#xd;\n                                        from obs ob&#xd;\n                                            where ob.concept_id = 3785 and ob.value_coded in (3786, 1037) -- Retreatmentafter LTFU/Failure&#xd;\n                                            and ob.voided = 0&#xd;\n                                        )  &#xd;\n				and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                AND o.obs_datetime &lt;= CAST(:endDate AS DATE)   </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 01:20:19',4,'2024-07-23 16:28:46',4,0,NULL,NULL,NULL,'17edcc8f-3d38-49dd-a6f4-a5384cdb7245'),(1828,'Children < 15 with Documented HIV Status','Children (0 - 14) with documented HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ca5b1d37-8229-474d-8125-2486520685fd\" retired=\"false\">\n  <name>Children &lt; 15 with Documented HIV Status</name>\n  <description>Children (0 - 14) with documented HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 20:10:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:51:25 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>endDate</name>\n      <label>endDate</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>startDate</name>\n      <label>startDate</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1828</id>\n  <query>select distinct patient.patient_id AS Id,&#xd;\n                patient_identifier.identifier AS patientIdentifier,&#xd;\n                concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n                    -- Documented HIV, Status&#xd;\n                    inner join location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666&#xd;\n                    AND o.voided = 0    &#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)   &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )            &#xd;\n                    INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                    INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n                    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                having Age &lt; 15</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 01:40:47',4,'2024-07-23 16:21:25',4,0,NULL,NULL,NULL,'ca5b1d37-8229-474d-8125-2486520685fd'),(1829,'Pulmonary Clinically Diagnosed New','Pulmonary Clinically Diagnosed New','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"34bcf70d-0178-4dcc-ab38-9046e4bcedd1\" retired=\"false\">\n  <name>Pulmonary Clinically Diagnosed New</name>\n  <description>Pulmonary Clinically Diagnosed New</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 20:39:34 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 10:24:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1829</id>\n  <query>  select distinct Id&#xd;\n    FROM &#xd;\n     -- Clinical Diagnosis X-Ray&#xd;\n    (&#xd;\n&#xd;\n        Select distinct person_id as Id, max_observation, examination_timing,o.voided&#xd;\n            from obs o&#xd;\n            inner join&#xd;\n                        (&#xd;\n                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.obs_id)), 20) as examination_timing&#xd;\n                                from obs oss&#xd;\n                                    where oss.concept_id = 2237 -- TB Start Date&#xd;\n                                    and cast(oss.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                    and cast(oss.value_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                    and oss.voided = 0&#xd;\n                                    group by oss.person_id&#xd;\n                                &#xd;\n                                )latest&#xd;\n                            on latest.Id = o.person_id&#xd;\n                            where o.concept_id = 4673 and o.value_coded = 4171 -- XRay suggestive of TB&#xd;\n                            and o.voided=0&#xd;\n                            and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                            and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                    from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                    where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n                            group by person_id&#xd;\n    )as XRay_Clients&#xd;\n     &#xd;\n     -- Site (Pulmonary)&#xd;\n    inner join (&#xd;\n                    select distinct ob.person_id as pId&#xd;\n                        FROM obs ob&#xd;\n                        -- Pulmonary TB&#xd;\n                        where ob.concept_id = 3788 and ob.value_coded = 1018&#xd;\n                        AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                        and ob.voided = 0&#xd;\n                        group by pId&#xd;\n        ) As Pulmonary&#xd;\n    on XRay_Clients.Id = Pulmonary.pId&#xd;\n&#xd;\n    inner join (&#xd;\n                    -- New&#xd;\n                    select distinct person_id as pId&#xd;\n                        from obs ob&#xd;\n                        where concept_id = 3785 and value_coded = 1034&#xd;\n                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n&#xd;\n    ) As New_Client&#xd;\n     on XRay_Clients.Id = New_Client.pId&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 02:09:34',4,'2024-07-22 15:54:09',4,0,NULL,NULL,NULL,'34bcf70d-0178-4dcc-ab38-9046e4bcedd1'),(1830,'Miners with Documented HIV Status','High risk population of miners with documented HIV','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"001d7c51-fa6b-45d5-9690-cc6dce14a608\" retired=\"false\">\n  <name>Miners with Documented HIV Status</name>\n  <description>High risk population of miners with documented HIV</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-27 20:45:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:57:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1830</id>\n  <query>select distinct o.person_id&#xd;\n                from obs o&#xd;\n                    -- Documented HIV, Status&#xd;\n                    INNER JOIN location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666&#xd;\n                    AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded = 3667 -- Population (Miner)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )    &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)  </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 02:15:17',4,'2024-07-23 16:27:53',4,0,NULL,NULL,NULL,'001d7c51-fa6b-45d5-9690-cc6dce14a608'),(1831,'Ex-Miners with Documented HIV Status','High risk population of Ex Miners with Documented HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinitio