       <parameterMappings id=\"26\">\n          <entry>\n            <string>maxAge</string>\n            <int>64</int>\n          </entry>\n          <entry>\n            <string>minAge</string>\n            <int>50</int>\n          </entry>\n          <entry>\n            <string>effectiveDate</string>\n            <string>${endDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n    <entry>\n      <string>65Plus</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"27\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.AgeCohortDefinition\" reference=\"9\"/>\n        <parameterMappings id=\"28\">\n          <entry>\n            <string>maxAge</string>\n            <int>120</int>\n          </entry>\n          <entry>\n            <string>minAge</string>\n            <int>65</int>\n          </entry>\n          <entry>\n            <string>effectiveDate</string>\n            <string>${endDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n    <entry>\n      <string>Under1yr</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"29\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.AgeCohortDefinition\" reference=\"9\"/>\n        <parameterMappings id=\"30\">\n          <entry>\n            <string>maxAge</string>\n            <int>0</int>\n          </entry>\n          <entry>\n            <string>minAge</string>\n            <int>0</int>\n          </entry>\n          <entry>\n            <string>effectiveDate</string>\n            <string>${endDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </cohortDefinitions>\n</org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension>','2023-03-28 14:04:09',4,'2024-02-29 19:34:18',4,0,NULL,NULL,NULL,'68d03856-4b9b-4d8d-ba8f-bc698222c9f2'),(1847,'Children < 15 with Positive HIV Status','High risk population for Children < 15 with Positive HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"63b6abab-6261-4d20-9601-74454ea10cd6\" retired=\"false\">\n  <name>Children &lt; 15 with Positive HIV Status</name>\n  <description>High risk population for Children &lt; 15 with Positive HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 08:43:51 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:42:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1847</id>\n  <query>select distinct patient.patient_id AS Id,&#xd;\n                patient_identifier.identifier AS patientIdentifier,&#xd;\n                concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n                    -- HIV PositiveStatus&#xd;\n                    inner join location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666 and o.value_coded in (4323, 4664)&#xd;\n                    AND o.voided = 0    &#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)    &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )           &#xd;\n                    INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                    INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n                    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                having Age &lt; 15</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 14:13:51',4,'2024-07-23 16:12:45',4,0,NULL,NULL,NULL,'63b6abab-6261-4d20-9601-74454ea10cd6'),(1848,'Miners with Positive HIV Status','High risk population of miners with Positive HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d4d85343-09fc-473b-a650-50f444deee3e\" retired=\"false\">\n  <name>Miners with Positive HIV Status</name>\n  <description>High risk population of miners with Positive HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 08:58:19 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:47:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1848</id>\n  <query>select distinct o.person_id&#xd;\n                from obs o&#xd;\n                    -- Documented HIV, Status&#xd;\n                    INNER JOIN location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666 and o.value_coded in (4323, 4664)&#xd;\n                    AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded = 3667 -- Population (Miner)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )    &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)  </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 14:28:19',4,'2024-07-23 16:17:24',4,0,NULL,NULL,NULL,'d4d85343-09fc-473b-a650-50f444deee3e'),(1849,'Ex-Miners with Positive HIV Status',' High risk population of Ex Miners with Positive HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"33fa2a02-6cb8-4850-8d80-18d86f0516a8\" retired=\"false\">\n  <name>Ex-Miners with Positive HIV Status</name>\n  <description> High risk population of Ex Miners with Positive HIV Status</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 09:10:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:48:15 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1849</id>\n  <query>select distinct o.person_id&#xd;\n                from obs o&#xd;\n                    -- Documented HIV, Status&#xd;\n                    INNER JOIN location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666 and o.value_coded in (4323, 4664)&#xd;\n                    AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded = 3668 -- Population (Ex-Miner)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )   &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    &#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE) </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 14:40:47',4,'2024-07-23 16:18:15',4,0,NULL,NULL,NULL,'33fa2a02-6cb8-4850-8d80-18d86f0516a8'),(1850,'Pulmonary Clinically Diagnosed Excluding Relapse','Pulmonary Clinically Diagnosed Excluding Relapse','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8a1f3d92-c5ec-4892-920b-5bae45020424\" retired=\"false\">\n  <name>Pulmonary Clinically Diagnosed Excluding Relapse</name>\n  <description>Pulmonary Clinically Diagnosed Excluding Relapse</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 09:16:40 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 10:27:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1850</id>\n  <query>  select distinct Id&#xd;\n    FROM &#xd;\n     -- Clinical Diagnosis X-Ray&#xd;\n    (&#xd;\n&#xd;\n        Select distinct person_id as Id, max_observation, examination_timing,o.voided&#xd;\n            from obs o&#xd;\n            inner join&#xd;\n                        (&#xd;\n                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.obs_id)), 20) as examination_timing&#xd;\n                                from obs oss&#xd;\n                                    where oss.concept_id = 2237 -- TB Start Date&#xd;\n                                    and cast(oss.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                    and cast(oss.value_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                    and oss.voided = 0&#xd;\n                                    group by oss.person_id&#xd;\n                                &#xd;\n                                )latest&#xd;\n                            on latest.Id = o.person_id&#xd;\n                            where o.concept_id = 4673 and o.value_coded = 4171 -- XRay suggestive of TB&#xd;\n                            and o.voided=0&#xd;\n                            and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                            and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                    from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                    where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n                            group by person_id&#xd;\n    )as XRay_Clients&#xd;\n     &#xd;\n     -- Site (Pulmonary)&#xd;\n    inner join (&#xd;\n                    select distinct ob.person_id as pId&#xd;\n                        FROM obs ob&#xd;\n                        -- Pulmonary TB&#xd;\n                        where ob.concept_id = 3788 and ob.value_coded = 1018&#xd;\n                        AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                        and ob.voided = 0&#xd;\n                        group by pId&#xd;\n        ) As Pulmonary&#xd;\n    on XRay_Clients.Id = Pulmonary.pId&#xd;\n&#xd;\n    inner join (&#xd;\n                    -- Retreatment&#xd;\n                    select distinct person_id as pId&#xd;\n                        from obs ob&#xd;\n                        where concept_id = 3785 and value_coded in (3786,1037)&#xd;\n                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n&#xd;\n    ) As New_Client&#xd;\n     on XRay_Clients.Id = New_Client.pId&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 14:46:40',4,'2024-07-22 15:57:42',4,0,NULL,NULL,NULL,'8a1f3d92-c5ec-4892-920b-5bae45020424'),(1851,'Factory Workers with Positive HIV Status','High risk populatio