 in (4323, 4664)&#xd;\n                    AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded = 3669 -- Population (Factory Workers)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )   &#xd;\n					 and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)  </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 14:52:07',4,'2024-07-23 16:14:21',4,0,NULL,NULL,NULL,'e7f0599c-bb8c-4d2d-94a7-4b99e0f1f7af'),(1852,'Public transport with Positive HIV Status','High risk population of Public transport operators with Positive HIV Status','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"17f9486c-aefe-4a21-b3ad-d5c685280640\" retired=\"false\">\n  <name>Public transport with Pos