cation l on ob.location_id = l.location_id&#xd;\n     &#xd;\n    where  ob.concept_id = 3788 and ob.value_coded = 2233 -- Extra Pulmonary TB&#xd;\n	and cast(ob.obs_datetime as date) &gt;= cast(:startDate as date) &#xd;\n	and cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n	and ob.person_id in 			 &#xd;\n		(&#xd;\n							select distinct ob.person_id &#xd;\n							from obs ob&#xd;\n							-- TB Start Date&#xd;\n							where ob.concept_id = 2237&#xd;\n							and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n							and cast(ob.value_datetime as date) &lt;= cast(:endDate as date)&#xd;\n							and ob.voided = 0&#xd;\n		)&#xd;\n	AND ob.person_id in &#xd;\n		(&#xd;\n		-- Retreatment Clients&#xd;\n			select distinct person_id&#xd;\n			from obs&#xd;\n			where concept_id = 3785 and value_coded in (3786,1037)&#xd;\n			and cast(obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n			and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n		)&#xd;\n	&#xd;\n	AND ob.person_id not in (&#xd;\n		select distinct os.person_id &#xd;\n			from obs os&#xd;\n				-- Patient must not be a tranfer in	&#xd;\n			where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n		AND (cast(os.obs_datetime as date) BETWEEN cast(:startDate as date) AND cast(:endDate as date))&#xd;\n	)&#xd;\n	and ob.voided = 0&#xd;\n	or ob.person_id in (&#xd;\n	select ob.person_id &#xd;\n	FROM obs ob&#xd;\n	-- Extra Pulmonary TB in ART Intake&#xd;\n	where ob.concept_id = 2236 and ob.value_coded = 2233&#xd;\n	and cast(ob.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n	and cast(ob.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n	and ob.voided = 0&#xd;\n		)&#xd;\n		&#xd;\n    </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 19:59:38',4,'2024-07-22 19:04:00',4,0,NULL,NULL,NULL,'5023a0c3-15b8-4d16-ac54-09a77d01648d'),(1863,'HHCM with HIV Positive on CPT/Dapzone','High risk population of HHCM with HIV Positive 