  AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded =3777 -- Population (Household member of miner)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 5415 and ob.value_coded in (2330,4619) -- On Dapsone/CPT                                         AND ob.voided = 0&#xd;\n&#xd;\n                                        )    &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE) </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 20:35:16',4,'2024-07-23 15:54:43',4,0,NULL,NULL,NULL,'6365d73a-6fde-4e27-a75b-b5010023ddea'),(1864,'New and Relapse with HIV Positive on CPT/Dapzone','High risk population of New and Relapse with HIV Positive on CPT/Dapzone','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"14343630-0c58-4f34-8bb5-1744e1618c31\" retired=\"false\">\n  <name>New and Relapse with HIV Positive on CPT/Dapzone</name>\n  <description>High risk population of New and Relapse with HIV Positive on CPT/Dapzone</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 15:14:37 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:28:28 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1864</id>\n  <query>select distinct o.person_id&#xd;\n                from obs o&#xd;\n                    -- Positive, Status&#xd;\n                    INNER JOIN location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4666 and o.value_coded in (4323, 4664)&#xd;\n                    AND o.voided = 0&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 3776 and ob.value_coded in (1034, 1084) -- Population (New and Relapse)&#xd;\n                                                AND ob.voided = 0&#xd;\n&#xd;\n                                        )&#xd;\n                    AND o.person_id in &#xd;\n                                        (&#xd;\n                                            Select ob.person_id&#xd;\n                                                from obs ob&#xd;\n                                                where ob.concept_id = 5415 and ob.value_coded in (2330,4619) -- On Dapsone/CPT                                         AND ob.voided = 0&#xd;\n&#xd;\n                                        ) &#xd;\n					and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE) </query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 20:44:37',4,'2024-07-23 15:58:28',4,0,NULL,NULL,NULL,'14343630-0c58-4f34-8bb5-1744e1618c31'),(1865,'Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : New','Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : New','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"273f38fa-7a41-4323-ac9d-24fd27c0c4cf\" retired=\"false\">\n  <name>Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : New</name>\n  <description>Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : New</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 15:16:26 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 09:11:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1865</id>\n  <query>-- Bacteriologically confirmed Genotypic test results and Phenotypic test results&#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id in (3814, 3815, 4153) &#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (3814,3815) -- Bacteriologically Confirmed&#xd;\n											and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840) &#xd;\n                                        and o.value_coded in (3816,3817,1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n        and o.person_id in        (&#xd;\n                                    -- New patient&#xd;\n                                    select distinct person_id as pId&#xd;\n                                        from obs ob&#xd;\n                                        where concept_id = 3785 and value_coded = 1034&#xd;\n                                        and cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n                                )&#xd;\n        and o.person_id not in (&#xd;\n                                select distinct os.person_id &#xd;\n                                from obs os&#xd;\n                                        -- Patient must not be a tranfer in	&#xd;\n                                where os.concept_id = 	3772 and os.value_coded =2095&#xd;\n                                AND (os.obs_datetime BETWEEN :startDate AND :endDate)&#xd;\n                                and os.voided = 0&#xd;\n                            )&#xd;\n&#xd;\n        and o.person_id in  (&#xd;\n                                select distinct ob.person_id as pId&#xd;\n								FROM obs ob&#xd;\n								-- Died before treatment or lost to followup&#xd;\n								where ob.concept_id = 3789 and ob.value_coded in (3791,2302)&#xd;\n								AND cast(ob.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n								and ob.voided = 0&#xd;\n								group by pId&#xd;\n&#xd;\n       						 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-28 20:46:26',4,'2024-07-23 14:41:09',4,0,NULL,NULL,NULL,'273f38fa-7a41-4323-ac9d-24fd27c0c4cf'),(1866,'Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : Relapse','Bacteriologically confirmed not started on treatment (m) ticked Died before treatment or Lost to follow up : Relapse','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializ