     <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1886</id>\n  <query>select distinct patient.patient_id AS Id,&#xd;\n                patient_identifier.identifier AS patientIdentifier,&#xd;\n                concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n                    -- HIV Positive on ART&#xd;\n                    inner join location l on o.location_id = l.location_id&#xd;\n                    INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                    AND o.concept_id = 4667 and o.value_coded in (4670, 4669)&#xd;\n                    AND o.voided = 0    &#xd;\n                    AND o.obs_datetime &gt;= CAST(:startDate AS DATE)&#xd;\n                    AND o.obs_datetime &lt;= CAST(:endDate AS DATE)&#xd;\n					AND o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct ob.person_id &#xd;\n                                        from obs ob&#xd;\n                                        -- TB Start Date&#xd;\n                                        where ob.concept_id = 2237&#xd;\n                                        and cast(ob.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n                                        and cast(ob.value_datetime as date) &lt;= cast(:endDate as date) &#xd;\n                                )&#xd;\n                    INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                    INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n                    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                having Age &lt; 15</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-29 01:17:46',4,'2024-07-23 15:36:30',4,0,NULL,NULL,NULL,'e724e30e-b9e1-4a19-afa9-d19aa8dc42f4'),(1887,'TB among Public Transport Operators	','TB among Key Population Group Public Transport Operators','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"4aac5017-e28a-4f36-8805-0812476a9d7b\" retired=\"false\">\n  <name>TB among Public Transport Operators	</name>\n  <description>TB among Key Population Group Public Transport Operators</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 19:51:36 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-22 14:09:35 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1887</id>\n  <query>select oss.person_id &#xd;\nfrom obs oss &#xd;\n	where oss.concept_id = 2237&#xd;\n    and cast(oss.value_datetime as date) &gt;= cast(:startDate as date)&#xd;\n    and cast(oss.value_datetime as date) &lt;= cast(:endDate as date)&#xd;\n    and oss.voided = 0&#xd;\nand oss.person_id in&#xd;\n			(select diagnosis.Id &#xd;\n				from&#xd;\n				(select distinct o.person_id as Id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS TB_diagnosis&#xd;\n									from obs o &#xd;\n									INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n									where o.concept_id = 3776 and o.value_coded = 4654 -- Public Transport&#xd;\n									AND o.voided = 0&#xd;\n									AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n									group by person_id)diagnosis&#xd;\n			)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-29 01:21:36',4,'2024-07-22 19:39:35',4,0,NULL,NULL,NULL,'4aac5017-e28a-4f36-8805-0812476a9d7b'),(1888,'Miners with HIV Positive on ART','High risk population of Miners with HIV Positive on ART','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a37a95b7-1365-4d73-8d21-28dd2e77196e\" retired=\"false\">\n  <name>Miners with HIV Positive on ART</name>\n  <description>High risk population of Miners with HIV Positive on ART</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-28 19:55:27 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-07-23 10:14:47 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>