eporting.evaluation.parameter.Mapped id=\"10\">\n        <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"11\" uuid=\"9016d0ef-4556-49e7-99bd-2bf2e7f5188f\"/>\n        <parameterMappings id=\"12\">\n          <entry>\n            <string>endDate</string>\n            <string>${endDate}</string>\n          </entry>\n          <entry>\n            <string>location</string>\n            <string>${location}</string>\n          </entry>\n          <entry>\n            <string>startDate</string>\n            <string>${startDate}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </cohortDefinitions>\n</org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension>','2023-03-30 15:48:45',4,'2023-03-30 16:06:44',4,0,NULL,NULL,NULL,'2244b6f7-5dd0-4c8a-8a9e-67bac3fe7d9b'),(1970,'test','test','org.openmrs.module.reporting.indicator.dimension.Dimension','org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension id=\"1\" uuid=\"a572d104-f644-42bb-ae58-7c83ac0747ad\" retired=\"false\">\n  <name>test</name>\n  <description>test</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 14:06:01 UTC</dateCreated>\n  <parameters id=\"4\"/>\n  <cohortDefinitions class=\"tree-map\" id=\"5\"/>\n</org.openmrs.module.reporting.indicator.dimension.CohortDefinitionDimension>','2023-03-30 16:06:01',4,NULL,NULL,0,NULL,NULL,NULL,'a572d104-f644-42bb-ae58-7c83ac0747ad'),(1971,'TB New and Relapse Completed','TB New and Relapse Completed','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"1540870d-551a-4e11-baad-70ed9b13289a\" retired=\"false\">\n  <name>TB New and Relapse Completed</name>\n  <description>TB New and Relapse Completed</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 14:58:43 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-03-30 14:59:47 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1971</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(Select distinct Id&#xd;\n    From(&#xd;\n        select distinct patient.patient_id AS Id,&#xd;\n            patient_identifier.identifier AS patientIdentifier,&#xd;\n            pi2.identifier AS TB_Number,&#xd;\n            concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n            floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n            observed_age_group.name AS age_group,&#xd;\n            person.gender AS Gender,&#xd;\n            observed_age_group.sort_order AS sort_order &#xd;\n          from obs o&#xd;\n          --  TB Clients &#xd;\n            INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n            INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n            INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n            INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n            LEFT JOIN patient_identifier pi2 ON pi2.patient_id = o.person_id AND pi2.identifier_type in (7)&#xd;\n            AND o.voided=0&#xd;\n            INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            AND o.concept_id in (4153, 1158)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n            AND patient.voided = 0 AND o.voided = 0&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 2237 and o.voided = 0&#xd;\n              and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n              and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n              group by o.person_id&#xd;\n                )&#xd;\n            -- TB History of previous treatment&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 3785 and o.value_coded in (1034,1084) &#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n            -- TB Treatment Outcome&#xd;\n             and o.person_id in (&#xd;\n               select o.person_id&#xd;\n               from obs o&#xd;\n               where o.concept_id = 3792 and o.value_coded = 2242 and o.voided = 0&#xd;\n              )&#xd;\n&#xd;\n            Group by o.person_id) AS TB_TESTING&#xd;\n)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 16:58:43',4,'2023-03-30 16:59:47',4,0,NULL,NULL,NULL,'1540870d-551a-4e11-baad-70ed9b13289a'),(1972,'TB New and Relapse Cured','TB New and Relapse Cured','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"22e1906b-16cd-4109-b529-a043e43ff3d4\" retired=\"false\">\n  <name>TB New and Relapse Cured</name>\n  <description>TB New and Relapse Cured</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 15:04:42 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-03-30 15:06:17 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>1972</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(Select distinct Id&#xd;\n    From(&#xd;\n        select distinct patient.patient_id AS Id,&#xd;\n            patient_identifier.identifier AS patientIdentifier,&#xd;\n            pi2.identifier AS TB_Number,&#xd;\n            concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n            floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n            observed_age_group.name AS age_group,&#xd;\n            person.gender AS Gender,&#xd;\n            observed_age_group.sort_order AS sort_order &#xd;\n          from obs o&#xd;\n          --  TB Clients &#xd;\n            INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n            INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n            INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n            INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n            LEFT JOIN patient_identifier pi2 ON pi2.patient_id = o.person_id AND pi2.identifier_type in (7)&#xd;\n            AND o.voided=0&#xd;\n            INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            AND o.concept_id in (4153, 1158)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n            AND patient.voided = 0 AND o.voided = 0&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 2237 and o.voided = 0&#xd;\n              and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n              and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n              group by o.person_id&#xd;\n                )&#xd;\n            -- TB History of previous treatment(New AND Relapse)&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 3785 and o.value_coded in (1034,1084) &#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n            -- TB Treatment Outcome&#xd;\n             and o.person_id in (&#xd;\n               select o.person_id&#xd;\n               from obs o&#xd;\n               where o.concept_id = 3792 and o.value_coded = 1068&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n&#xd;\n            Group by o.person_id) AS TB_TESTING&#xd;\n)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 17:04:42',4,'2023-03-30 17:06:17',4,0,NULL,NULL,NULL,'22e1906b-16cd-4109-b529-a043e43ff3d4'),(1973,'TB New and Relapse Died','TB New and Relapse Died','org.openmrs.mo