nd o.person_id in (&#xd;\n							select o.person_id&#xd;\n								from obs o&#xd;\n							where o.concept_id = 2237 &#xd;\n							and o.voided = 0&#xd;\n							and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n							and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n							group by o.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n							select ob.person_id &#xd;\n								from obs ob&#xd;\n								where ob.concept_id = 3776&#xd;\n								and ob.value_coded = 3776 &#xd;\n								and ob.voided = 0						&#xd;\n						)&#xd;\n						and o.person_id not in (&#xd;\n										select b.person_id &#xd;\n								from obs b&#xd;\n								where b.concept_id = 3792&#xd;\n								and b.value_coded in (2242)&#xd;\n								and b.voided = 0						&#xd;\n						)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 18:38:29',4,'2023-03-30 18:38:53',4,0,NULL,NULL,NULL,'9e174142-2794-43fc-95dd-9f3f92e4b379'),(2015,'prison_worker_curred','Prion worker curred','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"91f85b53-7dca-4730-a391-5198293d1cf9\" retired=\"false\">\n  <name>prison_worker_curred</name>\n  <description>Prion worker curred</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 16:40:22 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-03-30 16:43:23 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2015</id>\n  <query>select distinct  o.person_id&#xd;\n					from obs o&#xd;\n					inner join location l on o.location_id = l.location_id&#xd;\n					WHERE (o.location_id =:location or parent_location =:location)&#xd;\n						and o.concept_id in (4153, 1158)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n						AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n					    and o.person_id in (&#xd;\n							select o.person_id&#xd;\n								from obs o&#xd;\n							where o.concept_id = 2237 &#xd;\n							and o.voided = 0&#xd;\n							and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n							and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n							group by o.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n							select ob.person_id &#xd;\n								from obs ob&#xd;\n								where ob.concept_id = 3776&#xd;\n								and ob.value_coded = 3776&#xd;\n								and ob.voided = 0						&#xd;\n						)&#xd;\n						and o.person_id not in (&#xd;\n										select b.person_id &#xd;\n								from obs b&#xd;\n								where b.concept_id = 3792&#xd;\n								and b.value_coded in (1068)&#xd;\n								and b.voided = 0						&#xd;\n						)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 18:40:22',4,'2023-03-30 18:43:23',4,0,NULL,NULL,NULL,'91f85b53-7dca-4730-a391-5198293d1cf9'),(2016,'All Childred and Completed','All Childred and Completed','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f300ef4e-70b5-4c81-b993-7d45d23f299e\" retired=\"false\">\n  <name>All Childred and Completed</name>\n  <description>All Childred and Completed</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 16:43:19 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-03-30 16:46:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2016</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(Select distinct Id&#xd;\n    From(&#xd;\n        select distinct patient.patient_id AS Id,&#xd;\n            patient_identifier.identifier AS patientIdentifier,&#xd;\n            pi2.identifier AS TB_Number,&#xd;\n            concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n            floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n            observed_age_group.name AS age_group,&#xd;\n            person.gender AS Gender,&#xd;\n            observed_age_group.sort_order AS sort_order &#xd;\n          from obs o&#xd;\n          --  TB Clients &#xd;\n            INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n            INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n            INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n            INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n            LEFT JOIN patient_identifier pi2 ON pi2.patient_id = o.person_id AND pi2.identifier_type in (7)&#xd;\n            AND o.voided=0&#xd;\n            INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            AND o.concept_id in (4153, 1158)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n            AND patient.voided = 0 AND o.voided = 0&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 2237 and o.voided = 0&#xd;\n              and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n              and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n              group by o.person_id&#xd;\n                )&#xd;\n            -- All Children&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n              INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n              where floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) &lt; 15&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n            -- TB Treatment Outcome&#xd;\n             and o.person_id in (&#xd;\n               select o.person_id&#xd;\n               from obs o&#xd;\n               where o.concept_id = 3792 and o.value_coded = 2242&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n&#xd;\n            Group by o.person_id) AS TB_TESTING&#xd;\n)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 18:43:19',4,'2023-03-30 18:46:26',4,0,NULL,NULL,NULL,'f300ef4e-70b5-4c81-b993-7d45d23f299e'),(2017,'prison_worker_notEvaluated','Prison worker not evaluated','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"1c0c7eab-e438-4787-982a-bfb448fe7455\" retired=\"false\">\n  <name>prison_worker_notEvaluated</name>\n  <description>Prison worker not evaluated</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-03-30 16:46:21 UTC</dateCreated>\n  <changedBy reference=\