    AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n            AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n            AND patient.voided = 0 AND o.voided = 0&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 2237 and o.voided = 0&#xd;\n              and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n              and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n              group by o.person_id&#xd;\n                )&#xd;\n            -- All Children&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n              INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n              where floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) &lt; 15&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n            -- TB Treatment Outcome&#xd;\n             and o.person_id in (&#xd;\n               select o.person_id&#xd;\n               from obs o&#xd;\n               where o.concept_id = 3792 and o.value_coded = 3793&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n&#xd;\n            Group by o.person_id) AS TB_TESTING&#xd;\n)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-03-30 18:49:34',4,'2023-03-30 18:50:01',4,0,NULL,NULL,NULL,'1b710ad4-75b5-4b64-b916-1806dca0013d'),(2024,'health_worker_completed','Health worker completed','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" 