 * Description: HIV patients who have not been seen for at least 18 months&#xd;\n   * Assumption: Database has only HIV patients&#xd;\n   * HIV Case Reporting Module has already excluded patients previously added to the list.&#xd;\n   */&#xd;\n&#xd;\n  SELECT e2.patient_id&#xd;\n  FROM (&#xd;\n    SELECT e1.patient_id, max(e1.encounter_datetime) as latest_encounter_date&#xd;\n    FROM encounter e1&#xd;\n    WHERE not e1.voided&#xd;\n    GROUP BY e1.patient_id&#xd;\n  ) as e2&#xd;\n  WHERE&#xd;\n    date(e2.latest_encounter_date) &lt;= DATE_SUB(now(), INTERVAL 18 MONTH)&#xd;\n  AND&#xd;\n    date(e2.latest_encounter_date) &gt; DATE_SUB(:lastExecutionTime, INTERVAL 18 MONTH);&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-16 11:25:57',2,NULL,NULL,0,NULL,NULL,NULL,'8916dca2-85b6-4eea-b921-d5cffe1056d4'),(2331,'HIV Patient Died','HIV patients who have died','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d8cb3c40-0d86-4448-8f1f-cf4cd91ece26\" retired=\"false\">\n  <name>HIV Patient Died</name>\n  <description>HIV patients who have died</description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2023-08-16 09:25:57 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>lastExecutionTime</name>\n      <label>casereport.lastExecutionTime</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <query>&#xd;\n&#xd;\n  /*&#xd;\n   * Name:HIV Patient Died&#xd;\n   * Query Type: SQL Cohort Query&#xd;\n   * Description: HIV patients who have died&#xd;\n   * Assumption: Database has only HIV patients&#xd;\n   * HIV Case Reporting Module has already excluded patients previously added to the list.&#xd;\n   */&#xd;\n&#xd;\n  SELECT person_id&#xd;\n  FROM person&#xd;\n  WHERE dead = 1&#xd;\n  AND(&#xd;\n    date_created &gt;= date(:lastExecutionTime)&#xd;\n    OR date_changed &gt;= date(:lastExecutionTime)&#xd;\n  )&#xd;\n  AND not voided;&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-16 11:25:57',2,NULL,NULL,0,NULL,NULL,NULL,'d8cb3c40-0d86-4448-8f1f-cf4cd91ece26'),(2333,'Children ARV Regimen_2ndLine_5C','Children ARV Regimen_2ndLine_5C disaggregated by weight, sex, age','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.PeriodIndicatorReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.PeriodIndicatorReportDefinition id=\"1\" uuid=\"38a458f9-cb42-4eb7-9b3a-22be06efe0e5\" retired=\"false\">\n  <name>Children ARV Regimen_2ndLine_5C</name>\n  <description>Children ARV Regimen_2ndLine_5C disaggregated by weight, sex, age</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-16 10:14:20 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-16 10:14:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.eval