    <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"97\">\n      <name>M&lt;1yr0-3</name>\n      <label>Clients given 6F weighing 0-3.9kg-Males-Under 1yr</label>\n      <indicator reference=\"18\"/>\n      <dimensionOptions id=\"98\">\n        <entry>\n          <string>DM_Sex</string>\n          <string>Males</string>\n        </entry>\n        <entry>\n          <string>DM_Age</string>\n          <string>Under 1yr</string>\n        </entry>\n      </dimensionOptions>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"99\">\n      <name>M&lt;1yr10-13</name>\n      <label>Clients given 6F weighing 10-13.9kg-Males-Under 1yr</label>\n      <indicator reference=\"23\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"100\">\n      <name>M&lt;1yr14-19</name>\n      <label>Clients given 6F weighing 14-19.9kg-Males-Under 1yr</label>\n      <indicator reference=\"26\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"101\">\n      <name>M&lt;1yr20-24</name>\n      <label>Clients given 6F weighing 20-24.9kg-Males-Under 1yr</label>\n      <indicator reference=\"29\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"102\">\n      <name>M&lt;1yr25-34</name>\n      <label>Clients given 6F weighing 25-34.9kg-Males-Under 1yr</label>\n      <indicator reference=\"32\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"103\">\n      <name>M&lt;1yr4-5</name>\n      <label>Clients given 6F weighing 4-5.9kg-Males-Under 1yr</label>\n      <indicator reference=\"35\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"104\">\n      <name>M&lt;1yr6-9</name>\n      <label>Clients given 6F weighing 6-9.9kg-Males-Under 1yr</label>\n      <indicator reference=\"38\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"105\">\n      <name>M&lt;1yr&gt;=35</name>\n      <label>Clients given 6F weighing &gt;= 35kg-Males-Under 1yr</label>\n      <indicator reference=\"41\"/>\n      <dimensionOptions reference=\"98\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n  </columns>\n</org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition>','2023-08-16 19:30:39',4,'2023-08-16 20:09:14',4,0,NULL,NULL,NULL,'739d18c0-8b69-47f2-b49c-f203e776d528'),(2358,'Clients given 5A with >=20Copies_Viral_Load','Clients given 5A with >=20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f9c21dfa-e2bc-4174-858c-5290ee412c83\" retired=\"false\">\n  <name>Clients given 5A with &gt;=20Copies_Viral_Load</name>\n  <description>Clients given 5A with &gt;=20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 08:33:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 08:34:00 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2358</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n							CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\n&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 10:33:38',4,'2023-08-17 10:34:00',4,0,NULL,NULL,NULL,'f9c21dfa-e2bc-4174-858c-5290ee412c83'),(2359,'Clients given 5A with <20Copies_Viral_Load','Clients given 5A with <20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f803bb84-0a18-4319-91e7-4ea289d8a295\" retired=\"false\">\n  <name>Clients given 5A with &lt;20Copies_Viral_Load</name>\n  <description>Clients given 5A with &lt;20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 08:35:33 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 08:36:23 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2359</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n							CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 10:35:33',4,'2023-08-17 10:36:23',4,0,NULL,NULL,NULL,'f803bb84-0a18-4319-91e7-4ea289d8a295'),(2360,'Clients given 5A with Undetectable_Viral_Load','Clients given 5A with Undetectable_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2386a884-ae79-46a7-8adf-d5044b06e9c4\" retired=\"false\">\n  <name>Clients given 5A with Undetectable_Viral_Load</name>\n  <description>Clients given 5A with Undetectable_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 08:37:56 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 08:39:04 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2360</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n							CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 10:37:56',4,'2023-08-17 10:39:04',4,0,NULL,NULL,NULL,'2386a884-ae79-46a7-8adf-d5044b06e9c4'),(2361,'Clients given 5B with >=20Copies_Viral_Load','Clients given 5B with >=20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5939e332-e3fc-4a42-a736-b647f31a87a3\" retired=\"false\">\n  <name>Clients given 5B with &gt;=20Copies_Viral_Load</name>\n  <description>Clients given 5B with &gt;=20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 08:44:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:02:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2361</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\n&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 10:44:15',4,'2023-08-17 11:02:37',4,0,NULL,NULL,NULL,'5939e332-e3fc-4a42-a736-b647f31a87a3'),(2362,'Clients given 5B with <20Copies_Viral_Load','Clients given 5B with <20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8b4f6f3d-4444-4429-ac84-94ecc1e14ba2\" retired=\"false\">\n  <name>Clients given 5B with &lt;20Copies_Viral_Load</name>\n  <description>Clients given 5B with &lt;20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 08:59:37 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:05:50 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2362</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 10:59:37',4,'2023-08-17 11:05:50',4,0,NULL,NULL,NULL,'8b4f6f3d-4444-4429-ac84-94ecc1e14ba2'),(2363,'Clients given 5B with Undetectable_Viral_Load','Clients given 5B with Undetectable_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d7418afd-aca2-46e9-9c72-e920d447db27\" retired=\"false\">\n  <name>Clients given 5B with Undetectable_Viral_Load</name>\n  <description>Clients given 5B with Undetectable_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:06:53 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:07:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2363</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:06:53',4,'2023-08-17 11:07:37',4,0,NULL,NULL,NULL,'d7418afd-aca2-46e9-9c72-e920d447db27'),(2364,'Clients given 5C with >=20Copies_Viral_Load','Clients given 5C with >=20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ee32f98e-445e-4a15-8a1e-c594ad7729b3\" retired=\"false\">\n  <name>Clients given 5C with &gt;=20Copies_Viral_Load</name>\n  <description>Clients given 5C with &gt;=20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:13:04 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:15:46 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2364</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:13:04',4,'2023-08-17 11:15:46',4,0,NULL,NULL,NULL,'ee32f98e-445e-4a15-8a1e-c594ad7729b3'),(2365,'Clients given 5C with <20Copies_Viral_Load','Clients given 5C with <20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5fc6059b-5dca-4e92-abe4-e44c4e5f9f09\" retired=\"false\">\n  <name>Clients given 5C with &lt;20Copies_Viral_Load</name>\n  <description>Clients given 5C with &lt;20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:18:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:19:06 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2365</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:18:17',4,'2023-08-17 11:19:06',4,0,NULL,NULL,NULL,'5fc6059b-5dca-4e92-abe4-e44c4e5f9f09'),(2366,'Clients given 5C with Undetectable Viral Load','Clients given 5C with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f3e6450c-1bda-42b4-87d3-352e65c53612\" retired=\"false\">\n  <name>Clients given 5C with Undetectable Viral Load</name>\n  <description>Clients given 5C with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:20:42 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:21:13 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2366</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:20:42',4,'2023-08-17 11:21:13',4,0,NULL,NULL,NULL,'f3e6450c-1bda-42b4-87d3-352e65c53612'),(2367,'Clients given 5D with >=20Copies_Viral_Load','Clients given 5D with >=20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"25589972-ceb9-4c56-bb7c-2911f712e272\" retired=\"false\">\n  <name>Clients given 5D with &gt;=20Copies_Viral_Load</name>\n  <description>Clients given 5D with &gt;=20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:31:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:32:04 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2367</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:31:21',4,'2023-08-17 11:32:04',4,0,NULL,NULL,NULL,'25589972-ceb9-4c56-bb7c-2911f712e272'),(2368,'Clients given 5D with <20Copies_Viral_Load','Clients given 5D with <20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a9a60d85-6eba-4872-9b0c-02c941d7ff94\" retired=\"false\">\n  <name>Clients given 5D with &lt;20Copies_Viral_Load</name>\n  <description>Clients given 5D with &lt;20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:34:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:36:20 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2368</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:34:28',4,'2023-08-17 11:36:20',4,0,NULL,NULL,NULL,'a9a60d85-6eba-4872-9b0c-02c941d7ff94'),(2369,'Clients given 4D with poor adherence','Clients given 4D with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"76e21882-219e-4852-aca2-a0d774c1c79b\" retired=\"false\">\n  <name>Clients given 4D with poor adherence</name>\n  <description>Clients given 4D with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:51:32 UTC</dateCreated>\n  <parameters id=\"4\"/>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:51:32',4,NULL,NULL,0,NULL,NULL,NULL,'76e21882-219e-4852-aca2-a0d774c1c79b'),(2370,'Clients given 5a with poor adherence','Clients given 5a with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"67dd544b-2e27-408f-824b-0312d06e9785\" retired=\"false\">\n  <name>Clients given 5a with poor adherence</name>\n  <description>Clients given 5a with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:51:59 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:53:44 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2370</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:51:59',4,'2023-08-17 11:53:44',4,0,NULL,NULL,NULL,'67dd544b-2e27-408f-824b-0312d06e9785'),(2371,'Clients given 5a with fair adherence','Clients given 5a with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"93e07039-5627-49fd-9fb4-9f3cf8ddaafd\" retired=\"false\">\n  <name>Clients given 5a with fair adherence</name>\n  <description>Clients given 5a with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:56:02 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:56:33 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2371</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:56:02',4,'2023-08-17 11:56:33',4,0,NULL,NULL,NULL,'93e07039-5627-49fd-9fb4-9f3cf8ddaafd'),(2372,'Clients given 5a with good adherence','Clients given 5a with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"94df16c2-5336-419b-be14-fe6c390dc41b\" retired=\"false\">\n  <name>Clients given 5a with good adherence</name>\n  <description>Clients given 5a with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:57:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:58:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2372</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3681)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:57:50',4,'2023-08-17 11:58:24',4,0,NULL,NULL,NULL,'94df16c2-5336-419b-be14-fe6c390dc41b'),(2373,'Clients given 5D with Undetectable Viral Load','Clients given 5D with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"95abcfbb-daac-4a02-a38c-455f5f0aca2d\" retired=\"false\">\n  <name>Clients given 5D with Undetectable Viral Load</name>\n  <description>Clients given 5D with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 09:58:03 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 09:58:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2373</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 11:58:03',4,'2023-08-17 11:58:42',4,0,NULL,NULL,NULL,'95abcfbb-daac-4a02-a38c-455f5f0aca2d'),(2374,'Clients given 5E with >=20Copies_Viral_Load','Clients given 5E with >=20Copies_Viral_Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7ec09187-6a9d-403e-97c3-f7d85f2a16a2\" retired=\"false\">\n  <name>Clients given 5E with &gt;=20Copies_Viral_Load</name>\n  <description>Clients given 5E with &gt;=20Copies_Viral_Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:05:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:05:33 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2374</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:05:15',4,'2023-08-17 12:05:33',4,0,NULL,NULL,NULL,'7ec09187-6a9d-403e-97c3-f7d85f2a16a2'),(2375,'Clients given 5E with <20 Copies Viral Load','Clients given 5E with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"fc0384af-2aba-4967-94cf-351c49ff4c06\" retired=\"false\">\n  <name>Clients given 5E with &lt;20 Copies Viral Load</name>\n  <description>Clients given 5E with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:06:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:09:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2375</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:06:47',4,'2023-08-17 12:09:36',4,0,NULL,NULL,NULL,'fc0384af-2aba-4967-94cf-351c49ff4c06'),(2376,'Clients given 5b with fair adherence','Clients given 5b with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"efbcc56c-18cd-4533-980c-6d8cf1c02e23\" retired=\"false\">\n  <name>Clients given 5b with fair adherence</name>\n  <description>Clients given 5b with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:10:23 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:12:23 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2376</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:10:23',4,'2023-08-17 12:12:23',4,0,NULL,NULL,NULL,'efbcc56c-18cd-4533-980c-6d8cf1c02e23'),(2377,'Clients given 5E with Undetectable Viral Load','Clients given 5E with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c1b14868-35fc-4ced-b9d6-d7434dbe4b96\" retired=\"false\">\n  <name>Clients given 5E with Undetectable Viral Load</name>\n  <description>Clients given 5E with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:10:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:11:44 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2377</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:10:47',4,'2023-08-17 12:11:44',4,0,NULL,NULL,NULL,'c1b14868-35fc-4ced-b9d6-d7434dbe4b96'),(2378,'Clients given 5b with good adherence','Clients given 5b with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"602e0915-bb58-4b03-a63e-ed3a6f83cc33\" retired=\"false\">\n  <name>Clients given 5b with good adherence</name>\n  <description>Clients given 5b with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:14:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:15:01 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2378</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:14:15',4,'2023-08-17 12:15:01',4,0,NULL,NULL,NULL,'602e0915-bb58-4b03-a63e-ed3a6f83cc33'),(2379,'Clients given 5b with poor adherence','Clients given 5b with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"02a6a90c-a410-4c5e-a32f-a56f6dad4a49\" retired=\"false\">\n  <name>Clients given 5b with poor adherence</name>\n  <description>Clients given 5b with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:20:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:24:24 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2379</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3682)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:20:28',4,'2023-08-17 12:24:24',4,0,NULL,NULL,NULL,'02a6a90c-a410-4c5e-a32f-a56f6dad4a49'),(2380,'Clients given 5F with >=20Copies Viral Load','Clients given 5F with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ed92d4db-077e-4eae-9c2c-963d455b9df3\" retired=\"false\">\n  <name>Clients given 5F with &gt;=20Copies Viral Load</name>\n  <description>Clients given 5F with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:20:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:22:29 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2380</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n (SELECT weight_.Id, _weight&#xd;\n from&#xd;\n (select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_numeric)), 20) as _weight&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 119 and oss.voided=0&#xd;\n		 and oss.obs_datetime &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id)AS weight_&#xd;\n		 where _weight &gt;= 20 and _weight &lt;= 24.9)peads_weight&#xd;\n	ON Active_Patients.Id = peads_weight.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:20:38',4,'2023-08-17 12:22:29',4,0,NULL,NULL,NULL,'ed92d4db-077e-4eae-9c2c-963d455b9df3'),(2381,'Clients given 5F with <20 Copies Viral Load','Clients given 5F with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9ca8ee52-584e-4164-85a0-73c3afffa236\" retired=\"false\">\n  <name>Clients given 5F with &lt;20 Copies Viral Load</name>\n  <description>Clients given 5F with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:27:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:34:06 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2381</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:27:57',4,'2023-08-17 12:34:06',4,0,NULL,NULL,NULL,'9ca8ee52-584e-4164-85a0-73c3afffa236'),(2382,'Clients given 5F with Undetectable Viral Load','Clients given 5F with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"fddbb793-03b3-432b-aa85-1afddec431d9\" retired=\"false\">\n  <name>Clients given 5F with Undetectable Viral Load</name>\n  <description>Clients given 5F with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:36:35 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:37:44 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2382</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:36:35',4,'2023-08-17 12:37:44',4,0,NULL,NULL,NULL,'fddbb793-03b3-432b-aa85-1afddec431d9'),(2383,'Clients given 5c with poor adherence','Clients given 5c with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"15d7e4f8-1626-4a98-ae7d-494e2cb6f49b\" retired=\"false\">\n  <name>Clients given 5c with poor adherence</name>\n  <description>Clients given 5c with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:39:09 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:40:19 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2383</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:39:09',4,'2023-08-17 12:40:19',4,0,NULL,NULL,NULL,'15d7e4f8-1626-4a98-ae7d-494e2cb6f49b'),(2384,'Clients given 5G with >=20Copies Viral Load','Clients given 5G with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2a249734-89d9-4f4c-bcab-dff2815d3b58\" retired=\"false\">\n  <name>Clients given 5G with &gt;=20Copies Viral Load</name>\n  <description>Clients given 5G with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:42:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:42:29 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2384</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5G&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:42:06',4,'2023-08-17 12:42:29',4,0,NULL,NULL,NULL,'2a249734-89d9-4f4c-bcab-dff2815d3b58'),(2385,'Clients given 5c with fair adherence','Clients given 5c with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"4d26e5f3-76e3-49fc-8a3c-f5de81a7724d\" retired=\"false\">\n  <name>Clients given 5c with fair adherence</name>\n  <description>Clients given 5c with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:42:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:43:23 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2385</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:42:21',4,'2023-08-17 12:43:23',4,0,NULL,NULL,NULL,'4d26e5f3-76e3-49fc-8a3c-f5de81a7724d'),(2386,'Clients given 5G with <20 Copies Viral Load','Clients given 5G with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"353bb356-a392-4c21-8641-40fd092426ce\" retired=\"false\">\n  <name>Clients given 5G with &lt;20 Copies Viral Load</name>\n  <description>Clients given 5G with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:45:37 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:48:38 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2386</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5G&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:45:37',4,'2023-08-17 12:48:38',4,0,NULL,NULL,NULL,'353bb356-a392-4c21-8641-40fd092426ce'),(2387,'Clients given 5c with good adherence','Clients given 5c with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"3f30f547-9fa6-4336-b034-e79a64906b6c\" retired=\"false\">\n  <name>Clients given 5c with good adherence</name>\n  <description>Clients given 5c with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:56:34 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:57:29 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2387</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4696)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:56:34',4,'2023-08-17 12:57:29',4,0,NULL,NULL,NULL,'3f30f547-9fa6-4336-b034-e79a64906b6c'),(2388,'Clients given 5G with Undetectable Viral Load','Clients given 5G with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7cb7f18e-986e-4854-be48-ca51e1d753dc\" retired=\"false\">\n  <name>Clients given 5G with Undetectable Viral Load</name>\n  <description>Clients given 5G with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 10:58:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 10:58:41 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2388</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5G&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 12:58:06',4,'2023-08-17 12:58:41',4,0,NULL,NULL,NULL,'7cb7f18e-986e-4854-be48-ca51e1d753dc'),(2389,'Clients given 5d with poor adherence','Clients given 5d with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"77c59203-be56-4041-abaf-eb409f199aab\" retired=\"false\">\n  <name>Clients given 5d with poor adherence</name>\n  <description>Clients given 5d with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:03:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:03:56 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2389</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:03:17',4,'2023-08-17 13:03:56',4,0,NULL,NULL,NULL,'77c59203-be56-4041-abaf-eb409f199aab'),(2390,'Clients given 5d with fair adherence','Clients given 5d with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"33ef5391-29b2-426b-bb43-75f88df81f18\" retired=\"false\">\n  <name>Clients given 5d with fair adherence</name>\n  <description>Clients given 5d with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:06:27 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:07:15 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2390</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:06:27',4,'2023-08-17 13:07:15',4,0,NULL,NULL,NULL,'33ef5391-29b2-426b-bb43-75f88df81f18'),(2391,'Clients given 5H with >=20Copies Viral Load','Clients given 5H with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a6c02fb1-c931-4405-9dcd-1fa775e9d262\" retired=\"false\">\n  <name>Clients given 5H with &gt;=20Copies Viral Load</name>\n  <description>Clients given 5H with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:06:39 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:07:19 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2391</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5H&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:06:39',4,'2023-08-17 13:07:19',4,0,NULL,NULL,NULL,'a6c02fb1-c931-4405-9dcd-1fa775e9d262'),(2392,':Clients given 5d with good adherence',':Clients given 5d with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"478a65e7-cbfc-4d04-bcbf-e97ad2119117\" retired=\"false\">\n  <name>:Clients given 5d with good adherence</name>\n  <description>:Clients given 5d with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:08:05 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:08:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2392</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4697)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:08:05',4,'2023-08-17 13:08:51',4,0,NULL,NULL,NULL,'478a65e7-cbfc-4d04-bcbf-e97ad2119117'),(2393,'Clients given 5H with <20 Copies Viral Load','Clients given 5H with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"92d662a9-7c9c-4d7f-8105-7892cc50f8df\" retired=\"false\">\n  <name>Clients given 5H with &lt;20 Copies Viral Load</name>\n  <description>Clients given 5H with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:08:35 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:09:13 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2393</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5H&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:08:35',4,'2023-08-17 13:09:13',4,0,NULL,NULL,NULL,'92d662a9-7c9c-4d7f-8105-7892cc50f8df'),(2394,'Clients given 5H with Undetectable Viral Load','Clients given 5H with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"67ad52ec-1ca8-4bd4-977e-cb0930173888\" retired=\"false\">\n  <name>Clients given 5H with Undetectable Viral Load</name>\n  <description>Clients given 5H with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:10:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:12:04 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2394</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5H&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1&#xd;\n						 )&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:10:21',4,'2023-08-17 13:12:04',4,0,NULL,NULL,NULL,'67ad52ec-1ca8-4bd4-977e-cb0930173888'),(2395,'Clients given 5e with poor adherence','Clients given 5e with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"13802910-1107-47fe-82b8-60340f77abef\" retired=\"false\">\n  <name>Clients given 5e with poor adherence</name>\n  <description>Clients given 5e with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:11:53 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:12:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2395</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:11:53',4,'2023-08-17 13:12:26',4,0,NULL,NULL,NULL,'13802910-1107-47fe-82b8-60340f77abef'),(2396,'Clients given 5e with fair adherence','Clients given 5e with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6585614b-c405-4fe5-bcb0-8edae5825b41\" retired=\"false\">\n  <name>Clients given 5e with fair adherence</name>\n  <description>Clients given 5e with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:13:19 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:13:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2396</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:13:19',4,'2023-08-17 13:13:43',4,0,NULL,NULL,NULL,'6585614b-c405-4fe5-bcb0-8edae5825b41'),(2397,'Clients given 5e with good adherence','Clients given 5e with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"dc9c0189-b91f-4b80-a484-67e2f5b4005c\" retired=\"false\">\n  <name>Clients given 5e with good adherence</name>\n  <description>Clients given 5e with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:17:29 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:18:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2397</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4698)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:17:29',4,'2023-08-17 13:18:09',4,0,NULL,NULL,NULL,'dc9c0189-b91f-4b80-a484-67e2f5b4005c'),(2398,'Clients given 6A with >=20Copies Viral Load','Clients given 6A with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"b0f47001-fdc3-4ea5-be0c-00112fab3bc8\" retired=\"false\">\n  <name>Clients given 6A with &gt;=20Copies Viral Load</name>\n  <description>Clients given 6A with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:19:05 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:19:35 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2398</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:19:05',4,'2023-08-17 13:19:35',4,0,NULL,NULL,NULL,'b0f47001-fdc3-4ea5-be0c-00112fab3bc8'),(2399,'Clients given 6A with <20 Copies Viral Load','Clients given 6A 