select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:21:31',4,'2023-08-17 13:22:34',4,0,NULL,NULL,NULL,'b912ab78-0fb9-4639-a1f4-56f1e6b2e44e'),(2400,'Clients given 6A with Undetectable Viral Load','Clients given 6A with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"2801df34-8bcf-4a7b-bc89-1210ad3d727d\" retired=\"false\">\n  <name>Clients given 6A with Undetectable Viral Load</name>\n  <description>Clients given 6A with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:23:42 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:24:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2400</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6A&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:23:42',4,'2023-08-17 13:24:21',4,0,NULL,NULL,NULL,'2801df34-8bcf-4a7b-bc89-1210ad3d727d'),(2401,'Clients given 5f with poor adherence','Clients given 5f with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c0c6a92f-87ed-4149-85af-4ed2e31328ac\" retired=\"false\">\n  <name>Clients given 5f with poor adherence</name>\n  <description>Clients given 5f with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:26:41 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:27:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2401</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5f&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:26:41',4,'2023-08-17 13:27:36',4,0,NULL,NULL,NULL,'c0c6a92f-87ed-4149-85af-4ed2e31328ac'),(2402,'Clients given 6B with >=20Copies Viral Load','Clients given 6B with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c01f687e-baef-4589-b4fd-63abfc132991\" retired=\"false\">\n  <name>Clients given 6B with &gt;=20Copies Viral Load</name>\n  <description>Clients given 6B with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:27:26 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:31:50 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2402</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:27:26',4,'2023-08-17 13:31:50',4,0,NULL,NULL,NULL,'c01f687e-baef-4589-b4fd-63abfc132991'),(2403,'Clients given 6B with <20 Copies Viral Load','Clients given 6B with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f6a13155-22a3-4ecc-80bf-dfef935ebf86\" retired=\"false\">\n  <name>Clients given 6B with &lt;20 Copies Viral Load</name>\n  <description>Clients given 6B with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:29:39 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:30:18 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2403</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:29:39',4,'2023-08-17 13:30:18',4,0,NULL,NULL,NULL,'f6a13155-22a3-4ecc-80bf-dfef935ebf86'),(2404,'Clients given 5f with fair adherence','Clients given 5f with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"250972a3-6fab-4d66-a028-7c43751cf95d\" retired=\"false\">\n  <name>Clients given 5f with fair adherence</name>\n  <description>Clients given 5f with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:31:51 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:32:47 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2404</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5f&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:31:51',4,'2023-08-17 13:32:47',4,0,NULL,NULL,NULL,'250972a3-6fab-4d66-a028-7c43751cf95d'),(2405,'Clients given 6B with Undetectable Viral Load','Clients given 6B with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8a1f9b0e-f55d-40ed-b59f-92971f598921\" retired=\"false\">\n  <name>Clients given 6B with Undetectable Viral Load</name>\n  <description>Clients given 6B with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:32:32 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:33:32 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2405</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6B&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:32:32',4,'2023-08-17 13:33:32',4,0,NULL,NULL,NULL,'8a1f9b0e-f55d-40ed-b59f-92971f598921'),(2406,'Clients given 5f with good adherence','Clients given 5f with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"8839041b-b3d1-48b1-a0b2-bc09f91cad73\" retired=\"false\">\n  <name>Clients given 5f with good adherence</name>\n  <description>Clients given 5f with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:36:40 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:37:11 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2406</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5f&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4699)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:36:40',4,'2023-08-17 13:37:11',4,0,NULL,NULL,NULL,'8839041b-b3d1-48b1-a0b2-bc09f91cad73'),(2407,'Clients given 6C with >=20 Copies Viral Load','Clients given 6C with >=20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c44258e3-391b-4e79-87f6-c647692cb3a1\" retired=\"false\">\n  <name>Clients given 6C with &gt;=20 Copies Viral Load</name>\n  <description>Clients given 6C with &gt;=20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:39:53 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:40:55 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2407</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:39:53',4,'2023-08-17 13:40:55',4,0,NULL,NULL,NULL,'c44258e3-391b-4e79-87f6-c647692cb3a1'),(2408,'Clients given 5g with poor adherence','Clients given 5g with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a21e3c23-e513-4a3f-b229-b0baad328af6\" retired=\"false\">\n  <name>Clients given 5g with poor adherence</name>\n  <description>Clients given 5g with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:41:26 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:41:56 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2408</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5g&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:41:26',4,'2023-08-17 13:41:56',4,0,NULL,NULL,NULL,'a21e3c23-e513-4a3f-b229-b0baad328af6'),(2409,'Clients given 6C with <20 Copies Viral Load','Clients given 6C with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"307392db-30aa-4e4c-a692-ab8350cb3f42\" retired=\"false\">\n  <name>Clients given 6C with &lt;20 Copies Viral Load</name>\n  <description>Clients given 6C with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:42:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:43:20 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2409</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:42:38',4,'2023-08-17 13:43:20',4,0,NULL,NULL,NULL,'307392db-30aa-4e4c-a692-ab8350cb3f42'),(2410,'Clients given 5g with fair adherence','Clients given 5g with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"0875bc5c-9df9-43d6-8e7a-5363f19adc4f\" retired=\"false\">\n  <name>Clients given 5g with fair adherence</name>\n  <description>Clients given 5g with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:43:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:43:28 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2410</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5g&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:43:06',4,'2023-08-17 13:43:28',4,0,NULL,NULL,NULL,'0875bc5c-9df9-43d6-8e7a-5363f19adc4f'),(2411,'Clients given 6C with Undetectable Viral Load','Clients given 6C with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"eb4392cf-c7f5-43c2-8f45-b56f46771ea3\" retired=\"false\">\n  <name>Clients given 6C with Undetectable Viral Load</name>\n  <description>Clients given 6C with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:45:31 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:46:32 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2411</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6C&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:45:31',4,'2023-08-17 13:46:32',4,0,NULL,NULL,NULL,'eb4392cf-c7f5-43c2-8f45-b56f46771ea3'),(2412,'Clients given 5g with good adherence','Clients given 5g with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9878645d-2648-4c62-8679-1449355eaf0a\" retired=\"false\">\n  <name>Clients given 5g with good adherence</name>\n  <description>Clients given 5g with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:46:09 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:46:30 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2412</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5g&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4700)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:46:09',4,'2023-08-17 13:46:30',4,0,NULL,NULL,NULL,'9878645d-2648-4c62-8679-1449355eaf0a'),(2413,'Clients given 5h with poor adherence','Clients given 5h with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ad1e42cb-ff60-47fd-b8b1-0649da1899a1\" retired=\"false\">\n  <name>Clients given 5h with poor adherence</name>\n  <description>Clients given 5h with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:49:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:51:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2413</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5h&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:49:55',4,'2023-08-17 13:51:43',4,0,NULL,NULL,NULL,'ad1e42cb-ff60-47fd-b8b1-0649da1899a1'),(2414,'Clients given 6D with >=20Copies Viral Load','Clients given 6D with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"dbcd7d71-ba25-4619-8d23-dd2592aaf59a\" retired=\"false\">\n  <name>Clients given 6D with &gt;=20Copies Viral Load</name>\n  <description>Clients given 6D with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:50:35 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:51:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2414</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:50:35',4,'2023-08-17 13:51:45',4,0,NULL,NULL,NULL,'dbcd7d71-ba25-4619-8d23-dd2592aaf59a'),(2415,'Clients given 6D with <20 Copies Viral Load','Clients given 6D with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"0199fd5f-2426-4c4e-b266-818a815ba80a\" retired=\"false\">\n  <name>Clients given 6D with &lt;20 Copies Viral Load</name>\n  <description>Clients given 6D with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:53:15 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:54:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2415</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:53:15',4,'2023-08-17 13:54:09',4,0,NULL,NULL,NULL,'0199fd5f-2426-4c4e-b266-818a815ba80a'),(2416,'Clients given 5h with fair adherence','Clients given 5h with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5478dbb5-4f3d-4a39-b263-625158d98129\" retired=\"false\">\n  <name>Clients given 5h with fair adherence</name>\n  <description>Clients given 5h with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:54:17 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:54:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2416</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5h&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:54:17',4,'2023-08-17 13:54:39',4,0,NULL,NULL,NULL,'5478dbb5-4f3d-4a39-b263-625158d98129'),(2417,'Clients given 6D with Undetectable Viral Load','Clients given 6D with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"10a317c1-829c-4739-b7c0-f0b4ba18a69f\" retired=\"false\">\n  <name>Clients given 6D with Undetectable Viral Load</name>\n  <description>Clients given 6D with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:55:34 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:56:31 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2417</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6D&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:55:34',4,'2023-08-17 13:56:31',4,0,NULL,NULL,NULL,'10a317c1-829c-4739-b7c0-f0b4ba18a69f'),(2418,'Clients given 5h with good adherence','Clients given 5h with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"00df085c-fd67-466a-94fa-2807a5cce6f7\" retired=\"false\">\n  <name>Clients given 5h with good adherence</name>\n  <description>Clients given 5h with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 11:57:56 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 11:58:25 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2418</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 5h&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4701)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 13:57:56',4,'2023-08-17 13:58:25',4,0,NULL,NULL,NULL,'00df085c-fd67-466a-94fa-2807a5cce6f7'),(2419,'Clients given 6E with >=20Copies Viral Load','Clients given 6E with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7c9d1608-dd16-4a6f-a811-aa9c285da131\" retired=\"false\">\n  <name>Clients given 6E with &gt;=20Copies Viral Load</name>\n  <description>Clients given 6E with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:02:11 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:04:41 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2419</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:02:11',4,'2023-08-17 14:04:41',4,0,NULL,NULL,NULL,'7c9d1608-dd16-4a6f-a811-aa9c285da131'),(2420,'Clients given 6a with poor adherence','Clients given 6a with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"b1f7d697-7125-4ad4-b73d-8538c0d0bf37\" retired=\"false\">\n  <name>Clients given 6a with poor adherence</name>\n  <description>Clients given 6a with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:07:35 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:07:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2420</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:07:35',4,'2023-08-17 14:07:53',4,0,NULL,NULL,NULL,'b1f7d697-7125-4ad4-b73d-8538c0d0bf37'),(2421,'Clients given 6E with <20 Copies Viral Load','Clients given 6E with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"76cdd1d3-9bb0-462b-a63d-5babfae535ae\" retired=\"false\">\n  <name>Clients given 6E with &lt;20 Copies Viral Load</name>\n  <description>Clients given 6E with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:07:43 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:08:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2421</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:07:43',4,'2023-08-17 14:08:22',4,0,NULL,NULL,NULL,'76cdd1d3-9bb0-462b-a63d-5babfae535ae'),(2422,'Clients given 6a with fair adherence','Clients given 6a with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"7caf8270-2015-4b33-9cc4-2d23dcbbdd40\" retired=\"false\">\n  <name>Clients given 6a with fair adherence</name>\n  <description>Clients given 6a with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:09:05 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:09:40 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2422</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:09:05',4,'2023-08-17 14:09:40',4,0,NULL,NULL,NULL,'7caf8270-2015-4b33-9cc4-2d23dcbbdd40'),(2423,'Clients given 6E with Undetectable Viral Load','Clients given 6E with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"42483bdd-5217-4e57-acfb-9dd6c405fc4e\" retired=\"false\">\n  <name>Clients given 6E with Undetectable Viral Load</name>\n  <description>Clients given 6E with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:09:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:10:12 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2423</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6E&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						   INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:09:16',4,'2023-08-17 14:10:12',4,0,NULL,NULL,NULL,'42483bdd-5217-4e57-acfb-9dd6c405fc4e'),(2424,'Clients given 6a with good adherence','Clients given 6a with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"495d25ab-dea0-49b3-89de-2f64548597eb\" retired=\"false\">\n  <name>Clients given 6a with good adherence</name>\n  <description>Clients given 6a with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:11:25 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:11:53 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2424</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6a&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3686)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:11:25',4,'2023-08-17 14:11:53',4,0,NULL,NULL,NULL,'495d25ab-dea0-49b3-89de-2f64548597eb'),(2425,'Clients given 6F with >=20Copies Viral Load','Clients given 6F with >=20Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"72be7653-8e41-42f4-9a8d-caa979c15ef6\" retired=\"false\">\n  <name>Clients given 6F with &gt;=20Copies Viral Load</name>\n  <description>Clients given 6F with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:12:26 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:13:56 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2425</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4705)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &gt;=20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and oss.obs_datetime &lt;= cast(&apos;2023-06-30&apos;as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &gt;=20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4265&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) greaterThan20&#xd;\non Active_Patients.Id = greaterThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:12:26',4,'2023-08-17 14:13:56',4,0,NULL,NULL,NULL,'72be7653-8e41-42f4-9a8d-caa979c15ef6'),(2426,'Clients given 6F with <20 Copies Viral Load','Clients given 6F with <20 Copies Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d11f84f3-e524-4688-9ad5-450362112a3d\" retired=\"false\">\n  <name>Clients given 6F with &lt;20 Copies Viral Load</name>\n  <description>Clients given 6F with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:14:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:15:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2426</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4705)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- &lt;20 Copies, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- &lt;20 Copies &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4264&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) lessThan20&#xd;\non Active_Patients.Id = lessThan20.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:14:54',4,'2023-08-17 14:15:37',4,0,NULL,NULL,NULL,'d11f84f3-e524-4688-9ad5-450362112a3d'),(2427,'Clients given 6b with poor adherence','Clients given 6b with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c16525a3-70e2-41e5-948b-171525dbc0aa\" retired=\"false\">\n  <name>Clients given 6b with poor adherence</name>\n  <description>Clients given 6b with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:15:12 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:16:00 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2427</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:15:12',4,'2023-08-17 14:16:00',4,0,NULL,NULL,NULL,'c16525a3-70e2-41e5-948b-171525dbc0aa'),(2428,'Clients given 6F with Undetectable Viral Load','Clients given 6F with Undetectable Viral Load','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e278c929-0e08-4577-92f9-e1a972fcf688\" retired=\"false\">\n  <name>Clients given 6F with Undetectable Viral Load</name>\n  <description>Clients given 6F with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:16:55 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:17:37 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2428</id>\n  <query>									   &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6F&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n								floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n						-- Picking Followup Date from Latest Followup Form&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 &#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n		&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n										-- Visitors&#xd;\n								select person_id &#xd;\n								FROM&#xd;\n								(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n								from obs where concept_id = 5416 &#xd;\n								and value_coded = 1 and voided = 0&#xd;\n								and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n								and voided = 0&#xd;\n								group by person_id)visitor&#xd;\n&#xd;\n							)&#xd;\n						 )&#xd;\n					&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						  INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n						WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n						having Age &lt; 15&#xd;\n				   ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n		FROM(&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2250&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as currentreg&#xd;\n					&#xd;\n					LEFT OUTER JOIN									&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 4284&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as substitutereg&#xd;\n					ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n					LEFT OUTER JOIN					&#xd;\n&#xd;\n					&#xd;\n					(select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n					from obs o &#xd;\n					INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n					where o.concept_id = 2268&#xd;\n					AND o.voided = 0&#xd;\n					and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n					group by person_id) as switchreg&#xd;\n					ON switchreg.person_id =  currentreg.person_id&#xd;\n		)				&#xd;\n		&#xd;\n		)as regimen&#xd;\n		where regimen.ARV_regimen = 4705)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n-- undetectable, Vira load results&#xd;\n	(&#xd;\n		select o.person_id as Id, o.value_coded&#xd;\n		from obs o &#xd;\n		inner join &#xd;\n				(&#xd;\n				select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n				SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as observation_id&#xd;\n				from obs oss&#xd;\n				-- Viral load form &#xd;\n				where oss.concept_id = 4273&#xd;\n				and oss.voided=0&#xd;\n				and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n				group by oss.person_id&#xd;\n				)latest &#xd;\n			on latest.person_id = o.person_id&#xd;\n			-- Undetectable &#xd;\n			where o.concept_id = 4266 and o.value_coded = 4263&#xd;\n			and  o.obs_datetime = max_observation&#xd;\n		group by o.person_id&#xd;\n	) Undetectable&#xd;\non Active_Patients.Id = Undetectable.Id&#xd;\n&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:16:55',4,'2023-08-17 14:17:37',4,0,NULL,NULL,NULL,'e278c929-0e08-4577-92f9-e1a972fcf688');
INSERT INTO `serialized_object` VALUES (2429,'Clients given 5a with >=20Copies Viral Load','Clients given 5a with >=20Copies Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"ac679df3-e5a4-4548-ba63-4fd778196ea4\" retired=\"false\">\n  <name>Clients given 5a with &gt;=20Copies Viral Load</name>\n  <description>Clients given 5a with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:19:02 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:21:57 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2429</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"f9c21dfa-e2bc-4174-858c-5290ee412c83\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:19:02',4,'2023-08-17 14:21:57',4,0,NULL,NULL,NULL,'ac679df3-e5a4-4548-ba63-4fd778196ea4'),(2430,'Clients given 6b with fair adherence','Clients given 6b with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c4aaf23a-6f87-424e-b8d6-b1519273b376\" retired=\"false\">\n  <name>Clients given 6b with fair adherence</name>\n  <description>Clients given 6b with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:19:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:19:59 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2430</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:19:38',4,'2023-08-17 14:19:59',4,0,NULL,NULL,NULL,'c4aaf23a-6f87-424e-b8d6-b1519273b376'),(2431,'Clients given 6b with good adherence','Clients given 6b with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"96917926-b178-4bf4-8113-7300329ee951\" retired=\"false\">\n  <name>Clients given 6b with good adherence</name>\n  <description>Clients given 6b with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:21:00 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:21:45 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2431</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6b&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 3687)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:21:00',4,'2023-08-17 14:21:45',4,0,NULL,NULL,NULL,'96917926-b178-4bf4-8113-7300329ee951'),(2432,'Clients given 5A with <20Copies Viral Load','Clients given 5A with <20Copies Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"9a1038ff-dcfd-4b2c-93a9-d7c68030d1ef\" retired=\"false\">\n  <name>Clients given 5A with &lt;20Copies Viral Load</name>\n  <description>Clients given 5A with &lt;20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:23:16 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:25:32 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2432</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"f803bb84-0a18-4319-91e7-4ea289d8a295\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:23:16',4,'2023-08-17 14:25:32',4,0,NULL,NULL,NULL,'9a1038ff-dcfd-4b2c-93a9-d7c68030d1ef'),(2433,'Clients given 5A with Undetectable Viral Load','Clients given 5A with Undetectable Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"f401ae7b-f27f-4b25-926f-65e3b8c81863\" retired=\"false\">\n  <name>Clients given 5A with Undetectable Viral Load</name>\n  <description>Clients given 5A with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:27:23 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:28:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2433</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"2386a884-ae79-46a7-8adf-d5044b06e9c4\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:27:23',4,'2023-08-17 14:28:22',4,0,NULL,NULL,NULL,'f401ae7b-f27f-4b25-926f-65e3b8c81863'),(2434,'Clients given 5B with >=20Copies Viral Load','Clients given 5B with >=20Copies Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"938a8cf8-cfb9-422e-be17-3a1e59e3c135\" retired=\"false\">\n  <name>Clients given 5B with &gt;=20Copies Viral Load</name>\n  <description>Clients given 5B with &gt;=20Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:29:26 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:33:25 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2434</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"5939e332-e3fc-4a42-a736-b647f31a87a3\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:29:26',4,'2023-08-17 14:33:25',4,0,NULL,NULL,NULL,'938a8cf8-cfb9-422e-be17-3a1e59e3c135'),(2435,'Clients given 6c with poor adherence','Clients given 6c with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a854add1-66a5-4624-94b8-ee9cc9f6b618\" retired=\"false\">\n  <name>Clients given 6c with poor adherence</name>\n  <description>Clients given 6c with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:34:23 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:35:25 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2435</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:34:23',4,'2023-08-17 14:35:25',4,0,NULL,NULL,NULL,'a854add1-66a5-4624-94b8-ee9cc9f6b618'),(2436,'Clients given 5B with <20 Copies Viral Load','','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"160dcddc-c186-4d31-a0c8-47edca4fc581\" retired=\"false\">\n  <name>Clients given 5B with &lt;20 Copies Viral Load</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:34:37 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:35:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2436</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"8b4f6f3d-4444-4429-ac84-94ecc1e14ba2\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:34:37',4,'2023-08-17 14:35:36',4,0,NULL,NULL,NULL,'160dcddc-c186-4d31-a0c8-47edca4fc581'),(2437,'Clients given 5B with Undetectable Viral Load','Clients given 5B with Undetectable Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"5f976c00-44ef-4b36-bed0-b976bb7f2b55\" retired=\"false\">\n  <name>Clients given 5B with Undetectable Viral Load</name>\n  <description>Clients given 5B with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:36:46 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:38:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2437</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"d7418afd-aca2-46e9-9c72-e920d447db27\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:36:46',4,'2023-08-17 14:38:09',4,0,NULL,NULL,NULL,'5f976c00-44ef-4b36-bed0-b976bb7f2b55'),(2438,'Clients given 6c with fair adherence','Clients given 6c with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"65b4eb44-cc9f-494e-b621-ee1bdedbc549\" retired=\"false\">\n  <name>Clients given 6c with fair adherence</name>\n  <description>Clients given 6c with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:36:48 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:37:12 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2438</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:36:48',4,'2023-08-17 14:37:12',4,0,NULL,NULL,NULL,'65b4eb44-cc9f-494e-b621-ee1bdedbc549'),(2439,'Clients given 6c with good adherence','Clients given 6c with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"17b46231-8af2-49d6-ab43-17a6d13d30d4\" retired=\"false\">\n  <name>Clients given 6c with good adherence</name>\n  <description>Clients given 6c with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:38:40 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:38:57 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2439</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6c&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4702)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:38:40',4,'2023-08-17 14:38:57',4,0,NULL,NULL,NULL,'17b46231-8af2-49d6-ab43-17a6d13d30d4'),(2440,'Clients given 5C with >=20 Copies Viral Load','Clients given 5C with >=20 Copies Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"ddd536bc-c879-4847-9c50-cc79a002813e\" retired=\"false\">\n  <name>Clients given 5C with &gt;=20 Copies Viral Load</name>\n  <description>Clients given 5C with &gt;=20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:38:53 UTC