le.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"fa914aa2-ce96-4063-a749-7718cf76a361\" retired=\"false\">\n  <name>Clients given 6d with poor adherence</name>\n  <description>Clients given 6d with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:40:45 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:41:01 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2441</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:40:45',4,'2023-08-17 14:41:01',4,0,NULL,NULL,NULL,'fa914aa2-ce96-4063-a749-7718cf76a361'),(2442,'Clients given 5C with <20 Copies Viral Load','Clients given 5C with <20 Copies Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"394324e6-b5b5-406f-9fb0-83194dc1b533\" retired=\"false\">\n  <name>Clients given 5C with &lt;20 Copies Viral Load</name>\n  <description>Clients given 5C with &lt;20 Copies Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:41:03 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:43:01 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2442</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"5fc6059b-5dca-4e92-abe4-e44c4e5f9f09\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:41:03',4,'2023-08-17 14:43:01',4,0,NULL,NULL,NULL,'394324e6-b5b5-406f-9fb0-83194dc1b533'),(2443,'Clients given 6d with fair adherence','Clients given 6d with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6a150299-a792-4070-953d-c475224522f9\" retired=\"false\">\n  <name>Clients given 6d with fair adherence</name>\n  <description>Clients given 6d with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:41:48 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:42:15 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2443</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:41:48',4,'2023-08-17 14:42:15',4,0,NULL,NULL,NULL,'6a150299-a792-4070-953d-c475224522f9'),(2444,' Clients given 6d with good adherence',' Clients given 6d with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"66ddc4ec-de69-43a5-8cda-3e7f9f8d28af\" retired=\"false\">\n  <name> Clients given 6d with good adherence</name>\n  <description> Clients given 6d with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:43:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:44:08 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2444</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:43:47',4,'2023-08-17 14:44:08',4,0,NULL,NULL,NULL,'66ddc4ec-de69-43a5-8cda-3e7f9f8d28af'),(2445,'Clients given 5C with Undetectable Viral Load','Clients given 5C with Undetectable Viral Load','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"c75e1385-b87e-49d1-a8ba-418f96c68379\" retired=\"false\">\n  <name>Clients given 5C with Undetectable Viral Load</name>\n  <description>Clients given 5C with Undetectable Viral Load</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:44:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:50:20 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2445</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"f3e6450c-1bda-42b4-87d3-352e65c53612\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 14:44:54',4,'2023-08-17 14:50:20',4,0,NULL,NULL,NULL,'c75e1385-b87e-49d1-a8ba-418f96c68379'),(2446,'Clients given 6e with poor adherence','Clients given 6e with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"0a65b09f-f0a6-45a6-a240-46f0a48dda2a\" retired=\"false\">\n  <name>Clients given 6e with poor adherence</name>\n  <description>Clients given 6e with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:49:27 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:49:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2446</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:49:27',4,'2023-08-17 14:49:43',4,0,NULL,NULL,NULL,'0a65b09f-f0a6-45a6-a240-46f0a48dda2a'),(2447,'Clients given 6e with fair adherence','Clients given 6e with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"3e2fec32-323e-453b-b4e1-23e746f37f1a\" retired=\"false\">\n  <name>Clients given 6e with fair adherence</name>\n  <description>Clients given 6e with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:50:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:50:58 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2447</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2306&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2306&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) fair_adherence&#xd;\non Active_Patients.Id = fair_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:50:30',4,'2023-08-17 14:50:58',4,0,NULL,NULL,NULL,'3e2fec32-323e-453b-b4e1-23e746f37f1a'),(2448,'Clients given 6e with good adherence','Clients given 6e with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ca2d72c9-cfb8-44bd-8859-2813817d6a80\" retired=\"false\">\n  <name>Clients given 6e with good adherence</name>\n  <description>Clients given 6e with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:52:12 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:53:46 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2448</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6e&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4704)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:52:12',4,'2023-08-17 14:53:46',4,0,NULL,NULL,NULL,'ca2d72c9-cfb8-44bd-8859-2813817d6a80'),(2449,'Clients given 6f with poor adherence','Clients given 6f with poor adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"68e19030-f17c-4489-8e26-e854ac11fcde\" retired=\"false\">\n  <name>Clients given 6f with poor adherence</name>\n  <description>Clients given 6f with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 12:55:45 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 12:56:07 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2449</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6f&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR