identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4705)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 3702&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 3702&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) poor_adherence&#xd;\non Active_Patients.Id = poor_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 14:55:45',4,'2023-08-17 14:56:07',4,0,NULL,NULL,NULL,'68e19030-f17c-4489-8e26-e854ac11fcde'),(2450,'Clients given 6f with fair adherence','Clients given 6f with fair adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9680051f-31ff-417c-9560-8bfce8b63699\" retired=\"false\">\n  <name>Clients given 6f with fair adherence</name>\n  <description>Clients given 6f with fair adherence</description>\n  <creator id=\"2\" uuid=\"