\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"65b4eb44-cc9f-494e-b621-ee1bdedbc549\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 17:10:40',4,'2023-08-17 17:12:06',4,0,NULL,NULL,NULL,'f8e62785-7303-493a-9c20-6c9f4280faf0'),(2504,'Clients given 6c with good adherence','Clients given 6c with good adherence','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"9b361e36-e897-4212-8c7f-26121e595425\" retired=\"false\">\n  <name>Clients given 6c with good adherence</name>\n  <description>Clients given 6c with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 15:11:54 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 15:13:48 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2504</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"17b46231-8af2-49d6-ab43-17a6d13d30d4\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 17:11:54',4,'2023-08-17 17:13:48',4,0,NULL,NULL,NULL,'9b361e36-e897-4212-8c7f-26121e595425'),(2505,'Clients given 6d with poor adherence','Clients given 6d with poor adherence','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"56b2509b-811c-4452-8432-5807792f207a\" retired=\"false\">\n  <name>Clients given 6d with poor adherence</name>\n  <description>Clients given 6d with poor adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 15:13:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 15:15:04 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2505</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"fa914aa2-ce96-4063-a749-7718cf76a361\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 17:13:21',4,'2023-08-17 17:15:04',4,0,NULL,NULL,NULL,'56b2509b-811c-4452-8432-5807792f207a'),(2506,'Clients given 6d with fair adherence','Clients given 6d with fair adherence','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"2808446d-305f-4bf7-b83b-3a5aad7cc119\" retired=\"false\">\n  <name>Clients given 6d with fair adherence</name>\n  <description>Clients given 6d with fair adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 15:14:20 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 15:16:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2506</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"6a150299-a792-4070-953d-c475224522f9\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-08-17 17:14:20',4,'2023-08-17 17:16:21',4,0,NULL,NULL,NULL,'2808446d-305f-4bf7-b83b-3a5aad7cc119'),(2507,'Clients given 6d with good adherence','Clients given 6d with good adherence','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"a10f7cfb-6012-4c2a-8f4f-f9ef7cdd8310\" retired=\"false\">\n  <name>Clients given 6d with good adherence</name>\n  <description>Clients given 6d with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 15:17:32 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 15:17:52 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2507</id>\n  <query>                     &#xd;\nselect distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id = :location or parent_location = :location)&#xd;\nand o.person_id in&#xd;\n(SELECT distinct Active_Patients.Id &#xd;\nFROM&#xd;\n((&#xd;\n                            -- 6d&#xd;\n(SELECT  Id&#xd;\n  FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n                floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age&#xd;\n&#xd;\n                from obs o&#xd;\n            -- Picking Followup Date from Latest Followup Form&#xd;\n             INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n             INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n             AND o.person_id in (&#xd;\n             &#xd;\n            select active_clients.person_id&#xd;\n                from&#xd;\n                (select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n                  from obs B&#xd;\n                  inner join &#xd;\n                  (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                  from obs where concept_id = 3753&#xd;\n                  and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                  and voided = 0&#xd;\n                  group by person_id) as A&#xd;\n                  on A.observation_id = B.obs_group_id&#xd;\n                  where concept_id = 3752&#xd;\n                  and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0  &#xd;\n                  group by B.person_id&#xd;\n                ) as active_clients&#xd;\n                where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n    &#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct os.person_id&#xd;\n              from obs os&#xd;\n              where concept_id = 2249&#xd;\n              AND CAST(os.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n              AND CAST(os.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n              AND os.voided = 0&#xd;\n              )&#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n              select distinct(o.person_id)&#xd;\n              from obs o&#xd;\n              where o.person_id in (&#xd;\n                  -- FOLLOW UPS&#xd;\n                    select firstquery.person_id&#xd;\n                    from&#xd;\n                    (&#xd;\n                    select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n                    from obs oss&#xd;\n                          where oss.voided=0 &#xd;\n                          and oss.concept_id=3752 &#xd;\n                          and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n                          group by oss.person_id) firstquery&#xd;\n                    inner join (&#xd;\n                          select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n                          from obs os&#xd;\n                          where concept_id = 3752&#xd;\n                          and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                          group by os.person_id&#xd;\n                          having last_ap &lt; 0&#xd;\n                    ) secondquery&#xd;\n                    on firstquery.person_id = secondquery.person_id&#xd;\n              ) and o.person_id in (&#xd;\n                  -- TOUTS&#xd;\n                  select distinct(person_id)&#xd;\n                  from&#xd;\n                  (&#xd;\n                    select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n                    from obs os&#xd;\n                    where os.concept_id=2266&#xd;\n                    group by os.person_id&#xd;\n                    having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n                  ) as TOUTS&#xd;\n              )     &#xd;\n                    )&#xd;\n      &#xd;\n&#xd;\n    and active_clients.person_id not in (&#xd;\n                  select person_id &#xd;\n                  from person &#xd;\n                  where CAST(death_date AS DATE) &lt;= cast(:endDate as date)&#xd;\n                  and dead = 1 and voided = 0&#xd;\n             )&#xd;\n    and active_clients.person_id not in (&#xd;\n                    -- Visitors&#xd;\n                select person_id &#xd;\n                FROM&#xd;\n                (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                from obs where concept_id = 5416 &#xd;\n                and value_coded = 1 and voided = 0&#xd;\n                and cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                and voided = 0&#xd;\n                group by person_id)visitor&#xd;\n&#xd;\n              )&#xd;\n             )&#xd;\n          &#xd;\n             INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n             INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n            CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n            AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n            WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n            having Age &lt; 15&#xd;\n           ) AS Seen_Previous_ART_Clients&#xd;\n)&#xd;\n&#xd;\n)Active_Patients&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n(SELECT regimen.Id as Id&#xd;\nFROM&#xd;\n( SELECT currentreg.person_id as Id,COALESCE(switch_regimen,substitute_regimen,current_regimen) ARV_regimen&#xd;\n    FROM(&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS current_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2250&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as currentreg&#xd;\n          &#xd;\n          LEFT OUTER JOIN                 &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS substitute_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 4284&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as substitutereg&#xd;\n          ON substitutereg.person_id =  currentreg.person_id&#xd;\n&#xd;\n          LEFT OUTER JOIN         &#xd;\n&#xd;\n          &#xd;\n          (select distinct o.person_id, max(o.obs_datetime) as maxdate, SUBSTRING(MAX(CONCAT(o.obs_datetime, o.value_coded)), 20) AS switch_regimen&#xd;\n          from obs o &#xd;\n          INNER JOIN patient_identifier ON patient_identifier.patient_id = o.person_id AND patient_identifier.preferred=1&#xd;\n          where o.concept_id = 2268&#xd;\n          AND o.voided = 0&#xd;\n          and o.obs_datetime &lt;= cast(:endDate as date)&#xd;\n          group by person_id) as switchreg&#xd;\n          ON switchreg.person_id =  currentreg.person_id&#xd;\n    )       &#xd;\n    &#xd;\n    )as regimen&#xd;\n    where regimen.ARV_regimen = 4703)Current_Reg&#xd;\nON Active_Patients.Id = Current_Reg.Id&#xd;\n&#xd;\nINNER JOIN&#xd;\n&#xd;\n-- Adherence&#xd;\n  (&#xd;\n    select o.person_id as Id, o.value_coded&#xd;\n    from obs o&#xd;\n    inner join&#xd;\n    (&#xd;\n     select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n     SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as adherence_hiv&#xd;\n     from obs oss&#xd;\n     where oss.concept_id = 2308 and oss.value_coded = 2305&#xd;\n     and oss.voided=0&#xd;\n     and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n     group by oss.person_id&#xd;\n    )latest&#xd;\n  on latest.person_id = o.person_id&#xd;\n  where o.concept_id = 2308 and o.value_coded = 2305&#xd;\n  and  o.obs_datetime = max_observation&#xd;\n  ) good_adherence&#xd;\non Active_Patients.Id = good_adherence.Id&#xd;\n))&#xd;\n&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-08-17 17:17:32',4,'2023-08-17 17:17:52',4,0,NULL,NULL,NULL,'a10f7cfb-6012-4c2a-8f4f-f9ef7cdd8310'),(2508,'Clients given 6d with good adherence','Clients given 6d with good adherence','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"e271c92e-f3e8-4218-a758-f2d91fd4173e\" retired=\"false\">\n  <name>Clients given 6d with good adherence</name>\n  <description>Clients given 6d with good adherence</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-08-17 15:18:32 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-08-17 15:19:41 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <typ