,'<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5de36ef7-faa8-422d-943d-fdd6ad3497a0\" retired=\"false\">\n  <name>ART clients with visits started</name>\n  <description>ART clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:40:58 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-04-25 10:31:31 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2537</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2)&#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id in (10,19)&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 18:10:58',4,'2024-04-25 16:01:31',4,0,NULL,NULL,NULL,'5de36ef7-faa8-422d-943d-fdd6ad3497a0'),(2538,'ART clients with visits consulted','ART clients with visits consulted','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"9340a449-ab16-4a98-8dcb-240635a9042d\" retired=\"false\">\n  <name>ART clients with visits consulted</name>\n  <description>ART clients with visits consulted</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:41:53 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-06 12:38:12 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2538</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2)&#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id and vt.visit_type_id in (10,19)&#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			and o.concept_id in (3843, 4276) and o.voided =0&#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n&#xd;\n		and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 18:11:53',4,'2024-02-06 18:08:12',4,0,NULL,NULL,NULL,'9340a449-ab16-4a98-8dcb-240635a9042d'),(2539,'Clients initiated on ART this month','Clients initiated on ART this month','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d3e386aa-99a9-4463-9e81-f663ca35cad2\" retired=\"false\">\n  <name>Clients initiated on ART this month</name>\n  <description>Clients initiated on ART this month</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:42:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-06 10:21:22 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2539</id>\n  <query> select distinct patient.patient_id AS Id&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 &#xd;\n&#xd;\n						AND CAST(o.value_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n						AND CAST(o.value_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							and os.voided = 0&#xd;\n							AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n							AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n						 )	&#xd;\n&#xd;\n						 and o.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 18:12:21',4,'2024-02-06 15:51:22',4,0,NULL,NULL,NULL,'d3e386aa-99a9-4463-9e81-f663ca35cad2'),(2540,'TB clients with visits started','TB clients with visits started','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"e6d2d518-2160-4fc8-84dc-a680c609b27f\" retired=\"false\">\n  <name>TB clients with visits started</name>\n  <description>TB clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:42:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:43:05 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2540</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2)&#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 13&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:42:50',4,'2023-09-21 14:43:05',4,0,NULL,NULL,NULL,'e6d2d518-2160-4fc8-84dc-a680c609b27f'),(2541,'TB clients with visits consulted','TB clients with visits consulted','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d205535e-f890-488a-a256-a69835a9a9d8\" retired=\"false\">\n  <name>TB clients with visits consulted</name>\n  <description>TB clients with visits consulted</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:44:18 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:45:05 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2541</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2) &#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			and o.concept_id in (4153,1158) and o.voided =0&#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 13&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:44:18',4,'2023-09-21 14:45:05',4,0,NULL,NULL,NULL,'d205535e-f890-488a-a256-a69835a9a9d8'),(2542,'HTS Clients Seen','HTS Clients Seen','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ce0fbba8-f81e-4f15-9da5-b341fd68b611\" retired=\"false\">\n  <name>HTS Clients Seen</name>\n  <description>HTS Clients Seen</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:45:02 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:45:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2542</id>\n  <query> select distinct o.person_id &#xd;\nfrom obs o inner join location l on o.location_id = l.location_id&#xd;\nwhere (o.location_id =:location or parent_location =:location)&#xd;\nand o.person_id in(&#xd;\nSELECT Id&#xd;\nFROM (&#xd;\n select distinct o.person_id as Id&#xd;\n                  from obs o&#xd;\n                  INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                  where o.concept_id = 4845 and o.value_coded = 4847&#xd;\n                   AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                   AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                  AND patient.voided = 0 AND o.voided = 0&#xd;\n                  ) as A&#xd;\n)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:45:02',4,'2023-09-21 14:45:39',4,0,NULL,NULL,NULL,'ce0fbba8-f81e-4f15-9da5-b341fd68b611'),(2543,'HTS clients with visits started','HTS clients with visits started','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"fe7fb845-5325-4d00-8cab-7041e6759f04\" retired=\"false\">\n  <name>HTS clients with visits started</name>\n  <description>HTS clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:45:52 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:46:05 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2543</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2)&#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 15&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:45:52',4,'2023-09-21 14:46:05',4,0,NULL,NULL,NULL,'fe7fb845-5325-4d00-8cab-7041e6759f04'),(2544,'1st Postnatal (PNC) Attendance','1st Postnatal (PNC) Attendance','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"290d3497-9608-4796-9826-1dc624696dbd\" retired=\"false\">\n  <name>1st Postnatal (PNC) Attendance</name>\n  <description>1st Postnatal (PNC) Attendance</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:46:47 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:47:10 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2544</id>\n  <query>select&#xd;\n       o.person_id&#xd;\nfrom obs o&#xd;\ninner join&#xd;\n		(&#xd;\n		 select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 4393 and oss.voided=0&#xd;\n		 and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n		 and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id&#xd;\n		)latest&#xd;\n	on latest.person_id = o.person_id&#xd;\n	where concept_id = 4393&#xd;\n	and  o.obs_datetime = max_observation</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:46:47',4,'2023-09-21 14:47:10',4,0,NULL,NULL,NULL,'290d3497-9608-4796-9826-1dc624696dbd'),(2545,'HTS clients with visits consulted','HTS clients with visits consulted','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"35051ec1-423c-4ede-a68f-88e94f2dc6a2\" retired=\"false\">\n  <name>HTS clients with visits consulted</name>\n  <description>HTS clients with visits consulted</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:47:27 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:47:54 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2545</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2) &#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			and o.concept_id = 4238 and o.voided =0&#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 15&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:47:27',4,'2023-09-21 14:47:54',4,0,NULL,NULL,NULL,'35051ec1-423c-4ede-a68f-88e94f2dc6a2'),(2546,'Self test Kits distributed','Self test Kits distributed','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"4ef31fd0-53cc-4296-adc1-1b74455e2a5f\" retired=\"false\">\n  <name>Self test Kits distributed</name>\n  <description>Self test Kits distributed</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:48:21 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:48:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2546</id>\n  <query>(select patient.patient_id AS Id&#xd;\n            from obs o&#xd;\n                -- HTS SELF TEST STRATEGY&#xd;\n                INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                 AND o.concept_id = 4833  and o.value_coded = 4834&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n              CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n              AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                 )&#xd;\n&#xd;\nUNION ALL&#xd;\n(select patient.patient_id AS Id&#xd;\n            from obs o&#xd;\n                -- HTS SELF TEST STRATEGY&#xd;\n                INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n                INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                AND o.concept_id = 4836  and o.value_coded in (4837, 4838, 4839)&#xd;\n                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&#xd;\n                 AND CAST(o.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n              CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n              AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n                 )</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:48:21',4,'2023-09-21 14:48:36',4,0,NULL,NULL,NULL,'4ef31fd0-53cc-4296-adc1-1b74455e2a5f'),(2547,'ANC clients with visits started','ANC clients with visits started','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"928922c7-633f-4cb0-9149-88ae7e50e237\" retired=\"false\">\n  <name>ANC clients with visits started</name>\n  <description>ANC clients with visits started</description>\n 