tion.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"dddf7e03-38fe-419f-81a4-625dabb0fd4e\" retired=\"false\">\n  <name>PNC clients with visits started</name>\n  <description>PNC clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:51:49 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:52:21 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2551</id>\n  <query>select distinct o.person_id&#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2)&#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 17&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:51:49',4,'2023-09-21 14:52:21',4,0,NULL,NULL,NULL,'dddf7e03-38fe-419f-81a4-625dabb0fd4e'),(2552,'Family Planning Clients seen','Family Planning Clients seen','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"287d14af-8d53-48d0-8cf4-47f141b0e9ea\" retired=\"false\">\n  <name>Family Planning Clients seen</name>\n  <description>Family Planning Clients seen</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:52:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:52:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2552</id>\n  <query>select&#xd;\n       o.person_id&#xd;\nfrom obs o&#xd;\ninner join&#xd;\n		(&#xd;\n		 select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n		 SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n		 from obs oss&#xd;\n		 where oss.concept_id = 4557 and oss.voided=0&#xd;\n		 and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n		 and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n		 group by oss.person_id&#xd;\n		)latest&#xd;\n	on latest.person_id = o.person_id&#xd;\n	where concept_id = 4557&#xd;\n	and  o.obs_datetime = max_observation</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 14:52:28',4,'2023-09-21 14:52:43',4,0,NULL,NULL,NULL,'287d14af-8d53-48d0-8cf4-47f141b0e9ea'),(2553,'PNC clients with visits consulted','PNC clients with visits consulted','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"bf6795b4-6d7f-49bd-aff7-53781f102898\" retired=\"false\">\n  <name>PNC clients with visits consulted</name>\n  <description>PNC clients with visits consulted</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 12:52:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 12:53:03 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</re