r>\n  </parameters>\n  <id>2570</id>\n  <query>select distinct o.person_id &#xd;\nfrom obs o &#xd;\nwhere o.person_id in&#xd;\n	(&#xd;\n	  SELECT DISTINCT p.person_id as id&#xd;\n		FROM visit v&#xd;\n			JOIN person_name pn on v.patient_id = pn.person_id and pn.voided=0&#xd;\n			JOIN person p on p.person_id = v.patient_id&#xd;\n			JOIN encounter en on en.visit_id = v.visit_id and en.voided=0 and en.encounter_type in (1,2) &#xd;\n			JOIN visit_type vt on vt.visit_type_id = vt.visit_type_id &#xd;\n			JOIN obs o on o.encounter_id=en.encounter_id &#xd;\n			and o.concept_id = 4511 and o.voided =0&#xd;\n			JOIN location l on v.location_id = l.location_id and l.retired=0&#xd;\n		WHERE CAST(en.encounter_datetime AS DATE) &gt;= CAST(:startDate AS DATE) and CAST(en.encounter_datetime AS DATE)&lt;= CAST(:endDate AS DATE)&#xd;\n		and v.visit_type_id = 21&#xd;\n        and (v.location_id = :location or parent_location = :location)&#xd;\n        &#xd;\n	)</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 15:02:56',4,'2023-09-21 15:03:08',4,0,NULL,NULL,NULL,'cf21c6a3-0a19-44c7-b2c7-e14246d7bc96'),(2571,'Under5 Clients Seen','Under5 Clients Seen','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"d8654256-acae-40b0-a3c2-feafeb2f36ad\" retired=\"false\">\n  <name>Under5 Clients Seen</name>\n  <description>Under5 Clients Seen</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:03:36 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:05:20 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</typ