anged id=\"4\">2023-09-21 13:31:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2590</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"ae2b5eee-422b-4307-a985-7bd763147582\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-21 15:28:28',4,'2023-09-21 15:31:36',4,0,NULL,NULL,NULL,'3a2857b0-1d9c-4f7d-95e9-abcba540935d'),(2591,'Under 5 clients with visits started','Under 5 clients with visits started','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"f62e6fdd-a64b-4619-925c-d86fc3987060\" retired=\"false\">\n  <name>Under 5 clients with visits started</name>\n  <description>Under 5 clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:30:05 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:30:36 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2591</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"ae2b5eee-422b-4307-a985-7bd763147582\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-21 15:30:05',4,'2023-09-21 15:30:36',4,0,NULL,NULL,NULL,'f62e6fdd-a64b-4619-925c-d86fc3987060'),(2592,'Clients current on ART','Clients current on ART','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"ad403c3b-d759-44ab-8965-252ca6127ce7\" retired=\"false\">\n  <name>Clients current on ART</name>\n  <description>Clients current on ART</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:31:58 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:35:41 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2592</id>\n  <query>    (SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS NEWLY INITIATED ON ART&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n						 AND (o.concept_id = 2249 &#xd;\n&#xd;\n						AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n						AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )&#xd;\n						 AND patient.voided = 0 AND o.voided = 0&#xd;\n						 AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							and os.voided = 0&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n&#xd;\n						 and o.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS Newly_Initiated_ART_Clients&#xd;\nORDER BY Newly_Initiated_ART_Clients.patientName)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n(SELECT Id&#xd;\nFROM (&#xd;\n&#xd;\nselect distinct patient.patient_id AS Id,&#xd;\n                                   patient_identifier.identifier AS patientIdentifier,&#xd;\n                                   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n                                   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n                                   person.gender AS Gender,&#xd;\n                                   observed_age_group.name AS age_group,&#xd;\n								   observed_age_group.sort_order AS sort_order&#xd;\n        from obs o&#xd;\n								-- CLIENTS SEEN FOR ART&#xd;\n                                 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n                                 AND (o.concept_id = 3843 AND o.value_coded = 3841 OR o.value_coded = 3842)&#xd;\n								 AND MONTH(o.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n								 AND YEAR(o.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n                                 AND patient.voided = 0 AND o.voided = 0&#xd;\n                                 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                                 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n                                 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n								 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n									  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n									  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n           WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;&#xd;\n&#xd;\n) AS Clients_Seen&#xd;\n&#xd;\nWHERE Clients_Seen.Id not in (&#xd;\n		select distinct patient.patient_id AS Id&#xd;\n		from obs o&#xd;\n				-- CLIENTS INITIATED ON ART&#xd;\n				 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n				 AND (o.concept_id = 2249 &#xd;\n											AND MONTH(o.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n											AND YEAR(o.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						)		&#xd;\n				 		AND patient.voided = 0 AND o.voided = 0&#xd;\n				 		AND o.person_id not in (&#xd;\n							select distinct os.person_id from obs os&#xd;\n							where os.concept_id = 3634 &#xd;\n							AND os.value_coded = 2095 &#xd;\n							and os.voided = 0&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n						 )	&#xd;\n&#xd;\n							)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752 and os.voided = 0&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266 and os.voided = 0&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)					&#xd;\n		)&#xd;\n&#xd;\nAND Clients_Seen.Id not in &#xd;\n					(&#xd;\n						select distinct(o.person_id)&#xd;\n						from obs o&#xd;\n						where o.person_id in (&#xd;\n								-- FOLLOW UPS&#xd;\n											select firstquery.person_id&#xd;\n											from&#xd;\n											(&#xd;\n											select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n											from obs oss&#xd;\n														where oss.voided=0 &#xd;\n														and oss.concept_id=3752 &#xd;\n														and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n														group by oss.person_id) firstquery&#xd;\n											inner join (&#xd;\n														select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n														from obs os&#xd;\n														where concept_id = 3752 and os.voided = 0&#xd;\n														and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n														group by os.person_id&#xd;\n														having last_ap &lt; 0&#xd;\n											) secondquery&#xd;\n											on firstquery.person_id = secondquery.person_id&#xd;\n						)&#xd;\n						and o.person_id in (&#xd;\n								-- Death&#xd;\n											select distinct p.person_id&#xd;\n											from person p&#xd;\n											where dead = 1&#xd;\n											and death_date &lt;= CAST(:endDate AS DATE)	&#xd;\n											and voided = 0	&#xd;\n						)&#xd;\n					)&#xd;\nAND Clients_Seen.Id not in (&#xd;\n					-- Visitors&#xd;\n							select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id = 5416 and oss.value_coded =1 and oss.voided=0&#xd;\n										and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and  o.obs_datetime = max_observation&#xd;\n						)&#xd;\n&#xd;\nORDER BY Clients_Seen.patientName)&#xd;\n&#xd;\nUNION&#xd;\n&#xd;\n&#xd;\n-- INCLUDE MISSED APPOINTMENTS WITHIN 28 DAYS ACCORDING TO THE NEW PEPFAR GUIDELINE&#xd;\n(SELECT Id&#xd;\nFROM&#xd;\n                 (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n						-- CLIENTS WHO MISSED APPOINTMENTS &lt; 28 DAYS&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &lt; cast(:endDate as date)&#xd;\n								and DATEDIFF(CAST(:endDate AS DATE),latest_follow_up) &lt;= 28&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							and os.voided = 0&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							and os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							&#xd;\n									-- TOUTS&#xd;\n									select tout_clients.person_id&#xd;\n                                from&#xd;\n                                (select B.person_id, B.obs_group_id, B.obs_datetime AS latest_consultation&#xd;\n                                    from obs B&#xd;\n                                    inner join&#xd;\n                                    (select person_id, max(obs_datetime), SUBSTRING(max(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n                                    from obs where concept_id = 2403&#xd;\n                                    and obs_datetime &lt;= cast(:endDate as date)&#xd;\n                                    and voided = 0&#xd;\n                                    group by person_id) as A&#xd;\n                                    on A.observation_id = B.obs_group_id&#xd;\n                                    where concept_id = 2398&#xd;\n                                    and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0&#xd;\n                                    group by B.person_id&#xd;\n                                ) as tout_clients&#xd;\n                                where tout_clients.latest_consultation &lt; cast(:endDate as date)&#xd;\n										&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n									&#xd;\n						 )&#xd;\n&#xd;\n		and active_clients.person_id not in(&#xd;\n									-- Visitors&#xd;\n							select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id = 5416 and oss.value_coded =1 and oss.voided=0&#xd;\n										and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and  o.obs_datetime = max_observation&#xd;\n							)				 &#xd;\n						 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS TwentyEightDayDefaulters&#xd;\n				   order by TwentyEightDayDefaulters.patientName)&#xd;\n	&#xd;\n				   &#xd;\nUNION&#xd;\n&#xd;\n(SELECT  Id&#xd;\n	FROM&#xd;\n                (select distinct patient.patient_id AS Id,&#xd;\n									   patient_identifier.identifier AS patientIdentifier,&#xd;\n									   concat(person_name.given_name, &apos; &apos;, person_name.family_name) AS patientName,&#xd;\n									   floor(datediff(CAST(:endDate AS DATE), person.birthdate)/365) AS Age,&#xd;\n									   person.gender AS Gender,&#xd;\n									   observed_age_group.name AS age_group,&#xd;\n									   observed_age_group.sort_order AS sort_order&#xd;\n&#xd;\n                from obs o&#xd;\n					&#xd;\n						 INNER JOIN patient ON o.person_id = patient.patient_id&#xd;\n						 AND o.person_id in (&#xd;\n						 -- begin&#xd;\n						select active_clients.person_id-- , active_clients.latest_follow_up&#xd;\n								from&#xd;\n								(select B.person_id, B.obs_group_id, B.value_datetime AS latest_follow_up&#xd;\n									from obs B&#xd;\n									inner join &#xd;\n									(select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n									from obs where concept_id = 3753&#xd;\n									and obs_datetime &lt;= cast(:endDate as date)&#xd;\n									and voided = 0&#xd;\n									group by person_id) as A&#xd;\n									on A.observation_id = B.obs_group_id&#xd;\n									where concept_id = 3752&#xd;\n									and A.observation_id = B.obs_group_id&#xd;\n                                    and voided = 0	&#xd;\n									group by B.person_id	&#xd;\n								) as active_clients&#xd;\n								where active_clients.latest_follow_up &gt;= cast(:endDate as date)&#xd;\n				&#xd;\n				&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where (os.concept_id = 3843 AND os.value_coded = 3841 OR os.value_coded = 3842)&#xd;\n							AND MONTH(os.obs_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.obs_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n						&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct os.person_id&#xd;\n							from obs os&#xd;\n							where concept_id = 2249&#xd;\n							AND MONTH(os.value_datetime) = MONTH(CAST(:endDate AS DATE)) &#xd;\n							AND YEAR(os.value_datetime) = YEAR(CAST(:endDate AS DATE))&#xd;\n							AND os.voided = 0&#xd;\n							)&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n							select distinct(o.person_id)&#xd;\n							from obs o&#xd;\n							where o.person_id in (&#xd;\n									-- FOLLOW UPS&#xd;\n										select firstquery.person_id&#xd;\n										from&#xd;\n										(&#xd;\n										select oss.person_id, SUBSTRING(MAX(CONCAT(oss.value_datetime, oss.obs_id)), 20) AS observation_id, CAST(max(oss.value_datetime) AS DATE) as latest_followup_obs&#xd;\n										from obs oss&#xd;\n													where oss.voided=0 &#xd;\n													and oss.concept_id=3752 &#xd;\n													and CAST(oss.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													and CAST(oss.obs_datetime AS DATE) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -13 MONTH)&#xd;\n													group by oss.person_id) firstquery&#xd;\n										inner join (&#xd;\n													select os.person_id,datediff(CAST(max(os.value_datetime) AS DATE), CAST(:endDate AS DATE)) as last_ap&#xd;\n													from obs os&#xd;\n													where concept_id = 3752 and os.voided = 0&#xd;\n													and CAST(os.obs_datetime AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n													group by os.person_id&#xd;\n													having last_ap &lt; 0&#xd;\n										) secondquery&#xd;\n										on firstquery.person_id = secondquery.person_id&#xd;\n							) and o.person_id in (&#xd;\n									-- TOUTS&#xd;\n									select distinct(person_id)&#xd;\n									from&#xd;\n									(&#xd;\n										select os.person_id, CAST(max(os.value_datetime) AS DATE) as latest_transferout&#xd;\n										from obs os&#xd;\n										where os.concept_id=2266 and os.voided = 0&#xd;\n										group by os.person_id&#xd;\n										having latest_transferout &lt;= CAST(:endDate AS DATE)&#xd;\n									) as TOUTS&#xd;\n							)			&#xd;\n										)&#xd;\n			&#xd;\n&#xd;\n		and active_clients.person_id not in (&#xd;\n									select person_id &#xd;\n									from person &#xd;\n									where death_date &lt;= cast(:endDate as date)&#xd;\n									and dead = 1 and voided = 0&#xd;\n						 )&#xd;\n		and active_clients.person_id not in (&#xd;\n									-- Visitors&#xd;\n							select o.person_id&#xd;\n								from obs o&#xd;\n								inner join&#xd;\n										(&#xd;\n										select oss.person_id, MAX(oss.obs_datetime) as max_observation,&#xd;\n										SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n										from obs oss&#xd;\n										where oss.concept_id = 5416 and oss.value_coded =1 and oss.voided=0&#xd;\n										and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n										and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n										group by oss.person_id&#xd;\n										)latest&#xd;\n									on latest.person_id = o.person_id&#xd;\n									where concept_id = 5416&#xd;\n									and  o.obs_datetime = max_observation&#xd;\n						 )&#xd;\n						 )&#xd;\n						 -- end&#xd;\n						 &#xd;\n						 INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n						 INNER JOIN person_name ON person.person_id = person_name.person_id AND person_name.preferred = 1&#xd;\n						 INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n						 INNER JOIN reporting_age_group AS observed_age_group ON&#xd;\n						  CAST(:endDate AS DATE) BETWEEN (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.min_years YEAR), INTERVAL observed_age_group.min_days DAY))&#xd;\n						  AND (DATE_ADD(DATE_ADD(person.birthdate, INTERVAL observed_age_group.max_years YEAR), INTERVAL observed_age_group.max_days DAY))&#xd;\n                   WHERE observed_age_group.report_group_name = &apos;Modified_Ages&apos;) AS Seen_Previous_ART_Clients&#xd;\nORDER BY Seen_Previous_ART_Clients.patientName)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-21 15:31:58',4,'2023-09-21 15:35:41',4,0,NULL,NULL,NULL,'ad403c3b-d759-44ab-8965-252ca6127ce7'),(2593,'Cervical Cancer Screening clients with visits started','Cervical Cancer Screening clients with visits started','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"c7967fcd-a8b7-41d4-b540-364a60a59621\" retired=\"false\">\n  <name>Cervical Cancer Screening clients with visits started</name>\n  <description>Cervical Cancer Screening clients with visits started</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:32:10 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:32:43 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2593</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"4f7cc18d-1104-4427-b582-f73b99bd0837\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-21 15:32:10',4,'2023-09-21 15:32:43',4,0,NULL,NULL,NULL,'c7967fcd-a8b7-41d4-b540-364a60a59621'),(2594,'Cervical Cancer Screening clients with visits consulted','Cervical Cancer Screening clients with visits consulted','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"b526566e-555d-40c6-88d4-0b89242b1dde\" retired=\"false\">\n  <name>Cervical Cancer Screening clients with visits consulted</name>\n  <description>Cervical Cancer Screening clients with visits consulted</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:33:06 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:34:03 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2594</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"cf21c6a3-0a19-44c7-b2c7-e14246d7bc96\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-21 15:33:06',4,'2023-09-21 15:34:03',4,0,NULL,NULL,NULL,'b526566e-555d-40c6-88d4-0b89242b1dde'),(2595,'Clients current on ART','Clients current on ART','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"1db1c64d-177f-4ecc-b1d7-c9fd2b029eff\" retired=\"false\">\n  <name>Clients current on ART</name>\n  <description>Clients current on ART</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-21 13:36:28 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-21 13:37:08 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2595</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"ad403c3b-d759-44ab-8965-252ca6127ce7\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-21 15:36:28',4,'2023-09-21 15:37:08',4,0,NULL,NULL,NULL,'1db1c64d-177f-4ecc-b1d7-c9fd2b029eff'),(2596,'Clients with LAB tests sent','Clients with LAB tests sent','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f06f1ccb-c048-44d3-8037-35f8660a6b95\" retired=\"false\">\n  <name>Clients with LAB tests sent</name>\n  <description>Clients with LAB tests sent</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-22 08:35:11 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-22 08:35:51 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2596</id>\n  <query>select distinct patient.patient_id AS Id&#xd;\n            from orders o&#xd;\n                    INNER JOIN patient ON o.patient_id = patient.patient_id &#xd;\n                    INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n                    INNER JOIN person_name ON person.person_id = person_name.person_id&#xd;\n                    INNER JOIN patient_identifier ON patient_identifier.patient_id = person.person_id AND patient_identifier.identifier_type = 3 AND patient_identifier.preferred=1&#xd;\n                    AND o.concept_id = 5484&#xd;\n                    AND CAST(o.date_created AS DATE)&gt;= CAST(:startDate AS DATE)&#xd;\n					AND CAST(o.date_created AS DATE) &lt;= CAST(:endDate AS DATE)&#xd;\n                    LEFT OUTER JOIN patient_identifier p ON p.patient_id = person.person_id AND p.identifier_type = 5</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-22 08:35:11',4,'2023-09-22 08:35:51',4,0,NULL,NULL,NULL,'f06f1ccb-c048-44d3-8037-35f8660a6b95'),(2597,'Clients with LAB tests sent','Clients with LAB tests sent','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"c29cff5d-5919-4b60-8ab7-c6d4c7ea01da\" retired=\"false\">\n  <name>Clients with LAB tests sent</name>\n  <description>Clients with LAB tests sent</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-22 08:36:30 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-22 08:38:26 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2597</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"f06f1ccb-c048-44d3-8037-35f8660a6b95\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-22 08:36:30',4,'2023-09-22 08:38:26',4,0,NULL,NULL,NULL,'c29cff5d-5919-4b60-8ab7-c6d4c7ea01da'),(2598,'Clients with LAB tests received','Clients with LAB tests received','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6939902b-1909-4f24-b71d-da60ab1d131b\" retired=\"false\">\n  <name>Clients with LAB tests received</name>\n  <description>Clients with LAB tests received</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-22 08:39:02 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-06 09:57:28 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2598</id>\n  <query>Select pId&#xd;\n    From&#xd;\n      (&#xd;\n        select oss.person_id as pId, concat(oss.value_numeric, &quot; &quot;, &quot;copies/ml&quot;)  as Results&#xd;\n            from obs oss&#xd;\n            where oss.concept_id = 5485&#xd;\n            and oss.voided=0&#xd;\n            and cast(oss.obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\n			and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n            group by oss.person_id&#xd;\n&#xd;\n    UNION&#xd;\n&#xd;\n    select oss.person_id as pId, &quot;LDL&quot;  as Results&#xd;\n            from obs oss&#xd;\n            where oss.concept_id = 5489&#xd;\n            and oss.voided=0&#xd;\n            and cast(oss.obs_datetime as date)  &gt;= cast(:startDate as date)&#xd;\n			and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n            group by oss.person_id&#xd;\n&#xd;\n      ) As received_results</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2023-09-22 14:09:02',4,'2024-02-06 15:27:28',4,0,NULL,NULL,NULL,'6939902b-1909-4f24-b71d-da60ab1d131b'),(2599,'Clients with LAB tests received','Clients with LAB tests received','org.openmrs.module.reporting.indicator.Indicator','org.openmrs.module.reporting.indicator.CohortIndicator','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.indicator.CohortIndicator id=\"1\" uuid=\"e47a29f8-b851-480f-9812-e54da393fdb9\" retired=\"false\">\n  <name>Clients with LAB tests received</name>\n  <description>Clients with LAB tests received</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2023-09-22 08:39:53 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2023-09-22 08:42:39 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2599</id>\n  <type>COUNT</type>\n  <cohortDefinition id=\"9\">\n    <parameterizable class=\"org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition\" id=\"10\" uuid=\"6939902b-1909-4f24-b71d-da60ab1d131b\"/>\n    <parameterMappings id=\"11\">\n      <entry>\n        <string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2023-09-22 08:39:53',4,'2023-09-22 08:42:39',4,0,NULL,NULL,NULL,'e47a29f8-b851-480f-9812-e54da393fdb9'),(2600,'Contacts  of TB Patients','Contacts of TB Patients','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"f74fefb2-b6d4-4c26-b214-fdb965aeb103\" retired=\"false\">\n  <name>Contacts  of TB Patients</name>\n  <description>Contacts of TB Patients</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 09:43:12 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 10:34:55 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2600</id>\n  <query>select contact.person_id &#xd;\n	from&#xd;\n		(select B.person_id, B.obs_datetime&#xd;\n			from obs B&#xd;\n			inner join &#xd;\n				(select person_id, max(obs_datetime) as latest_consultation&#xd;\n					from obs where concept_id = 5926&#xd;\n					and obs_datetime &lt;= cast(:endDate as date)&#xd;\n					and voided = 0&#xd;\n					group by person_id) as A&#xd;\n			on A.latest_consultation = B.obs_datetime&#xd;\n			where concept_id = 5962 and value_coded = 2146&#xd;\n			and A.latest_consultation = B.obs_datetime&#xd;\n            and voided = 0	&#xd;\n			group by B.person_id&#xd;\n		) as contact</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-02-27 15:13:12',4,'2024-02-27 16:04:55',4,0,NULL,NULL,NULL,'f74fefb2-b6d4-4c26-b214-fdb965aeb103'),(2601,'Contacts of TB Patients screened for TB','Contacts of TB Patients screened for TB','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"6733708e-c472-4c84-89a2-13e0938a8360\" retired=\"false\">\n  <name>Contacts of TB Patients screened for TB</name>\n  <description>Contacts of TB Patients screened for TB</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 10:35:41 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 10:36:09 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2601</id>\n  <query>select contact.person_id&#xd;\n	from&#xd;\n		(select B.person_id&#xd;\n			from obs B&#xd;\n			inner join &#xd;\n				(select person_id, max(obs_datetime) as latest_consultation&#xd;\n					from obs where concept_id = 5904&#xd;\n					and obs_datetime &lt;= cast(:endDate as date)&#xd;\n					and voided = 0&#xd;\n					group by person_id) as A&#xd;\n			on A.latest_consultation = B.obs_datetime&#xd;\n			where concept_id = 5962 and value_coded = 2146&#xd;\n			and A.latest_consultation = B.obs_datetime&#xd;\n            and voided = 0	&#xd;\n			group by B.person_id&#xd;\n		) as contact</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-02-27 16:05:41',4,'2024-02-27 16:06:09',4,0,NULL,NULL,NULL,'6733708e-c472-4c84-89a2-13e0938a8360'),(2602,'Presumptive TB contacts with bacteriologic result(s)','Presumptive TB contacts with bacteriologic test result (s)','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"5c82cebb-b76f-4acd-a416-752578f29546\" retired=\"false\">\n  <name>Presumptive TB contacts with bacteriologic result(s)</name>\n  <description>Presumptive TB contacts with bacteriologic test result (s)</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 14:08:31 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 14:16:55 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2602</id>\n  <query>&#xd;\n  select distinct Id&#xd;\n    FROM&#xd;\n    (&#xd;\n        -- Bacteriologically confirmed Genotypic test results and Phenotypic test results&#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id in (3814, 3815) &#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and cast(o.obs_datetime as date) &lt;= CAST(:endDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB not Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (5954,5433,5955,5956,5959)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840,5957) &#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n&#xd;\n        ) As Pulmonary_Bacteriologic</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-02-27 19:38:31',4,'2024-02-27 19:46:55',4,0,NULL,NULL,NULL,'5c82cebb-b76f-4acd-a416-752578f29546'),(2603,'Contacts of TB Patients who are positive to a bacteriologic test ','Contacts of TB Patients who are positive to a bacteriologic test ','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"c632d1d1-ddd1-40ca-bdfd-8df133511db3\" retired=\"false\">\n  <name>Contacts of TB Patients who are positive to a bacteriologic test </name>\n  <description>Contacts of TB Patients who are positive to a bacteriologic test </description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 14:17:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 17:56:03 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2603</id>\n  <query> select distinct Id&#xd;\n    FROM&#xd;\n    (&#xd;\n        -- Bacteriologically results &#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id = 5953 &#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and cast(o.obs_datetime as date) &lt;= CAST(:endDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (5954,5433,5955,5956,5959)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840,5957) &#xd;\n                                        and o.value_coded in (3816,3817,3718, 1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n&#xd;\n        ) As Pulmonary_Bacteriologic</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-02-27 19:47:57',4,'2024-02-27 23:26:03',4,0,NULL,NULL,NULL,'c632d1d1-ddd1-40ca-bdfd-8df133511db3'),(2604,'Contacts of TB Patients who are positive bacteriologic test & started TB treatment','Contacts of TB Patients who are positive to a bacteriologic test and started on TB treatment','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"d2360af2-f13b-4b10-978f-5f230a0a83d7\" retired=\"false\">\n  <name>Contacts of TB Patients who are positive bacteriologic test &amp; started TB treatment</name>\n  <description>Contacts of TB Patients who are positive to a bacteriologic test and started on TB treatment</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 18:19:38 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 18:20:06 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2604</id>\n  <query>select distinct Id&#xd;\n    FROM&#xd;\n    (&#xd;\n        -- Bacteriologically results &#xd;\n          select distinct person_id as Id&#xd;\n            From obs o &#xd;\n            where o.concept_id = 5953 &#xd;\n            and cast(o.obs_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and cast(o.obs_datetime as date) &lt;= CAST(:endDate AS DATE)&#xd;\n            and o.voided = 0&#xd;\n        &#xd;\n        -- MTB Detected&#xd;\n        and o.person_id in&#xd;\n                                (&#xd;\n                                    select distinct o.person_id&#xd;\n                                    from obs o&#xd;\n                                    inner join&#xd;\n                                            (&#xd;\n                                            select oss.person_id as Id, MAX(oss.obs_datetime) as max_observation,&#xd;\n                                            SUBSTRING(MAX(CONCAT(oss.obs_datetime, oss.value_coded)), 20) as examination_timing&#xd;\n                                            from obs oss&#xd;\n                                            where oss.concept_id in (5954,5433,5955,5956,5959)&#xd;\n                                            and cast(oss.obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\n                                            group by oss.person_id&#xd;\n                                            )latest&#xd;\n                                        on latest.Id = o.person_id&#xd;\n                                        where o.concept_id in (3787,3805,3840,5957) &#xd;\n                                        and o.value_coded in (3816,3817,3718, 1738, 3828,3829,3830, 3831, 3832,3833,3834, 3835,3836, 3837,3838,3839)&#xd;\n                                        and o.voided=0&#xd;\n                                        and cast(o.obs_datetime as date) = cast(max_observation as date)&#xd;\n                                    &#xd;\n                                )&#xd;\n&#xd;\n        ) As Pulmonary_Bacteriologic&#xd;\n inner join (&#xd;\n            select ob.person_id as pId&#xd;\n            FROM obs ob&#xd;\n            -- Pulmonary TB&#xd;\n            where ob.concept_id = 2237&#xd;\n            AND cast(ob.value_datetime as date) &gt;= CAST(:startDate AS DATE)&#xd;\n            and cast(ob.value_datetime as date) &lt;= CAST(:endDate AS DATE)&#xd;\n            and ob.voided = 0&#xd;\n            ) as Pulmonary&#xd;\n        on Pulmonary_Bacteriologic.Id = Pulmonary.pId</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-02-27 23:49:38',4,'2024-02-27 23:50:06',4,0,NULL,NULL,NULL,'d2360af2-f13b-4b10-978f-5f230a0a83d7'),(2605,'Contacts of TB patients - Presumptive','Contacts of TB patients who have one or more signs and symptoms of TB (Presumptive)','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"17e19631-0322-48e3-8a42-352880f64b8f\" retired=\"false\">\n  <name>Contacts of TB patients - Presumptive</name>\n  <description>Contacts of TB patients who have one or more signs and symptoms of TB (Presumptive)</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-02-27 18:31:50 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-02-27 18:32:42 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <requir