.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"123\">\n      <name>2qMales</name>\n      <label>Clients active on ART given 2q-Males</label>\n      <indicator reference=\"121\"/>\n      <dimensionOptions reference=\"20\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"124\">\n      <name>2rFemales</name>\n      <label>Clients active on ART given 2r-Females</label>\n      <indicator id=\"125\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.CohortIndicator\" id=\"126\" uuid=\"7644efb5-028c-48df-ad61-d5e9770d135e\"/>\n        <parameterMappings reference=\"17\"/>\n      </indicator>\n      <dimensionOptions reference=\"18\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"127\">\n      <name>2rMales</name>\n      <label>Clients active on ART given 2r-Males</label>\n      <indicator reference=\"125\"/>\n      <dimensionOptions reference=\"20\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"128\">\n      <name>2sFemales</name>\n      <label>Clients active on ART given 2s-Females</label>\n      <indicator id=\"129\">\n        <parameterizable class=\"org.openmrs.mo