g.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"151\">\n      <name>3eMales</name>\n      <label>Clients active on ART given 3e-Males</label>\n      <indicator reference=\"149\"/>\n      <dimensionOptions reference=\"20\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"152\">\n      <name>3fFemales</name>\n      <label>Clients active on ART given 3f-Females</label>\n      <indicator id=\"153\">\n        <parameterizable class=\"org.openmrs.module.reporting.indicator.CohortIndicator\" id=\"154\" uuid=\"4011ecc2-eb97-42b4-b141-e150c098402f\"/>\n        <parameterMappings reference=\"17\"/>\n      </indicator>\n      <dimensionOptions reference=\"18\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"155\">\n      <name>3fMales</name>\n      <label>Clients active on ART given 3f-Males</label>\n      <indicator reference=\"153\"/>\n      <dimensionOptions reference=\"20\"/>\n      <outer-class reference=\"1\"/>\n    </org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn>\n    <org.openmrs.module.reporting.dataset.definition.CohortIndicatorDataSetDefinition_-CohortIndicatorAndDimensionColumn id=\"156\">\n      <name>3gFemales</name>\n      <label>Clients active on ART given 3g-Females</label>\n      <indicator id=\"157\">\n        <parameterizable class=\"org.openmrs.m