nmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2819</id>\n  <query>SELECT Id&#xd;\nFROM&#xd;\n(select B.person_id as Id, B.obs_group_id,B. encounter_id&#xd;\n        from obs B&#xd;\n        inner join &#xd;\n        (select person_id, max(obs_datetime), SUBSTRING(MAX(CONCAT(obs_datetime, obs_id)), 20) AS observation_id&#xd;\n        from obs where concept_id = 4663 -- ANC form&#xd;\n        and obs_datetime &lt;= cast(:endDate as date)&#xd;\n        and voided = 0&#xd;\n        group by person_id) as A&#xd;\n        on A.observation_id = B.obs_group_id&#xd;\n        where B.concept_id = 4658 and B.value_coded = 4659 -- 1st ANC&#xd;\n		and CAST(B.obs_datetime as date) &gt;= CAST(:startDate as date)&#xd;\n		and CAST(B.obs_datetime as date) &lt;= CAST(:endDate as date)&#xd;\n        and A.observation_id = B.obs_group_id&#xd;\n        and voided = 0	&#xd;\n        group by B.person_id&#xd;\n)First_ANC_Visits&#xd;\n&#xd;\ninner join&#xd;\n-- first trimester&#xd;\n(&#xd;\n select o.person_id, o.encounter_id&#xd;\n from obs o&#xd;\n where o.concept_id = 2423 and o.voided = 0&#xd;\n and o.value_numeric &lt;= 12 -- first trimester&#xd;\n and CAST(o.obs_datetime AS DATE) &gt;= CAST(:startDate AS DATE)&