<string>endDate</string>\n        <string>${endDate}</string>\n      </entry>\n      <entry>\n        <string>location</string>\n        <string>${location}</string>\n      </entry>\n      <entry>\n        <string>startDate</string>\n        <string>${startDate}</string>\n      </entry>\n    </parameterMappings>\n  </cohortDefinition>\n</org.openmrs.module.reporting.indicator.CohortIndicator>','2024-06-28 19:28:37',4,'2024-06-28 19:30:02',4,0,NULL,NULL,NULL,'5428fb98-d094-4316-8d09-3e927a7b64a5'),(2901,'ANC Clients with a baseline Viral Load of <1000 copies','ANC Clients with a baseline Viral Load of <1000 copies','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"94b03818-6ff2-4b08-a66a-9f71c397e029\" retired=\"false\">\n  <name>ANC Clients with a baseline Viral Load of &lt;1000 copies</name>\n  <description>ANC Clients with a baseline Viral Load of &lt;1000 copies</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4-adec-0800271c1b75\"/>\n  <dateCreated id=\"3\">2024-06-28 14:04:57 UTC</dateCreated>\n  <changedBy reference=\"2\"/>\n  <dateChanged id=\"4\">2024-08-06 13:28:06 UTC</dateChanged>\n  <parameters id=\"5\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>startDate</name>\n      <label>Start Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"7\">\n      <name>endDate</name>\n      <label>End Date</label>\n      <type>java.util.Date</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"8\">\n      <name>location</name>\n      <label>Location</label>\n      <type>org.openmrs.Location</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <id>2901</id>\n  <query>select person_id&#xd;\nfrom obs &#xd;\nwhere concept_id = 4295 -- ANC Register&#xd;\nand cast(obs_datetime as date) &gt;= cast(:startDate as date)&#xd;\nand cast(obs_datetime as date) &lt;= cast(:endDate as date)&#xd;\nand voided = 0&#xd;\nand person_id in (&#xd;\n        select o.person_id&#xd;\n        from obs o &#xd;\n        where o.concept_id = 5489 and o.voided=0 -- DISA VL results low value &#xd;\n        and cast(o.obs_datetime as date) &lt;= CAST(:endDate as date)&#xd;\n        and cast(o.obs_datetime as date) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n&#xd;\n        UNION&#xd;\n&#xd;\n        select o.person_id&#xd;\n        from obs o &#xd;\n        where o.concept_id = 5485 and o.voided=0 -- DISA VL value numeric &#xd;\n        and cast(o.obs_datetime as date) &lt;= CAST(:endDate as date)&#xd;\n        and cast(o.obs_datetime as date) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n        and o.value_numeric &lt; 1000&#xd;\n&#xd;\n        UNION&#xd;\n&#xd;\n        select o.person_id&#xd;\n        from obs o &#xd;\n        where o.concept_id = 4266  and o.value_coded = 4263&#xd;\n        and o.voided=0 -- Undetectable VL&#xd;\n        and cast(o.obs_datetime as date) &lt;= CAST(:endDate as date)&#xd;\n        and cast(o.obs_datetime as date) &gt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -3 MONTH)&#xd;\n        )&#xd;\nand person_id in (&#xd;\n    -- First Visit&#xd;\n      select B.person_id&#xd;\n        from obs B&#xd;\n        where B.concept_id = 4658 and B.value_coded = 4659 -- First ANC&#xd;\n		and CAST(B.obs_datetime as date) &gt;= CAST(:startDate as date)&#xd;\n		and CAST(B.obs_datetime as date) &lt;= CAST(:endDate as date)&#xd;\n        and voided = 0	&#xd;\n       