atient.voided = 0 AND o.voided = 0&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              where o.concept_id = 2237 and o.voided = 0&#xd;\n              and o.value_datetime &gt;= DATE_ADD(CAST(:startDate AS DATE), INTERVAL -12 MONTH) &#xd;\n              and o.value_datetime &lt;= DATE_ADD(CAST(:endDate AS DATE), INTERVAL -12 MONTH)&#xd;\n              group by o.person_id&#xd;\n                )&#xd;\n            -- Female&#xd;\n            and o.person_id in (&#xd;\n              select o.person_id&#xd;\n              from obs o&#xd;\n              INNER JOIN patient ON o.person_id = patient.patient_id &#xd;\n              INNER JOIN person ON person.person_id = patient.patient_id AND person.voided = 0&#xd;\n              where person.gender = &apos;M&apos;&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n            -- TB Treatment Outcome&#xd;\n             and o.person_id in (&#xd;\n               select o.person_id&#xd;\n               from obs o&#xd;\n               where o.concept_id = 3792 and o.value_coded = 3794&#xd;\n              and o.voided = 0&#xd;\n              )&#xd;\n&#xd;\n            Group by o.person_id) AS TB_TESTING&#xd;\n)&#xd;\n</query>\n</org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition>','2024-07-16 19:10:32',4,'2024-07-16 19:28:03',4,0,NULL,NULL,NULL,'b52e33c9-1fd6-4370-a942-105bc72c739f'),(2917,'TB Males and Not Evaluated','TB Males and Not Evaluated','org.openmrs.module.reporting.cohort.definition.CohortDefinition','org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.cohort.definition.SqlCohortDefinition id=\"1\" uuid=\"48f1f3a4-2bd0-46f4-b398-d1fc26822b2a\" retired=\"false\">\n  <name>TB Males and Not Evaluated</name>\n  <description>TB Males and Not Evaluated</description>\n  <creator id=\"2\" uuid=\"c1c21e11-3f10-11e4